window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_008"]={"n":"杨士奇","dyn":"明","poems":[{"t":"杨白花","f":"古风","c":["杨白花，逐风起。","含霜弄雪太轻盈，荡日摇春无定止。","楼中佳人双翠颦，坐见纷纷渡江水。","天长水阔花渺茫，一曲悲歌思千里。"]},{"t":"巫山高","f":"七言律诗","c":["巫山高高十二峰，连崖叠巘重复重。","昔时阳台下神女，翠敛红销空处所。","朝朝峡里望氛氲，可怜犹似作行云。","相思已下沾裳泪，况复猿啼不可闻。"]},{"t":"寄尤文度 其一","f":"五言律诗","c":["苦忆尤参议，投簪养病劳。","卑栖人总厌，閒散自能高。","厨却胡奴米，门深仲蔚蒿。","平生冰雪意，犹足重吾曹。"]},{"t":"闻角","f":"五言律诗","c":["风静周庐夕，营门角起愁。","不须三弄彻，对月泪先流。","杨柳飘还合，梅花落未休。","乡心已无限，何必在边州。"]},{"t":"赋得沧浪送陈景祺之襄阳知府","f":"五言律诗","c":["汉水带襄城，沧浪旧有名。","分符来五马，如练照双旌。","济涉思为楫，听歌想濯缨。","须令郡人说，堪比使君清。"]},{"t":"送给事中姚山赴河南佥宪","f":"五言律诗","c":["观风在激扬，今喜擢苏章。","袖有银台笔，衣含玉殿香。","河流明宪节，嵩岳对公堂。","想见澄清日，歌声满洛阳。"]},{"t":"送胡元节广西宪使","f":"五言律诗","c":["骢马赤茸鞦，临岐嘶未休。","朝廷用儒雅，风纪得才猷。","天远三湘外，霜含八桂秋。","贪渔嗟薄俗，表率在名流。"]},{"t":"晚同宗豫先归诣清河途中寄勉仁弘济","f":"七言律诗","c":["载书先发赴前营，雨浥飞埃晚更晴。","人喜望家三舍近，马知归路四蹄轻。","风飘点点溪花送，日射行行野树明。","却忆今宵毡帐底，翠壶红烛伴双清。"]},{"t":"从游西苑","f":"七言律诗","c":["广寒宫殿属天家，晓从宸游驻翠华。","琼液总颁仙掌露，金支皆插御筵花。","棹穿萍藻波间雪，旗飐芙蓉水上霞。","身世真超人境外，玉盘亲捧枣如瓜。"]},{"t":"邳州城下夜雨","f":"五言绝句","c":["薄暮风色寒，移舟宿前渚。","欹枕不成眠，孤篷夜来雨。"]},{"t":"夜发清江口","f":"五言绝句","c":["日落烟水寒，解缆清江渚。","中夜北风来，相送潭州去。"]},{"t":"夹沟遇邑人问家信","f":"五言绝句","c":["闻道故乡来，辞家今远近。","恐有南京书，停舟试相问。"]},{"t":"江南行 其一","f":"五言绝句","c":["家住横塘口，船开去渐遥。","归时不愁暮，出浦正乘潮。"]},{"t":"江南行 其二","f":"五言绝句","c":["偶来长浦里，相伴采莲归。","并船打两桨，溅水湿罗衣。"]},{"t":"古意答伯阳","f":"五言绝句","c":["河洲双鸳鸯，流荡还相逐。","皎皎白杨花，风吹不相续。"]},{"t":"发淮安","f":"七言绝句","c":["岸蓼疏红水荇青，茨菰花白小如萍。","双鬟短袖惭人见，背立船头自采菱。"]},{"t":"扈从巡边至宣府往还杂诗 其一","f":"七言绝句","c":["北斗初高月未斜，五更清露净尘沙。","道边丛绕炉香立，多是耆人候翠华。"]},{"t":"扈从巡边至宣府往还杂诗 其二","f":"七言绝句","c":["居庸关中四十里，回冈复岭度萦纡。","道傍石刻无人识，尽是前朝蒙古书。"]},{"t":"扈从巡边至宣府往还杂诗 其六","f":"七言绝句","c":["红叶离离净可书，绿渠流水见游鱼。","老臣虚拜貂裘赐，一路阳和护属车。"]},{"t":"扈从巡边至宣府往还杂诗 其八","f":"七言绝句","c":["山望鸡鸣势入云，下循仄径棘纷纷。","不辞涉险观遗碣，重是欧阳太史文。"]},{"t":"扈从巡边至宣府往还杂诗 其九","f":"七言绝句","c":["关外初冬似早春，僧房犹见菊花新。","时平扈从巡边塞，宣府回銮只二旬。"]},{"t":"扈从巡边至宣府往还杂诗 其十","f":"七言绝句","c":["怀来城外夜微雪，风送轻寒初著身。","明旦马前红一色，回军共试赐衣新。"]},{"t":"以绢问张子俊求画","f":"七言绝句","c":["梦忆衡庐紫翠重，结巢须倚玉芙蓉。","天恩未便教投绂，一幅鹅溪更恼公。"]},{"t":"入蓟州界","f":"七言绝句","c":["云净天清紫翠浮，好山消尽越乡愁。","行人如有江南兴，马上题诗入蓟州。"]},{"t":"宣德丙午谒二陵 其一","f":"七言绝句","c":["去年侍从谒长陵，此日重来恸倍增。","春柳春花浑似昔，献陵陵树复层层。"]},{"t":"宣德丙午谒二陵 其二","f":"七言绝句","c":["君恩追忆不胜哀，老泪乾枯病骨摧。","陵下一来肠一断，馀生知复几回来。"]},{"t":"清明有感","f":"七言绝句","c":["西江南望渺天涯，岁岁清明不在家。","荡日飘风无定著，乱人情思是杨花。"]},{"t":"题少保杨澹庵江乡归趣图 其七","f":"七言绝句","c":["巴陵西畔楚江分，曾泛湖波望岳云。","借得君山小龙笛，月明吹向洞庭君。"]},{"t":"江上早行","f":"七言绝句","c":["汉阳楼上鼓初稀，烟柳昽昽一鹊飞。","乘月不知行处远，满江风露湿人衣。"]},{"t":"三十六湾","f":"七言绝句","c":["湘阴县南江水斜，春来两岸无人家。","深林日午鸟啼歇，开遍满山红白花。"]},{"t":"题鄂渚赠别图送人归庐陵 其一","f":"古风","c":["鹦鹉江中红树，凤凰城里青山。","借问来游几日，秋水兰舟独还。"]},{"t":"题鄂渚赠别图送人归庐陵 其二","f":"古风","c":["客游黄鹤矶畔，家住金鱼浦前。","心似波间明月，随君先过螺川。"]},{"t":"咏读书庄","f":"七言绝句","c":["清流城北读书庄，旧隐诗书岁月长。","玉署归来春昼永，松门流水落花香。"]},{"t":"赐游东苑诗九章 其一 斋宫","f":"古风","c":["严严斋居，清庙之侧。","高明澄肃，靡雕靡饰。","帝时恭默，对越秉诚。","有赫鉴观，锡祚万龄。"]},{"t":"赐游东苑诗九章 其二 圆亭","f":"古风","c":["翼翼圆亭，法象上玄。","至朴不斲，适于自然。","帝时端居，游思太极。","茅茨土阶，允配尧德。"]},{"t":"赐游东苑诗九章 其三 方沼","f":"古风","c":["凿方甃池，制仪坤舆。","㵾乎湛渊，浑涵太虚。","有丛其植，有群其潜。","文王灵沼，圣人同心。"]},{"t":"赐游东苑诗九章 其四 翠渠","f":"古风","c":["湜湜澄渠，天汉其宗。","凝如碧玉，衍如翠虹。","发循宸居，流润下土。","惟帝德施，周于天下。"]},{"t":"赐游东苑诗九章 其五 黛峰","f":"古风","c":["苍乎凌波，如戴神鳌。","节乎峻严，如瞻崧高。","上出氿泉，亦时出云。","惟帝乐之，允契圣仁。"]},{"t":"赐游东苑诗九章 其六 灵泉","f":"古风","c":["天一所生，而出异源。","或喷于龙，或跃在山。","智巧之妙，浑然天成。","周流畅达，允怡圣情。"]},{"t":"赐游东苑诗九章 其七 御苑","f":"古风","c":["群植斯蕃，盎乎凝春。","中和之推，时育之仁。","惟帝之仁，始内及外。","保合太和，爰暨四海。"]},{"t":"赐游东苑诗九章 其八 嘉鱼","f":"古风","c":["喁喁洋洋，以游以泳。","洪纤异群，咸适厥性。","爰适得所，莫敢以罟。","矧帝之氓，而敢以侮。"]},{"t":"赐游东苑诗九章 其九 瑞匏","f":"古风","c":["清云布阴，翠虬萦条。","宛宛双绶，交系于匏。","至和融□，毓奇斯植。","表瑞灵苑，式昭帝德。"]},{"t":"芳桂堂诗为杨御史作","f":"古风","c":["连绻桂树，罗生堂前。","自我植之，郁其栾栾。","百卉具腓，高秋始华。","湛露瀼瀼，芳馨满家。","有生必荣，岂必在早。","不与众竞，如彼有道。","坚贞之节，四时不渝。","宜尔君子，岁晏同娱。"]},{"t":"题雪窗兰","f":"古风","c":["粲粲幽兰，在彼岩阿。","春阳流辉，惠风布和。","粲粲幽兰，在岩之下。","懿彼白石，静言偕处。","兰生幽深，孰知其芳。","自我贞素，不知奚伤。","予怀芳馨，远莫致之。","援琴弹丝，薄写我私。"]},{"t":"题勉仁学士草虫图","f":"古风","c":["种瓜于田，既勤且劬。","弃瓜于道，遽厌其馀。","群趋于腐，为蚁斯足。","虫睨于傍，其亦有欲。","物各付物，天道流行。","动植之微，可玩生成。"]},{"t":"云山幽居图","f":"楚辞体","c":["翠岭兮岧岧，白云兮洋洋。","渺澄波兮滉瀁，交春木兮芬芳。","息有庐兮济有梁，田可穑兮原可以桑。","蹇驽足兮周行，时不处兮岁将晏，遵东皋兮聊彷徉。"]},{"t":"颜谷辞","f":"楚辞体","c":["山青青兮郁盘，又英英兮白云。","蔼嘉树兮颜谷，流泸水兮澄源。","源左右兮上有原田，鱼潜泳游兮禾麻秀蕃。","谷中之人兮连居接门，一姓盛大兮伯叔弟昆。","不斲为饰兮朴之惇，夕还诵弦兮画行耨耘。","嗟嗟夫子兮超哉拔伦，金玉为质兮组绣文。","握廉秉节兮服义仁，袆椒茝兮有馥其身。","逍摇徜徉兮以秋以春，胡不永世兮溘飘尘。","嗟嗟夫子兮身去名存，怀不可见兮空可闻。","世纷纷兮华薄群，安得硕人兮永亲。","空望颜谷兮涕泗沾巾。"]},{"t":"培山书屋辞为金学士作","f":"楚辞体","c":["崔嵬兮培山，窈窕兮幽居。","前峨峨兮芳林，俯溜溜兮澄渠。","鸟交交兮和鸣，云英英兮敛舒。","山中人兮采芝，聊栖迟兮恬以愉。","集夫容兮为衣，杂兰椒兮佩袆。","列左右兮图书，以旦以夕兮不知渴饥。","爰稽古兮唐虞，惟孔颜兮吾之师。","世远兮心同，游志千载兮乐且无期。","静与动兮有时。","承景运兮翱翔，登金门兮玉堂，焕云汉兮发天章。","奉圣君兮九五，弘化理兮道弥光。","眷山中兮故居，渺予怀兮能忘。"]},{"t":"退轩辞","f":"楚辞体","c":["芝橑兮桂户，山阿兮水澨。","云鳞鳞兮石磊磊，交松萝兮延薜荔。","华纷纷兮袭予，春之兰兮秋之蕙。","羌何为兮独往，舒萧散兮泄泄。","念盛衰兮有时，盍满盈兮豫戒。","抚年岁兮将晏，日斯征兮月斯迈。","纷骎骎兮忘归，余何为兮靡止。","揽吾辔兮旋轸，返吾车兮旧里。","恬澹兮以休，全之兮终始。","怀夫子兮高风，邈游心兮千载。"]},{"t":"题画","f":"楚辞体","c":["延白云兮山中，荫乔木兮水澨。","之君子兮空谷，憺逍遥兮终岁。"]},{"t":"送尤文度归吴中","f":"五言古诗","c":["我友整遐装，誓将起旋归。","平明发城邑，率彼东路驰。","爰与二三子，祖饯临郊岐。","中觞趣分袂，恨恨使我悲。","嘤鸣求其友，窃慕伐木诗。","平生携手好，何为中仳离。","行当阻川岫，安得睹光仪。","情敦思苦深，久要谅不遗。","各言崇令德，庶保黄发期。"]},{"t":"宿蔡胄秀才馆中","f":"五言古诗","c":["肃肃高馆静，寥寥夜何其。","天汉当西楼，流月正徘徊。","仰观列宿悬，俯视平湖漪。","良时奉嘉会，执手叙所怀。","清言以适意，留连忽忘疲。","且当娱兹夕，明晨与子辞。"]},{"t":"夏夜用谢宣城韵答陆伯阳","f":"五言律诗","c":["连柝起高城，微钟飘广陌。","徘徊夏夜长，怀人未眠客。","林风有馀清，庭月流虚白。","结思渺城南，如何违促席。"]},{"t":"题蔡骐练林先冢图","f":"五言律诗","c":["犹诵过庭教，俄成陟岵悲。","尘生五色服，空忆上堂时。","新冢楸梧绿，深春雨露滋。","含情已无限，更咏蓼莪诗。"]},{"t":"杂诗三首赠陆伯阳 其一","f":"五言古诗","c":["中夜不能寐，揽衣步前楹。","员灵肃清穆，凉风飒以兴。","秋虫亦何悲，流响于阶庭。","徘徊感节变，绵绵忧思生。","四时掷人去，忽如流电惊。","立身庶及时，僶勉苦无成。","窃愁盛年迈，将与秋草并。","念之不得言，俛默伤我情。"]},{"t":"杂诗三首赠陆伯阳 其二","f":"五言古诗","c":["翩翩孤鸿雁，遥遥鸣且飞。","寒阴翳洲渚，日暮将安归。","栖栖客游子，独往临路岐。","薇食聊自甘，卒岁仍无衣。","达士守固穷，遑恤寒与饥。","先民有遗言，乐命复奚疑。"]},{"t":"杂诗三首赠陆伯阳 其三","f":"五言古诗","c":["南国有佳人，皎皎怀芬芳。","被服纨与绮，五色何煌煌。","容仪希世有，音响流四方。","我怀往从□，晨征越河梁。","喜遇诚独难，欢爱两相当。","愿得常携手，终岁不相忘。"]},{"t":"汉江夜泛","f":"五言古诗","c":["泛舟入玄夜，奄忽越江干。","员景颓西林，列宿粲以繁。","凝霜飞水裔，回飙荡微澜。","孤鸿从北来，哀鸣出云间。","时迁物屡变，游子殊未还。","短褐不掩胫，岁暮多苦寒。","悠悠念行迈，慊慊怀所欢。","岂不固时命，苦辛诚独难。","感彼式微诗，喟然兴长叹。"]},{"t":"将归庐陵送朱智南上","f":"五言古诗","c":["朔风日云厉，凛凛天雨霜。","征夫念行役，游子思故乡。","宿昔累欢宴，一旦异飞翔。","晨兴戒徒旅，各已俨成装。","齐驱上河桥，祖送盈路傍。","驾言从此辞，俯仰情内伤。","流波逝东渚，浮云越西冈。","去去踰万里，各在天一方。","嘉遇讵可期，乖阙谅难忘。","惟当保贞素，随时以自臧。"]},{"t":"归程阻风","f":"五言古诗","c":["凄风起西北，日夕满川坻。","寒云结重阴，曜灵隐高晖。","惊涛浩纵横，零雨何霏霏。","行人念往路，怫郁多悲怀。","延领望故乡，誓将赴东归。","临津不能济，伫立以徘徊。","安得凌风翰，奋绝起高飞。"]},{"t":"同蔡骐尚远尤安礼文度朱智仲礼杨翥仲举蔡胄用严游东山得剪字","f":"五言古诗","c":["步出城东门，逍遥望云巘。","累月怀佳游，兹晨遂登践。","梵宇绕层阿，飞楼凌绝岘。","方塘涵湛碧，乔林茂敷衍。","繁翳幽莫通，丰茸纷不剪。","攀磴穷高跻，缘径屡回转。","是时微雨收，轻霞澹舒卷。","睇遥素横川，俯夷绿盈畎。","陟降体自便，顾睇心已缅。","况接旷士言，复偶释子辩。","析空理弗昩，违喧抱逾展。","何因此间栖，永令浮虑遣。"]},{"t":"雪中饮陆伴读斗室","f":"五言律诗","c":["新斋坐閒敞，瑞雪晃清妍。","寒消碧窗外，光动玉琴前。","淹留酌甘醴，朗咏瑶华篇。","自然纷虑静，即此对群仙。"]},{"t":"送蔡胄秀才归四明","f":"五言古诗","c":["仆夫起严装，白露晨未晞。","之子思旧庐，星言赴旋归。","路指东海陬，翩翩忽如飞。","羁鸟怀并栖，须臾失相依。","仰首望鸾鷟，何时接光辉。","山川信缅邈，宿昔分不违。","无为金玉音，使我长歔欷。"]},{"t":"送宗上人归君山","f":"五言律诗","c":["初维鄂渚楫，又上岳阳舟。","行住皆无系，身轻波上沤。","寺连龙井近，山压洞庭流。","回望王城里，还来持钵游。"]},{"t":"送性上人归巴陵独松庵","f":"五言律诗","c":["老襌心湛寂，身被七条衣。","端坐无言说，谁知精道机。","初来鹦渚见，又问岳阳归。","应忆松庵下，诸僧候锡飞。"]},{"t":"题郭氏溪南斋","f":"五言古诗","c":["幽人谐静适，结宇临溪园。","溪流清且深，逶迤带平村。","榆柳植我楥，远岫列我门。","碧筱播春阴，芙蓉丽秋暾。","远绝往还迹，遂忘廛市喧。","坐玩孔氏书，覃思古人言。","玄理日有得，可以祛尘昏。","素琴虽无弦，旨酒常在尊。","意至时有适，登高睇澄源。","讴吟发舒散，一写中郁烦。","栖迟固夙尚，贵贱命攸存。","知分吾所安，谁谓轻华轩。"]},{"t":"斗湖道人诗","f":"五言古诗","c":["家临斗湖滨，门对斗湖上。","明镜影香台，文波绣仙氅。","诵经无辍口，谭道若指掌。","为霖从潜虬，飞符驱魍魉。","止水涵湛然，可以喻心想。","一谢湖边人，终年罢来往。"]},{"t":"樵云诗","f":"五言古诗","c":["悠悠南山云，素心澹相似。","偶托樵采迹，遂隐山云际。","云中有灌木，四散枝叶繁。","薄剪去云翳，讵令伤本根。","昨朝买斧来，暂入庐陵县。","五马出辉煌，低头愧相见。","芙蓉荡晻霭，环洲亦氛氲。","一返伐木处，丁丁谁得闻。"]},{"t":"题施员外画","f":"五言律诗","c":["久旷山水游，披图适心目。","远岫云外青，清潭千丈绿。","芳尊集幽舫，春鸟鸣高木。","茅屋是谁家，门无往来躅。"]},{"t":"送胡子澄遂安知县","f":"五言古诗","c":["初日丽金闺，香风含玉殿。","之子承湛恩，铜章宰花县。","匆匆下长浦，靡靡经芳甸。","驰情在民瘼，铭心答天眷。","嗟予重朋侣，三春不相见。","偶聚还暌违，临岐空恋恋。"]},{"t":"送曾仲修训导赴新淦","f":"五言古诗","c":["玉笥抗云汉，金川汎晴虹。","山水互明丽，照耀城邑中。","连延开绮构，崔嵬表黉宫。","俎豆谨常祀，弦歌曰沨沨。","君子抱德艺，出教属时雍。","高斋振木铎，济济来游从。","峨冠讲周孔，表率诚在躬。","兹晨饯发轫，飘拂乘长风。","因结故园想，怅望南飞鸿。"]},{"t":"永丰曾氏龙潭书屋","f":"五言古诗","c":["开轩面澄潭，潭水绿于染。","其下蟠蛟虬，四时兴有渰。","嘉树罗葱旧，烟霞互舒敛。","晴漪漾春牖，凉飔含暑簟。","俗辙谢经过，书卷恒不掩。","探微心有得，行素道无歉。","消摇视天宇，油云驰冉冉。","庶跂沂上乐，谁当叹与点。"]},{"t":"送石彦诚徐闻知县","f":"五言古诗","c":["朔风起严冬，凛凛亘晨暮。","我友整行装，迢遥戒长路。","祖饯集朋俦，暌离黯情绪。","念子敦德义，雍容古人度。","饮水必澄源，涉蹊无枉步。","伊昔丞小邑，□婺乐仁恕。","朅承公车徵，同游玉堂署。","遂荷迁秩荣，还婴理民务。","扬舲溯江湖，停舻展丘墓。","行行睇岭海，稍稍侵烟雾。","恭惟承宣重，岂复驱驰虑。","会兴中牟治，终流单父誉。","嗟予托久要，惭乏赆者具。","惟期保贞素，永副心所慕。"]},{"t":"竹间诗为李伯葵赋","f":"五言古诗","c":["夙志在间适，结宇城东隅。","脩竹何漪漪，丛生罗庭除。","虽无灌木荫，清云郁纷敷。","四时自苍翠，寒暑常不渝。","天风起旦夕，绕屋含笙竽。","何必来羊求，静阅古人书。","至理会有得，陶然倾一壶。","油油天壤内，安知忧与虞。"]},{"t":"晚过扬州","f":"五言古诗","c":["朝辞仪真坝，暮过广陵城。","前汀交瞑色，远渡闻钟声。","微微初月辉，湛湛天宇澄。","仰首望北辰，众星粲然明。","商飙从西来，忽忽凉思生。","掩篷坐终夕，嘅然念脩程。"]},{"t":"邳州","f":"五言律诗","c":["岧岧下邳城，浩浩河流骛。","伫立思徘徊，古人今何处。","船头见青山，山下连烟树。","白鸟自幽间，双飞背人去。"]},{"t":"歌风台","f":"五言古诗","c":["汉皇靖宇内，六合承统御。","万乘还沛中，龙旗翼銮辂。","兴情侧微曰，张筵会亲故。","酒酣歌大风，气势排云雾。","往绩示殊伟，丕图怀永固。","众起称万寿，弘哉帝王度。","宽仁运乾刚，四百隆鸿祚。","至今千载馀，光华垂竹素。","崇台面河曲，穹碑倚烟树。","我来属秋杪，维舟久瞻顾。","矫首芒砀云，澹澹青空曙。"]},{"t":"同金公素自枣林闸步至鲁桥望邹峄山","f":"五言古诗","c":["舍舟步平皋，名山望邹峄。","元气下磅礴，黛色凌空碧。","千里瞻神秀，群峰避孤特。","常时济物功，有渰弘灵泽。","伟兹造化奇，无应辱秦刻。","经旬坐局蹐，一览豁胸臆。","何当跻绝顶，旷然见溟渤。"]},{"t":"胡学士山居六景 其一 芳洲春草","f":"五言律诗","c":["窈窕河上洲，芊绵芳草碧。","常与幽趣会，消摇散轻策。","一往白玉堂，经年无履迹。","望望楚江西，烟波渺春色。"]},{"t":"胡学士山居六景 其二 墨潭秋月","f":"五言律诗","c":["峨峨墨潭山，纯浸潭水碧。","高秋明月悬，照见蜿蜒黑。","忆昔乘桂舟，沿洄弄晴夕。","同时钓游侣，惆怅千里隔。"]},{"t":"胡学士山居六景 其三 沧江烟雨","f":"五言律诗","c":["忆昔沧江上，烟雨时冥冥。","遥隐江波白，复含江树青。","凫鹥近屡见，渔歌清可听。","何必抚图画，然后怡性灵。"]},{"t":"胡学士山居六景 其四 天玉泉石","f":"五言律诗","c":["岧峣天玉峰，高出南斗上。","自昔采灵芝，托身此萧爽。","扫石青云生，鸣琴答泉响。","已趋金门直，犹结丹霞想。"]},{"t":"胡学士山居六景 其五 石屋晴澜","f":"五言律诗","c":["石冈俯川澨，嵌岩下成屋。","天际薰风来，轻波荡文縠。","上有相知人，萧散出尘俗。","永念故年时，扁舟往来熟。"]},{"t":"胡学士山居六景 其六 螺冈晚照","f":"五言律诗","c":["西望金螺峰，临夕宜返照。","川明天光净，潇洒若员峤。","振衣援紫萝，凌高发清啸。","解组如有期，吾侪亦同调。"]},{"t":"题富春柴桑二图 其一","f":"五言古诗","c":["圣人抚昌运，四海洽时雍。","间对桐江水，湛然心迹同。","怀仁以辅义，百世仰高风。"]},{"t":"题富春柴桑二图 其二","f":"五言古诗","c":["琐琐厌形役，飘飖赋归休。","开轩面南山，黄花亦映秋。","酒熟自可漉，白社吾何求。"]},{"t":"送进士彭琉赴政和知县","f":"五言古诗","c":["霜露凋卉木，朔风激郊原。","之子戒行迈，相送城南门。","驰车指瓯越，靡靡无停奔。","山川间道路，气序异凉温。","仳离方自兹，曷舒中郁烦。","念子同乡彦，令质挺玙璠。","劲节夙所尚，古道矢弗谖。","宾兴属昌期，出宰膺明恩。","善政崇教育，化理由身惇。","行矣懋树立，以副平生言。"]},{"t":"送康孔高纪善还乡","f":"五言古诗","c":["泽暄冰始泮，林霁雪犹积。","肃肃征辆驰，翩翩城南陌。","以我同旅人，看君独归客。","青春别乡县，白首滞京国。","念此增怀思，何由尽离席。"]},{"t":"题王性存画","f":"五言古诗","c":["辉辉山水丽，云树蔼青苍。","髣髴永嘉郡，环临西射堂。","朝回书阁静，对此故难忘。"]},{"t":"题芦雁","f":"五言律诗","c":["北风吹葭菼，轻云覆洲渚。","万里雁门来，优哉此栖处。","南州少霜霰，中田剩禾黍。","大夫不用贽，虞人焉慕汝。"]},{"t":"雨中寄蒋用文院判","f":"五言律诗","c":["北风吹行云，凌虚俄澶漫。","城上朝雨悬，渠里寒潮断。","退朝出天阙，怀贤坐林馆。","趋谒当何时，联珂待清旦。"]},{"t":"送王彦鼒还南京","f":"五言古诗","c":["旭日照圻甸，北风寒路岐。","萧萧骢马鸣，矫矫将南驰。","停辔仍踟蹰，还顾与我辞。","念子我同里，且有中和资。","不见已三载，乖违复在兹。","山川缅迢递，何以赠仳离。","白圭易为瑕，素服易为缁。","勉哉慎厥终，以副平生期。"]},{"t":"送陈正言知府归云南","f":"五言古诗","c":["日照东南隅，门有车马宾。","飞盖映华毂，高鞍镂素银。","别我将有适，念我夙所亲。","山川万里途，远行多苦辛。","何以赠暌违，承流贵及民。","谦谦君子德，恂恂长者仁。","恶旨好善言，昔有大圣人。","稽古以力行，敬哉愿书绅。"]},{"t":"题勉仁学士岁寒图","f":"五言古诗","c":["岁晏朔风劲，雨雪何霏霏。","原陆莽萧条，百卉具已萎。","郁郁凌云松，猗猗脩竹枝。","皎皎林间梅，鲜葩亦已披。","并秀以相依，况与瑶华宜。","潇洒清白居，足怡君子怀。","艳阳耀丹萼，赪霞映紫蕤。","当春岂不时，不及商飙摧。","谅非冱寒节，曷表贞素姿。","永托金石契，迟暮以为期。"]},{"t":"吕主事泰山春云图","f":"五言古诗","c":["东岱五岳宗，雄誇齐鲁疆。","磅礴据深广，峻极凌穹苍。","春云起肤寸，乘风歘飘扬。","弥谷乍蔼蔼，浮空忽洋洋。","日观不可辨，环道杳茫茫。","若人尚父裔，家居岱之阳。","诗书际明世，冠绂趋朝行。","引领日东眺，含思在高堂。","不闻泰山云，作霖雨八荒。","僶勉励所志，以副君亲望。"]},{"t":"送廖主事还南京","f":"五言古诗","c":["蓟门宿雨霁，西山翠如扫。","送子出城闉，看山还懆懆。","念子匡庐秀，秋官致身早。","皎洁瑚琏质，岁久声逾好。","昔晤愧匆匆，兹别仍草草。","百年几离合，不觉壮已老。","斗酒慰羁颜，商歌写幽抱。","贵贱各有分，贫富安足道。","何以赠暌违，清名逝为宝。"]},{"t":"题伯牙子房子猷太白四图 其一","f":"五言律诗","c":["八音丝为尊，由来识者难。","邂逅两相契，何辞为君欢。","妙绝山水操，殷勤一再弹。","相知苟不尽，徒贻后时叹。"]},{"t":"题伯牙子房子猷太白四图 其二","f":"五言律诗","c":["兴王必有佐，授道自有师。","长者幸赐教，鞠躬敢辞卑。","向来一编书，帷幄坐见施。","从容成功退，去谒谷城祠。"]},{"t":"题伯牙子房子猷太白四图 其三","f":"五言律诗","c":["都城二三月，名花艳芳春。","车马填九衢，歌钟动四邻。","焉知竹林下，潇洒绝纤尘。","兴至时独造，清风含八垠。"]},{"t":"题伯牙子房子猷太白四图 其四","f":"五言律诗","c":["夫容九叠屏，上有瀑布悬。","浩浩不可极，银河泻青天。","览之登高咏，超然锦袍仙。","观物当求源，我欲升其巅。"]},{"t":"题髑髅图","f":"五言律诗","c":["漆园傲世者，放言出糟粕。","大观天地间，玩化以嘲谑。","昼夜自恒理，生死等酬酢。","存顺而殁宁，焉往非吾乐。"]},{"t":"斋宿听周编脩弹琴","f":"五言古诗","c":["群处谅有适，单居恒鲜欢。","乐只众君子，斋沐此盘桓。","华缸照绮席，香气蔼焚兰。","爰理峄阳桐，为我三四弹。","迟迟写适意，宛宛含幽叹。","怡我中和抱，涤我沉郁端。","所怀在古操，焉知清夜阑。"]},{"t":"李孟昭挽诗","f":"五言古诗","c":["月落城乌啼，风凄寒露繁。","轜车戒明发，祖送城南门。","挽者皆丧歌，增我中郁烦。","向来相知人，古道子克敦。","荆玉抱贞洁，楚兰含幽芬。","周行慎素履，雅义播清文。","表俗赖耆俊，启迪资多闻。","德业之所造，诜诜各高鶱。","如何乘化迁，奄忽在兹晨。","渺渺东去波，翩翩南飞云。","铭旌望已遥，涕泪空沾巾。"]},{"t":"游白云观 其一","f":"五言古诗","c":["仲春气清和，招携适所适。","扬策指灵阿，联镳度脩陌。","山开画障明，川含浮练白。","真境历逶迤，玄关敞虚寂。","既歆道气澄，缅望尘氛隔。","金鼎窥神丹，玉壸漱云液。","潇洒两仙童，妙歌出金石。","石髓会当逢，琼芝庶可食。"]},{"t":"游白云观 其二","f":"五言古诗","c":["云台远人境，升高适奇观。","西瞻五华秀，东顾绿漫漫。","坐玩金夫渠，流咏翠琅玕。","祥飙含桂树，仙禽唳石坛。","闻昔有至士，于此养神丹。","飞盖一朝举，翱翔紫霞端。","道高用自超，志一功匪难。","脱屣当何时，相从命青鸾。"]},{"t":"朱中书为余写溪山幽趣彦鼒南还遂以赠之并题诗云","f":"五言律诗","c":["山翠拂云清，溪光湛虚碧。","林亭揽澄爽，超然适所适。","为有江南趣，持赠江南客。","公暇或披图，还应忆江北。"]},{"t":"西城宴集","f":"五言古诗","c":["置酒清轩下，衣冠聿来萃。","皆我同朝士，各有禄与位。","昩爽趋在公，日夕还未至。","属兹岁除暇，一觞聊共醉。","匪徒展间阔，亦复解劬瘁。","平生所相好，岂不在名义。","中和诚可则，贪鄙诚可戒。","僶勉以自强，前脩庶足跂。"]},{"t":"送曾侍读归省","f":"五言古诗","c":["都城春如暄，澹荡风光好。","雪罢冰亦泮，长空曀如扫。","文澜漾太液，晴霞涌琼岛。","顾我同署良，行迈何草草。","高堂念亲癠，夙夜心如捣。","岂无一觞酒，为子饯远道。","去乡三十年，昔壮今已老。","同邑不同归，临岐增懆懆。"]},{"t":"题王孟杨检讨鹡鸰图","f":"五言古诗","c":["平生急难意，怅咏鹡鸰诗。","绿水夫渠后，清秋独立时。","王家好兄弟，对尔自怡怡。"]},{"t":"早发桃源","f":"五言古诗","c":["凌晨牵滩濑，将暮泊沙渚。","沙头卖酒家，好者酽于乳。","舟子沽大盎，相共解劳苦。","饮酣意气豁，放歌杂嘲语。","中夜风水声，倏如飒飞雨。","鸡鸣棹讴发，挂席逐前侣。"]},{"t":"题刘逸人乐耕卷","f":"五言古诗","c":["理生虽异业，居世皆有务。","治本既在兹，食力余所慕。","九扈春始鸣，兴言向田墅。","初来正沟塍，爰方艺禾黍。","虽有耘耨劳，三时足甘雨。","岁功聿已成，屡丰报田祖。","储贮何必多，取具充寒暑。","有酒可同欢，时时会邻父。","既醉去悠然，登高睇平楚。","一为击壤谣，游心缅千古。"]},{"t":"雪夜胡学士载酒见过剧饮四鼓乃罢明日辱诗次韵奉答","f":"五言古诗","c":["开岁已旬浃，消摇休暇中。","良宵雪初霁，玉色明房栊。","君子枉青盼，眷言写欢悰。","豁达高世情，脱略尘虑空。","从者陈豆笾，中筵粲鲜醲。","虽云朋侣稀，屡促觞酌崇。","旋舻诮王子，投辖嗤孟公。","气合自淹留，清言益沨沨。","芬馨逼兰茝，和洽谐丝桐。","云巾耀朱氅，初疑降青童。","听歌以成醉，复如对南翁。","倏忽踰夜分，起视月胧胧。","参差仰象纬，冲融散条风。","鸡鸣戒朝谒，又促明发同。"]},{"t":"题陈叔起画","f":"五言古诗","c":["青山带长林，虚亭夐萧爽。","溪水流玉虹，天光涵滉瀁。","頫洁淹澹游，塞芳惬幽赏。","邈尔高世怀，脱略浮云上。","惟有同心人，扁舟日来往。"]},{"t":"舟次安山驿尚书蹇公奉敕南归仆与公素北行临岐执别情见乎辞","f":"五言律诗","c":["同来不同归，临分俱惨戚。","昨日别家情，何如此时剧。","悠悠北逝川，杳杳南飞翼。","天寒道路遥，相望恒相忆。"]},{"t":"题孙给事画","f":"五言古诗","c":["山水谐素心，幽居托林樾。","日暮澹无营，超然孤兴发。","时携绿绮琴，坐待青天月。"]},{"t":"道傍杏花一树盛开","f":"五言律诗","c":["碧草初出地，杏花红满枝。","粲粲耀晨旭，盈盈娇路岐。","称我庭阶赏，植远不可移。","玩之未忍别，念当长育时。"]},{"t":"莲叶舟图","f":"五言律诗","c":["若人有道者，脱迹凡尘中。","身轻御一叶，消摇若乘空。","仰接三光近，前望十洲通。","超然游汗漫，不与世人同。"]},{"t":"正月六日偕邹汝舟庶子金用诚司直张伯原司谏过姚友直洗马饮","f":"五言古诗","c":["绪风回微和，青阳肇新岁。","官曹属休暇，朝簪盍交契。","虚馆坐幽深，南窗敞明丽。","清言畅素抱，至理有超诣。","醇醪写芳冽，嘉肴列甘脆。","觞行屡循环，欢洽忘次第。","既醉各已归，独淹余岂泥。","磬折辞主人，斜月皎庭际。"]},{"t":"雨中寄邹仲熙侍讲","f":"五言古诗","c":["炎月苦淫雨，抱疾坐幽居。","淖泥横隘巷，流潦溢深渠。","已绝还往迹，遂将人事疏。","时闻黄鸟鸣，交交屋东隅。","岂无斗酒酌，閒玩古人书。","兴怀在君子，夙昔同欢娱。","契谊托金兰，清德重璠玙。","跬步不可即，而况千里馀。","仰瞻白日晖，屏翳何由舒。","念离余未弭，单居子何如。"]},{"t":"送王胡两生归西昌","f":"五言古诗","c":["卞和得荆璞，献之以为珍。","当时不见信，弃置同凡珉。","任公钓东海，终岁无寸鳞。","一朝乃大获，厌足浙河滨。","丈夫遇有时，屈伸理相因。","黄金筑高台，青云登要津。","古来公卿贵，皆出畎亩民。","两生吾乡彦，读书非隐沦。","白日辞都门，归卧烟萝春。","努力崇进脩，人生岂长贫。"]},{"t":"送刘宪副之四川 其一","f":"五言古诗","c":["寒飙激原野，鸿雁纷南征。","念我同心侣，岁暮万里行。","萧萧骢马鸣，恻恻临别情。","子怀廉洁操，烱若冰壸清。","偕处诚所乐，离居非所宁。","矫首西黄鹄，何时重合并。"]},{"t":"送刘宪副之四川 其二","f":"五言古诗","c":["圣皇御四海，华夷同一仁。","命吏乖抚绥，乃有狂弗驯。","西羌近搆患，边人以忧勤。","王师振天讨，旦暮捷奏闻。","丈夫效时用，所重在安民。","肃清固职分，僶勉敷阳春。"]},{"t":"赠傅仲礼 其一","f":"五言古诗","c":["猗兰生涧阿，邈与尘氛违。","清泉带丛薄，白石相因依。","澹无艳丽质，皎洁何菲菲。","惠风日披拂，湛露晨未晞。","我乐往从之，芳馨袭满衣。","爱重不忍折，徘徊暮忘归。"]},{"t":"赠傅仲礼 其二","f":"五言古诗","c":["籊籊林间竹，上拂青云涯。","清虚挺直操，特达含贞姿。","四时来天风，锵锵韵笙篪。","常与松柏茂，岂为冰霜萎。","我乐往从之，潇洒同襟怀。","愿言笃永好，载歌有斐诗。"]},{"t":"送朱智南行","f":"七言古诗","c":["白日皦皦忽南驰，流金烁石赫炎威。","念君行役当此时，山高水深路逶迟。","岂不慊慊思东归，涉历险阻赴边陲。","翩翩飞蓬风飏之，君今一去来何时。","我但㷀㷀恒苦思，黄鹄日暮独远飞，徘徊感激泪沾衣。"]},{"t":"咏水镜同陆伯阳作","f":"七言绝句","c":["秋江无云风色静，怗怗凉波澈虚映。","佳人晓汲照新妆，不知俯首湿罗裳。"]},{"t":"陈烈妇诗","f":"古风","c":["结发为夫妻，调琴弄瑟两相宜。","生谐同室居，死愿终不离。","北风凉冽激庭树，中夜折我连理枝。","死者无复荣，存者空何为。","一双南湖锦翼鸟，雄先决起雌随之。","嗟嗟陈烈妇，金石真自持。"]},{"t":"题宝义堂","f":"七言古诗","c":["晨鸡喔喔东方明，家家营利出门行。","东驰西走纷相逐，百千取万终不足。","高堂静居无所为，团团绿树临清漪。","斑衣酌酒奉慈父，贤兄令弟皆怡怡。","人生虽贫重有道，黄金如山未为宝。"]},{"t":"寄题聂训导清碧书舍","f":"七言古诗","c":["沙羡初来识君面，旨酒高堂促欢宴。","鹦沙鹄岭遽分携，五载相思不相见。","片帆来往萧滩下，见尔滩前旧精舍。","碧嶂清江净俗氛，古木流云起炎夏。","往昔闻君此隐沦，读书学道拟终身。","山头麋鹿下窥户，沙上凫鹥不避人。","光风华月共徘徊，秋桂春兰迤逦开。","洒翰寻常舒逸兴，赋诗往往发奇才。","时来未得安肥遁，泮水桥门逐髦俊。","一官典教荷朝恩，千里思家隔乡信。","画图谁写故园春，题品兼看藻咏新。","南宫初传米员外，西掖皆知贾舍人。","我家林亭鸥浦侧，一住京华归未得。","展卷因君激素怀，更与裁诗寄相忆。"]},{"t":"送中书徐舍人归省兼问讯乃父茂良","f":"七言古诗","c":["长安门上飞雪花，长安门外客还家。","挂席龙河欲分手，寒气飘飘堕杯酒。","忆昔君自桂林归，手持彩笔趋彤闱。","诏书五色出挥洒，鸾翔凤翥生光辉。","乡里青云多故人，爱君于我更情亲。","銮坡凤沼地清切，曳绂鸣琚皆近臣。","君住文江近枫岭，数年出门违定省。","九重昨日许归宁，千里长风去俄顷。","家人岁晚俟君来，小洲寒梅花正开。","庭闱欣顾舞綵乐，邻里争看着绣回。","严君高年重清逸，我曾黄鹤楼前识。","过庭想见问京华，好为慇勤道相忆。"]},{"t":"赋得彭郎矶送王澄渊知县","f":"古风","c":["彭郎矶，连峰秀如马。","蜿蜒崒嵂凌烟霄，万里江流走其下。","彭郎何处所，大姑渺相望。","小姑云鬟亦谁见，对门一柱空青苍。","晴云寒雨朝还夕，飞鸟回翔树如箦。","楚舵吴樯日往来，江上行人几今昔。","西连彭泽县，高柳当县门。","过者纷纷忆陶令，小姑彭郎谁暇言。","去岁东来谒丹阙，矶下徘徊清兴发。","今年作令蜀西行，重过矶边还有情。","情思彭泽千载士，岂为彭郎山水清。"]},{"t":"送邓指挥","f":"古风","c":["邓将军家住文水濆。","十五袭父爵，桓桓气凌云。","二十年前尚年少，镇抚西湖到南诏。","纷纷蛮部未知名，手提一剑身横行。","去年蠢尔犹纷争，片言折之无不平。","万里归来报天子，奏对边情若流水。","御前官赏赐勋劳，象笏朱衣拜丹扆。","曙光曈曈射双阙，又奉天书戒明发。","青骢玉勒飞腾骧，楚水黔山去超忽。","云南到时花未飞，还以天恩谕远夷。","只今四海遵文教，独恃短兵何所为。"]},{"t":"送刘孝章南归","f":"古风","c":["北风吹洲渚，十月芦花飞。","经年别乡郡，寒冬方始归。","朝发通济桥，暮瞻九华岑。","乘潮荡兰桨，烟波愁我心。","家住庐陵近文水，青春为客都城里。","常时车马来故人，自拥皋比课童子。","知君力学富诗书，心似閒云随卷舒。","夜梦高堂见亲面，晓起归情疾于箭。","嗟予握手未斯须，临岐无那增烦纡。","明年春雁联翩过，莫向山中断寄书。"]},{"t":"湘潭王知县城南亲舍诗","f":"七言古诗","c":["永嘉城南亲舍幽，永嘉城上云悠悠。","三年作官慕禄养，每日思亲增别愁。","愁心常逐湘流水，直到城南海东涘。","人生乐亲贵及时，未报君恩未得归。","他年官颁五花诰，一门慈孝有光辉。"]},{"t":"吕梁洪","f":"古风","c":["吕梁洪，截流巉岩立巨石，森若虎豹蹲欹侧。","洪波中射势怒激，鸣声喧豗万鼓击。","自昔疏凿出神力，侧身望之皆辟易。","蜀江瞿塘险莫敌，百丈牵船载牛轭，棹夫操篙捷贯的。","君不见北来南去皆安流，未若人心不可测。"]},{"t":"涿州行","f":"七言古诗","c":["四郊茫茫沙草白，青山迢遥亘西北。","涿州百里近都门，北来南去无晨昏。","道边邮亭连古堠，时平不置官军守。","土墙茆屋尽耕屯，半插青帘卖新酒。","牛车辚辚冲早寒，争先槁秸输县官。","少年家家便骑射，雉兔如林不论价。","由来意气倾山冈，邂逅相逢肯相借。","伐石为碑记古人，凄凉遗刻百年存。","摩挲三叹忆盛德，路人为指楼桑村。"]},{"t":"题山水画图赠胡存渊南归","f":"古风","c":["胡先生，家住鸥江上。","半生宦游走湖海，林泉不归劳梦想。","谁为点染三尺绡，流水矶头叠青嶂。","气势峥嵘五千丈，春云如波浮滉漾。","苍松森立蛟虬蟠，白日天风动萧爽。","幽寻适意玩飞淙，散诞何人独长往。","先生抚图心懩懩，三顾之山忆仙掌。","岫幌岩扉久寂寥，芝草琅玕为谁长。","童子松阴抱琴路，想像当时旧行处。","清节书台望杳微，彷佛龙湫起烟雾。","胡先生，明日归帆暂南去，玉笥匡庐莫淹驻。","仙人卢度待公来，立把琼箫倚春树。"]},{"t":"萧子敬之官岭表以无为真人写竹求题","f":"七言律诗","c":["上清真人紫府仙，手挥玉管开云烟。","翩然骑凤溯寥廓，空有遗迹人间传。","相随万里南溟路，对座朝朝泻青露。","春雷起蛰正及时，变化须防解飞去。"]},{"t":"题刘伯埙所藏云山图","f":"七言古诗","c":["一片青山是何处，复岭层峦清可数。","春来缥缈生白云，云际连延见芳树。","雨声半夜涨溪流，隐者虚亭近水幽。","寻常书帙有真乐，况复同志来扁舟。","展图彷佛沙溪路，四十年馀记曾去。","鹅鼻峰高捲翠岚，鸡潭波静澄寒雾。","百川先生富天趣，一笑相逢豁襟度。","携酒持鱼踏白沙，共我酣唫不知暮。","先生乘云竟不归，令弟郎曹荣锦衣。","每同感慨论畴昔，还忆旧游心不违。","我愧非才侍丹阙，壮岁叨荣已华发。","投簪他日或蒙恩，更访沙溪棹明月。"]},{"t":"奉教围猎擒虎歌","f":"七言古诗","c":["山头围猎日将午，猛士如林尽貔虎。","凌云铜角一声落，驰马争前捷飞羽。","草间咆哮谁敢撄，赤手缚之如缚鼠。","柙中耽耽目如炬，犹激阴风动平楚。","生擒一虎直百兽，况乃杀获连四五。","睿情所重扬威武，奏凯归营叠笳鼓。","山村羔豚散不收，扫除民患民无忧。","欢呼仰荷储皇赐，道傍拜舞歌千秋。"]},{"t":"友松轩","f":"七言古诗","c":["苍楠翠柏连山丘，杨家绕屋青松稠。","百年雨露涵深泽，六月凉爽如清秋。","势凌千尺浮云外，黛色团团拱车盖。","阴森昼晦起蛟虬，萧瑟天风振竽籁。","若人好学怀奇姿，琼林秀出珊瑚枝。","由来孤高秉异尚，爱此挺特同心期。","结庐松下栖迟久，坐卧看松与松友。","劲操何殊处士梅，閒情未说先生柳。","才高何必老深林，清庙明堂会见寻。","惟应晚岁冰霜节，永矢平生金石心。"]},{"t":"题曾学士竹","f":"七言古诗","c":["石田筼筜不百个，满池羃羃春云阴。","神仙疑来旌节降，风雨欲动蛟龙吟。","江南种竹家家好，北来见竹如见宝。","何人胸中富淇澳，醉墨淋漓为公扫。","六月萧萧不知夏，白日长空翠如泻。","九龙山人不可作，对此阴森亦萧洒。","马头红尘千丈深，朝驰暮走积满襟。","兴来拂衣何所适，梦忆山阴脩竹林。","爱君城西卷雨轩，萧爽可以舒郁烦。","朝回借坐共永日，不须砍鲙倾金尊。"]},{"t":"送田郎中还南京武库","f":"七言古诗","c":["故人昨日南京来，兹晨还向南京去。","过门握手一相见，遽别能无黯情绪。","十载勤劳地官属，富有声华照郎署。","太平武备五兵戢，升擢还应属祈父。","功名淹速各有时，所重持身在清素。","玉堂学士子同乡，索我题诗赠行路。","是时雨霁都门道，沉雾飞埃净于扫。","日射西山如锦屏，紫翠夫渠涌琼岛。","长风吹帆发潞河，齐鲁山川坐看好。","江南岁晚还相思，努力荣名以为宝。"]},{"t":"题严氏光远堂","f":"七言古诗","c":["朴山先生天下士，明经著书遗来世。","宰相持书献天子，宠召除官列中秘。","结缨彯组青琐闱，萧散终怀荷芰衣。","明日上书乞身去，万里碧霄鸿鹄飞。","窈窕烟霞护丘壑，共羡知几返真乐。","园田旧绕柴桑居，山水清于富春郭。","又百馀岁传曾孙，束帛徵起官桥门。","峨冠正席讲周孔，诜诜俊彦罗玙璠。","两贤出处各有道，前后声华相映好。","光远堂中春不穷，乔木风烟拂晴昊。","插架牙签万卷存，焚香扫径无尘喧。","阶前暖翠看慈竹，岁岁年年蕃子孙。"]},{"t":"为行俭题五杏图赠院判蒋主善","f":"七言古诗","c":["昔时庐山仙杏花，千树万树如丹砂。","照岩炫谷总春色，功成仙驾登紫霞。","淮南蒋氏今董奉，父子声名万金重。","圣朝国医非一手，蒋氏奇能比星凤。","凤池舍人写此图，贤贵固与凡民殊。","玉堂学士经济具，何啻报功论五株。"]},{"t":"送彭御史归养","f":"楚辞体","c":["银鞍金勒赤汗骢，铁冠霜简衣绣红。","祗事明主趋九重，岂不夙夜怀匪躬。","北堂违远心冲冲，日斯征兮薄高舂。","天鉴孔迩昭微衷，鸣佩朝下篷莱宫。","惠风条畅淑景融，我出祖饯城之东。","念子夙昔言笑同，含思凝睇冥飞鸿。","虽有羽翼不能从，人之大节孝与忠。","永矢弗谖在敬恭，何以赠子岁寒松，期子誉名扬永终。"]},{"t":"为钟舍人题孟端竹","f":"七言古诗","c":["近年画竹擅名誉，九龙山人谁比肩。","歘忽乘云去无迹，但有遗墨人间传。","中书彩笺盈尺许，写赠平生凤池侣。","彷佛潇湘月下船，掀篷卧看青鸾舞。","翠帘不捲珊瑚钩，虚亭六月风飕飕。","山人或者念畴昔，云端应下苍精虬。"]},{"t":"郭端佥宪之交趾","f":"古风","c":["宫锦绣为衣，青骢白玉蹄。","官迁五岭外，路出大江西。","草堂旧在雩阳郭，便道还家意偏乐。","水色山光泻向人，紫葵黄菊嗟非昨。","手持宪节重，肃肃念王程。","声驰白简飞霜厉，气压黄茅瘴雾清。","只今疮痍极边土，宵旰忧勤荷明主。","未须搏击策殊勋，好尽怀绥副当宁。"]},{"t":"赋得蓟门行送胡元节广东宪使","f":"古风","c":["晨起出蓟门，念卿万里客。","骢马锦连钱，嚼啮黄金勒。","卿行衔命有光辉，朝下初辞青琐闱。","西山晓翠凝琼佩，北阙睛霞艳绣衣。","纷纷相送蓟门路，丝绳玉壶泻春露。","今朝携手当蓟门，明朝相忆知何处。","登车揽辔志澄清，知卿慷慨自平生。","他时广海成功日，还忆蓟门临别情。"]},{"t":"临川吴氏慈节堂","f":"古风","c":["结发被衿帨，来为君子嫔。","行年始三八，空遗未亡身。","玉台寂寞掩明镜，罗帷惨澹栖暗尘。","膝下两男儿，提携心独苦。","寒窗雪夜课诗书，虚牖霜晨把机杼。","临阶双桂同本根，春风并秀凌青云。","煌煌珠翟明鹤发，寿酒日进慈颜醺。","嫁时白玉镜，团团光皎洁。","百年高堂乐未央，长看清辉似明月。"]},{"t":"送杨参政致仕归永嘉兼简宗豫","f":"古风","c":["杨大夫，起自章逢儒，清涵烱烱冰玉壶。","平生胸中书万卷，上溯邹鲁窥唐虞。","年未四十游帝都，朝朝冠佩明庭趋。","退陪天官品量天下士，区别高下贤与愚。","缙绅可望不可近，大夫自视澹若无。","出佐方岳薇垣居，施政不亟亦不徐。","春风披拂枯槁苏，时雨沾洒惠化敷。","闽南八郡五十邑，咏歌鼓舞连道途。","列圣相承三十载，大夫夷险一节终不渝。","白发如丝未全老，成功而退合天道。","山林钟鼎固有命，得退还应健时好。","五月燕南雨晴早。","清莺啼满绿杨烟，舞蝶翩翩弄芳草。","大夫拂袂出都门，我往饯之心懆懆。","逸翮争骞银汉云，蹇驽尚恋天闲皂。","雁荡秀拔东海堧，夫容作花浦屿妍。","谢公旧游清境在，解绂可以长周旋。","何须吴歌越舞酣高筵，何须丹砂玉屑图永年。","但令俯仰无愧天，任情随意合自然。","武英学士清无恙，鹤氅云巾曰来往。","太史行将望聚星，定在斗城华盖上。"]},{"t":"题朱给事所藏马牛二图 其一","f":"古风","c":["矫矫皆雄姿，来从渥洼涘。","金羁未络头，散诞春风里。","试令剪拂效驱驰，君看一日轻千里。"]},{"t":"题朱给事所藏马牛二图 其二","f":"古风","c":["宛宛柳丝柔，绵绵芳草绿。","三月耕犁閒，春田雨新足。","纷纷陌上骤青骢，独占溪南坐黄犊。"]},{"t":"赋得滕王阁送别","f":"七言古诗","c":["章江西来绕洪州，滕王高阁临江流。","滕王去后无千岁，高阁人间几兴废。","昔闻贞观全盛时，大廷金册封宗支。","时平还出领旌节，富贵非常骄逸滋。","正对西山俯南浦，雕栏朱槛参差起。","玳筵凤管杂龙笙，白昼欢声彩云里。","留连晚日下帘钩，别有渔歌闻上头。","回眸共眄沧洲际，杏彩兰娇影娥翠。","只言欢乐殊未央，城头一夜飞秋霜。","三春荣盛逐流水，佩玉鸣銮俱渺茫。","年深代易无此阁，好事何人为重作。","绝世流传蛱蝶图，东风粉色皆消落。","只今阁空台亦平，濒江但有滕王亭。","松门薄暮掩脩竹，数叶萧萧寒雨青。","当时弃德耽游宴，身后荒凉竟谁叹。","一种南昌孺子亭，行人下马思东汉。","君行几日过江津，吊览应知作赋新。","文章自昔三王盛，还见今人继昔人。"]},{"t":"题勤司务画","f":"古风","c":["峨峨青山，英英白云。","缘冈绕岸合苍翠，澄波浩荡龙鳞文。","萧散彼何人，楼居托幽谷。","心与云山清，坐看云山熟。","钓鱼艇子一丝风，门外还来张子同。","沃洲禹穴定何处，梦想江南越中路。","白头无补负明时，亦欲投簪采芝去。"]},{"t":"蜀道难","f":"七言古诗","c":["蜀山峨峨连剑阁，百丈飞崖俯奔壑。","逶迤鸟道出云中，江横石栈凌虚空。","行人未行先胆落，马足凌竞度还却。","由来此路险莫当，王遵策驭如康庄。","未若人心有崎曲，眼前十步能摧毂。"]},{"t":"秋夜长","f":"七言古诗","c":["月明星稀河汉凉，高秋蟋蟀鸣洞房。","愁人不寐独彷徨，披衣徐步出东厢。","白露如玉兰委芳，感激涕泪纷纵横。","为君含思思断肠，念君迢遥异他乡。","欲往从之河无梁，夜长悠悠夜未央。","援琴弹丝写哀伤，山川万里永相望，我独与尔为参商。"]},{"t":"将进酒","f":"古风","c":["将进酒，酒满瓯。","华馔肆陈，炰羔炙牛。","将进酒，酒满觞。","高怀雅度，众宾在堂。","将进酒，勿蹉跎。","奉君寿，为君歌。","白日西逝，黄河东驰。","人生几时。","将进酒，青天翳云，沧海扬波。","人生奈何。","将进酒，晴光摇荡二月时，紫花葳蕤黄柳垂。","花前百鸟春乱啼，玉颜雪皎扬素眉。","清歌宛转舞逶迤。","将进酒，君莫辞。"]},{"t":"君马黄","f":"古风","c":["君马黄，我马白。","并出青楼东，俱驰绿杨陌。","陌头春日游人多，复恐红尘暗玉珂。","长安大道净如洗，回辔联翩若流水。","一双意气逼青春，共指天门五云里。","男儿高步会成名，何须一日千里行。"]},{"t":"紫骝马","f":"古风","c":["紫骝马，黄金鞯。","五花错落锦连钱。","三鬃剪出鸣向天，红丝饰鞚珊瑚鞭。","扬鞭揽辔殊慨然。","愿得出身事明主，驰马挥刀奋威武。","一为除凶报千古。"]},{"t":"行路难","f":"古风","c":["行路难，路多岐。","青天白日光洞地，出门相背东西驰。","忆昔贫贱时，两情如胶漆。","共言生死不相违，握手披肝誓天日。","君今得意成大勋，金章封侯蒙主恩。","六曹贵臣却避马，两府官僚趋过门。","一朝富贵谁能及，翻笑傍人百忧集。","平生金石安足论，对面云泥不相揖。","世事悠悠安可期，芳春花木秋易衰。","冰霜岁寒不改色，却羡南山松柏枝。"]},{"t":"陌上桑","f":"古风","c":["陌上桑。","柔条未全劲，碧叶纷低昂。","秦家女儿年十五，朝日成妆把筐筥。","把筐筥，盈盈南陌前。","明珠结宝带，翡翠贴花钿，一身皎皎尽成妍。","使君从南来，顾盼久徘徊。","遥见东方骑，惆怅空乘五马回。"]},{"t":"关山月","f":"古风","c":["关山月，皎洁如清霜。","连营接幕夕流光。","流光犹得照故园，征人见月徒伤魂。","四时弦望如流去，可惜韶华暗中度。","深闺少年两别离，还如婵娟缺半规。","缺半规，三五来复圆，一身远戍何时旋？"]},{"t":"结客少年场行","f":"五言古诗","c":["置酒高堂上，嘉殽列肥鲜。","结交并豪侠，四座皆少年。","意气不复殊，肝胆相披宣。","仰视白日辉，一言誓青天。","贻我紫绮裘，报君珊瑚钩。","暮从邯郸饮，朝入洛城游。","横行无七贵，傲睨凌五侯。","腰间双青龙，精光含九秋。","投躯报知己，慷慨当仇雠。","性命如鸿毛，夕死无怨尤。"]},{"t":"从军行六章 其一","f":"五言律诗","c":["少小从六军，英声振三边。","拓疆有勋业，貂蝉二十年。","遭遇亨嘉辰，万里净烽烟。","顾视双宝刀，精光犹彻天。"]},{"t":"从军行六章 其二","f":"五言律诗","c":["宝刀白昼鸣，旄头出西陲。","平明有诏书，遴选行率师。","甲士百万馀，桓桓各如貔。","慷慨出门去，妻子安足辞。"]},{"t":"从军行六章 其三","f":"五言律诗","c":["出门意气都，上马跨雕鞍。","旌旗亘千里，戈矛霜雪寒。","来苏望苦深，遄驱敢辞难。","经过令严肃，鸡狗亦得安。"]},{"t":"从军行六章 其四","f":"五言律诗","c":["令严岂不惜，军动良苦辛。","冰行屡及暮，露坐恒达晨。","所倚主将明，抚养义且仁。","恩威两无遗，谁不思奋身。"]},{"t":"从军行六章 其五","f":"五言律诗","c":["奋身一何勇，压敌三重围。","师行倚大义，奇谋定足希。","所向势莫当，降者日以归。","杀之昧天道，纵之表皇威。"]},{"t":"从军行六章 其六","f":"五言律诗","c":["皇威既清肃，奏凯发回军。","明旦谒金门，饮至劳殊勋。","赏赉过百千，麾下歘见分。","拜稽谢万乘，归钓清江濆。"]},{"t":"雨雪曲","f":"五言律诗","c":["边城九月尽，雨雪正霏霏。","兼霰侵毡幕，如冰晃铁衣。","塞垣深莫辨，边云冷不飞。","鬓毛分可拟，征戍几时归。"]},{"t":"上之回","f":"五言律诗","c":["传警甘泉外，扬銮载道周。","回中戒巡省，云动赴遐陬。","春色承雕辇，山光影翠旒。","吾皇亿万岁，岁岁总来游。"]},{"t":"芳树曲","f":"五言律诗","c":["阳和二月时，列树发葳蕤。","凝辉映绮阁，飘香度锦帷。","蝶戏栖浮蕊，莺响隐高枝。","芳华今若此，千春亦不移。"]},{"t":"折杨柳","f":"五言律诗","c":["双堤夹道傍，垂柳复垂杨。","攀条知色改，缀絮讶丝长。","思妇悲迟暮，征夫望故乡。","一闻清角起，谁不泪沾裳。"]},{"t":"自君之出矣 其一","f":"五言绝句","c":["自君之出矣，闻道戍凉州。","思君如明月，夜夜向西流。"]},{"t":"自君之出矣 其二","f":"五言绝句","c":["自君之出矣，镜台尘网生。","思君如海水，浩荡何时平。"]},{"t":"次韵陆伯阳林塘晚咏兼简雷道夫 其一","f":"五言律诗","c":["金门趋讲罢，西园日暮时。","繁阴交杂树，轻浪散清池。","玩芳因坐久，延月却归迟。","还与同袍侣，携手咏新诗。"]},{"t":"次韵陆伯阳林塘晚咏兼简雷道夫 其二","f":"五言律诗","c":["高居傍城阙，隙地富园林。","天风下修竹，锵锵韵玉琴。","浮觞清沼曲，憩石碧梧阴。","别有闻佳咏，因之仰素心。"]},{"t":"贫乐堂","f":"五言律诗","c":["草色荫松门，青山绿树村。","种蔬成小圃，饮水必澄源。","每究贤人乐，时同静者论。","穷通自有分，非为薄华轩。"]},{"t":"观海生诗为临海令作","f":"五言律诗","c":["作县临东海，当年眺览中。","水云连浩渺，心境合昭融。","已惬观澜趣，还思作楫功。","有才终利涉，非比望洋同。"]},{"t":"高巨川挽诗","f":"五言律诗","c":["保障临江曲，荒城已半隳。","重寻耆旧传，愁说乱离时。","乡里思遗德，河山识令仪。","孤坟三尺在，落日有馀悲。"]},{"t":"善乐堂","f":"五言律诗","c":["家惟经籍富，数世坐丘园。","善乐承先训，心清味道言。","穿林无曲径，引水得澄源。","旦暮悠然处，南山正对门。"]},{"t":"题贝教谕容与轩","f":"五言律诗","c":["金川带玉笥，此地托幽轩。","旦暮无尘事，弦歌近县门。","傍花晴散帙，延月夜开樽。","容与存吾道，长令学者尊。"]},{"t":"送舒有常知县赴永春","f":"五言律诗","c":["幸际文明世，谁甘畎亩民。","再来趋北阙，九月赴南闽。","红树吴门郭，青帘海上津。","有才当抚字，卓鲁亦何人。"]},{"t":"赠魏将军","f":"五言律诗","c":["铁马载雕弓，身轻百战中。","圣朝初偃武，高爵竟论功。","带镂银花白，衣裁绣锦红。","西清五云下，长卫大明宫。"]},{"t":"高邮","f":"五言律诗","c":["四顾无山色，苍茫极远天。","水云涵郡郭，粳稻被湖田。","草舍津头市，菱歌柳外船。","羁愁念前路，非为别离牵。"]},{"t":"过武城县","f":"五言律诗","c":["河上皆民舍，波光映苇扉。","青裙沽酒过，白发载鲜归。","仓廪丰年积，弦歌古俗稀。","征帆未可住，还逐暮云飞。"]},{"t":"任丘道中","f":"五言律诗","c":["霜柳未全稀，风沙不住飞。","居人过驿尽，猎火隔河微。","客路冲寒景，天恩恋禁闱。","金台行渐远，回首思依依。"]},{"t":"晚次景州遇李颀给事吕文质进士","f":"五言律诗","c":["下马郭西村，萧条尽掩门。","荒城明落景，独树出平原。","野水条侯墓，寒芜董氏园。","閒因访遗事，邂逅故人论。"]},{"t":"重过济宁","f":"五言律诗","c":["闾井皆临闸，郊原四望平。","横峰连岱岳，分水向彭城。","笳鼓屯千骑，舟车会两京。","沿洄未能住，俱是重王程。"]},{"t":"挽卢侍郎 其一","f":"五言律诗","c":["三十趋京国，同时复有谁。","贵为祈父佐，长在缙云司。","物化嗟何速，神游不可知。","凄凉山浦侧，千古葬灵輀。"]},{"t":"挽卢侍郎 其二","f":"五言律诗","c":["无复相逢处，相思每独哀。","真成雕鹗奋，忽殒栋梁材。","草露晞还落，河流去或回。","空馀一片月，夜夜照中台。"]},{"t":"送张鸣玉赣州知府","f":"五言律诗","c":["北阙捧恩荣，西江戒驿程。","悠悠驱五马，冉冉度双旌。","政得虔人爱，心如赣水清。","崆峒千丈碧，应勒使君名。"]},{"t":"早度清流关","f":"五言律诗","c":["地险雄江北，崩云乱石高。","古人成败远，行客往来劳。","雾壑疑藏豹，风林讶啸猱。","五年重过此，霜点旧青袍。"]},{"t":"萧知州清省居 其一","f":"五言律诗","c":["白发滦州守，邦畿久著称。","心清何所似，皎洁玉壶冰。","数米功难致，烹鲜道可凭。","从知清净理，未愧古人能。"]},{"t":"萧知州清省居 其二","f":"五言律诗","c":["廨宇清如水，时平案牍稀。","阶前幽鸟下，帘外白云飞。","易简民从化，廉平吏息机。","鸣琴过日夕，玩月澹忘归。"]},{"t":"非所寄示康甥荣","f":"五言律诗","c":["旦暮圜扉下，清羸念尔身。","闭门堪避俗，省事足怡神。","药里时常检，书灯夜少亲。","亦知相念切，来问勿频频。"]},{"t":"题刘士皆云林小画","f":"五言律诗","c":["春雾晓初收，春山翠欲流。","林霏疑雨润，岚彩近天浮。","故里三华麓，当年一叶舟。","看图浑彷佛，虚负水亭幽。"]},{"t":"月池彭母挽诗 其一","f":"五言律诗","c":["七十人间世，婺居四十馀。","冰霜明妇节，灯火课儿书。","堂掩春晖暗，乌啼夜月虚。","白头游子泪，和血洒衣裾。"]},{"t":"月池彭母挽诗 其二","f":"五言律诗","c":["谁不为孀妇，风霜苦自持。","人情易衰薄，亲戚厌□婺。","旧箧藏遗简，寒机理断丝。","百年池上月，曾照育孤时。"]},{"t":"题杨学士画 其一","f":"五言律诗","c":["群山开奕奕，清涧绕沄沄。","叆叇疑浮玉，巑岏讶染纁。","岩芝香可茹，林翠暖如熏。","想见幽栖者，尘喧了不闻。"]},{"t":"题杨学士画 其二","f":"五言律诗","c":["素琴兼白鹤，潇洒散高踪。","境类金精迥，山如玉笥重。","泉香流石乳，霞彩拂虬松。","溪上桃花满，神仙倘解逢。"]},{"t":"夜两坏壁简邻居诸君子","f":"五言律诗","c":["雨深颓屋壁，夜起揽衣趋。","入室风翻幔，缘阶水倒渠。","未沈爨下釜，急护案头书。","得似东西舍，高眠总晏如。"]},{"t":"送刘编修朝宗赴九江教授 其一","f":"五言律诗","c":["昔过浔阳郡，凭高畅客情。","庐山当近郭，江水带孤城。","茅屋家家净，渔舟个个轻。","广文怀散逸，此去课诸生。"]},{"t":"送刘编修朝宗赴九江教授 其二","f":"五言律诗","c":["去上还乡路，天恩便养亲。","拜辞金殿直，谢别玉堂人。","山水濂溪近，风烟栗里邻。","怀贤知有志，应不负青春。"]},{"t":"行天寿山","f":"五言律诗","c":["连骑去骎骎，缘冈复度林。","杏花明似绣，杨柳淡含金。","万物亨嘉日，先朝种植心。","白头供俸在，俯仰一沾襟。"]},{"t":"晓起","f":"五言律诗","c":["晓起侵风露，黄埃涌素袍。","如林行队伍，缘涧耀旗旄。","细马驰能捷，苍鹰奋欲高。","从臣稀奏赋，心切圣躬劳。"]},{"t":"行营夜雨","f":"五言律诗","c":["雨来从薄暮，沾洒夜将阑。","稍喜尘埃息，何由衾席乾。","天心存发育，人事有忧欢。","森立戈殳士，通宵念尔难。"]},{"t":"早行","f":"五言律诗","c":["联骑载旌㫋，移营乱垄田。","人行风露下，月转斗牛边。","涉涧泥沾袂，穿林草没鞯。","数家茅屋小，彷佛见炊烟。"]},{"t":"冲雨","f":"五言律诗","c":["晨起冲寒雨，艰难念仆夫。","山田行沮洳，石径度崎岖。","矫矫虞张弋，桓桓士执殳。","肩舆扶老病，扈跸愧残躯。"]},{"t":"次韵黄少保过田家有感","f":"五言律诗","c":["水旱农艰食，兹乡实可嗟。","扫田纷拾稗，为饭杂蒸沙。","岁赋徵仍急，秋成望苦赊。","吾徒何补益，肉食老京华。"]},{"t":"晚度密云北山绝顶","f":"五言律诗","c":["常奉垂堂戒，其如扈跸何。","高疑登玉垒，近恐逼银河。","宛转扪萝上，低回避石过。","前途看渐晚，力尽敢蹉跎。"]},{"t":"送周布政之官三山","f":"五言律诗","c":["御苑柳初春，龙河冰始泮。","祗命辞彤闱，驱车候清旦。","超遥起云翼，光华升玉瓒。","远别期誉名，无为乖阙叹。"]},{"t":"题梅花图","f":"五言律诗","c":["昔者江南住，栖迟万玉林。","只今图画见，遗恨别离深。","凛凛岁寒意，娟娟冰雪心。","北人知爱少，閒伴小窗吟。"]},{"t":"送袁文理 其一","f":"五言律诗","c":["昔我艰虞日，于君邂逅欢。","相看羡玉树，遂拟托金兰。","岁月分携久，江湖聚晤难。","喜闻嘉政满，荐剡出台端。"]},{"t":"送袁文理 其二","f":"五言律诗","c":["入觐初相见，升除遽不留。","还寻江左路，问买浙西舟。","桑梓归应蚤，莼鲈到及秋。","伫闻宽恤治，为解别离愁。"]},{"t":"寄尤文度 其二","f":"五言律诗","c":["三年别帝京，归卧阖闾城。","贫病疏朋友，艰难倚弟兄。","香焚瓦鼎细，寒拥纸屏清。","自有床头易，时时畅道情。"]},{"t":"寄黄宗豫少保","f":"五言律诗","c":["佩玉娱亲日，衣抛五色文。","身閒疏药裹，庭静对炉熏。","醉写泉头竹，吟看海上云。","从知萧散地，一饭不忘君。"]},{"t":"邹谦所孝思堂","f":"五言律诗","c":["墓筑芜湖县，因之托数椽。","却思严谴日，感泣更生年。","十口今谁在，孤身秪自怜。","朝朝松柏地，拜跽荐寒泉。"]},{"t":"早发","f":"五言律诗","c":["行营侵曙发，风露不胜清。","海色微茫动，林霏杳霭生。","六军严虎卫，万骑翼霓旌。","七九流年外，含毫扈远征。"]},{"t":"观猎","f":"五言律诗","c":["扬旌表四岑，环戟拥如林。","已失千寻险，宁遗三穴深。","春蒐元有典，时育亦关心。","解网商王德，光辉尚至今。"]},{"t":"早入蓟州","f":"五言律诗","c":["极目平无际，青山画不如。","彩云迎霁旭，翠柳带澄渠。","地重城逾壮，年丰廪有馀。","未应两岐咏，独系汉人书。"]},{"t":"自题小像寄乡邑亲故","f":"五言律诗","c":["两京三十载，梦寐在乡闾。","叨䘵承明主，匡时愧腐儒。","淹留鞶带缓，愁思鬓毛疏。","惟有秋霜意，今吾是故吾。"]},{"t":"送黄养正 其一","f":"五言律诗","c":["历事三朝圣，曾蒙当宁知。","手持五色笔，常在凤凰池。","雪霁城南路，春融柳外澌。","还家自足喜，报国岂应迟。"]},{"t":"送黄养正 其二","f":"五言律诗","c":["文明门外柳，频折送人归。","窃䘵吾何补，怀乡志屡违。","越潮天际白，吴树雨中微。","羡尔乘仙舫，东南去似飞。"]},{"t":"送陈公馀赴台州教授诗 其一","f":"五言律诗","c":["陈氏联双璧，京华旧合并。","蚤终悲令弟，久别见难兄。","受命辞丹阙，之官向赤城。","相逢已多嘅，相送更胜情。"]},{"t":"送陈公馀赴台州教授诗 其二","f":"五言律诗","c":["海上天台郡，云边岛屿青。","交游如昨日，梦寐想平生。","乡里风仍厚，诗书化易行。","公堂无外事，弦诵有馀清。"]},{"t":"郑村坝","f":"五言律诗","c":["十里都城外，天清见远山。","断渠冰奠玉，连树叶飞丹。","牧苑千群出，耕畬万顷閒。","赐田思往事，双泪不胜弹。"]},{"t":"早发李家桥","f":"五言律诗","c":["霜气欺貂帽，风埃压毳袍。","天连东海近，斗转北辰高。","戈戟纷成队，衣冠总属櫜。","衰年仍窃䘵，扈跸敢辞劳。"]},{"t":"应制两咏 其一 五色鹦鹉","f":"五言律诗","c":["异质超同类，光辉五色并。","非关怜巧语，所重表文明。","香粒金为勺，甘泉玉作罂。","君恩无限好，能忘陇山情。"]},{"t":"应制两咏 其二 白鸠","f":"五言律诗","c":["本与凤同类，名官自昔时。","萧萧閒雅意，皎皎洁清姿。","金屋看尤好，琼林息正宜。","和鸣致甘雨，丰岁足公私。"]},{"t":"扈从度居庸关登八达岭","f":"五言律诗","c":["盘回跻峻崄，岚翠湿纷纷。","巘路平银汉，关楼俯白云。","朝廷须讲武，扈从总能文。","独立舒长啸，风清上界闻。"]},{"t":"岔道观猎","f":"五言律诗","c":["已度重关险，初临广野平。","岚兼远水白，山拥半空青。","扈跸同三事，蒐原合五兵。","农閒陪阅武，亦得畅予情。"]},{"t":"挽黄行中检讨","f":"五言律诗","c":["霜霰零琼树，天寒一夕摧。","竟如东逝水，无复却西回。","世数金闺彦，人思玉署才。","旧时来往路，重过不胜哀。"]},{"t":"黄处士挽诗","f":"五言律诗","c":["簪组名家后，诗书奕世承。","艰危持行义，萧散在林坰。","韶光惊石火，精爽閟泉扃。","徒使相知者，含悲诵冢铭。"]},{"t":"樊通政雪霁草堂","f":"五言律诗","c":["轻风解寒冱，初日丽丘林。","檐际泻悬溜，窗中见遥岑。","清和荡淑气，浩畅发冲襟。","馀色皎如玉，吾将比素心。"]},{"t":"勉仁少傅行营置酒就席奉简同寅","f":"五言律诗","c":["万乘行春日，千官得共陪。","石林穿窅窱，涧道历邅回。","酒载黄封赐，人联玉署才。","解鞍庐帐下，随意泻金罍。"]},{"t":"送襄阳王时中知县","f":"五言律诗","c":["铜章仍出宰，金阙已知名。","归治中牟县，重经故郢城。","轻霞江树晓，疏雨汉皋晴。","还忆沧浪曲，清泠好濯缨。"]},{"t":"独游山寺奉简宗豫少保勉仁少傅弘济太常","f":"五言律诗","c":["扈跸愧无能，同官喜得朋。","芳林时独往，清境遂閒登。","碑古封文藓，泉幽羃翠藤。","欲题岩畔石，历览记吾曾。"]},{"t":"夜发岔道赴怀来","f":"五言律诗","c":["明月下西岭，天高北斗斜。","惊风起中夜，捲地簸飞沙。","磊磊道间石，喧喧桥外车。","过城曙色动，连骑发箫笳。"]},{"t":"早发老鸦庄","f":"五言律诗","c":["鼓角动行营，翩翩从羽旌。","月明人影乱，沙软马蹄轻。","本乏筹边略，恒存事主诚。","叨荣何补益，惭愧负平生。"]},{"t":"早发安家堡","f":"五言律诗","c":["上马逐西风，风寒夜正中。","众星斜转北，一水背驰东。","不恨冯唐老，虚怀杜甫忠。","祗勤扈龙驭，何暇恤微躬。"]},{"t":"望昌平","f":"五言律诗","c":["百里近皇都，萧条邑井孤。","夏霖频汎滥，秋谷竟虚无。","官府犹徵役，朝廷已罢租。","缅怀刘谏议，千载愧吾徒。"]},{"t":"送向诚随侍赴九宫山","f":"五言古诗","c":["神境三光表，王车十月行。","霜随龙旆肃，风送马蹄轻。","云馆迎千乘，仙台望五城。","岩前金灶古，树杪玉泉鸣。","听讲淮南道，闻吹子晋笙。","遥知随侍好，频有咏歌声。"]},{"t":"题山水画","f":"五言古诗","c":["际海飞初旭，凌空叠远岑。","岚端浮石笋，霞畔拥金林。","岛屿红涛上，藤萝翠壁阴。","连帆乘浩渺，高阁倚嵚崟。","江路缘频转，云居望转深。","依微庐阜下，彷佛越溪浔。","展玩销纷虑，经营见苦心。","定应何处所，思与谢公寻。"]},{"t":"送王泸渊改训导上杭","f":"五言古诗","c":["寥落新安邑，横经已十年。","朝盘餐有粟，夜榻坐无毡。","济济来衿佩，洋洋听诵弦。","学规兼体用，祀礼备精虔。","东鲁文衡撤，南闽教铎迁。","肯辞行道远，自喜过家便。","天霁云横岳，潮平雨溢川。","别离将万里，书问若为传。"]},{"t":"馀姚陈氏嘉会楼","f":"五言古诗","c":["邑里稽山麓，楼居浙水湄。","雕栏出翠树，藻井映华芝。","远眺通吴会，高攀近尾箕。","云乘鹦鹉落，瀑带凤凰垂。","圣化升平日，天恩长养时。","四郊无夜警，万物蔼春熙。","耕有如坻积，歌闻击壤辞。","都将欣惬意，持用表兰楣。"]},{"t":"分题送史郎中代时彦学夔德遵 其一 驿楼","f":"五言古诗","c":["靡靡遵归路，岧岧见驿楼。","朱帘迎日捲，画栱碍云浮。","眺览通恒岱，跻攀切斗牛。","乘轺来使节，驰驿驻行驺。","送尔今重过，凭高试一留。","诗成清似玉，洒翰记曾游。"]},{"t":"分题送史郎中代时彦学夔德遵 其二 河梁","f":"五言古诗","c":["河水深无极，河梁构石崇。","映波疑坠月，倚岸讶垂虹。","华表东西出，兰舟上下通。","屡经题柱客，谁论济川功。","甃古苔纹暗，亭虚柳色浓。","送君携手处，征骑莫匆匆。"]},{"t":"分题送史郎中代时彦学夔德遵 其三 芙蓉","f":"五言古诗","c":["菡萏开初盛，池塘及早秋。","根从玉井得，叶似镜湖稠。","丽彩凝云动，清香抱露浮。","娉婷汉女出，窈窕洛神游。","折赠宁忘远，听歌或弭愁。","惟将君子意，临别寄绸缪。"]},{"t":"七夕送丁侃吴江教谕","f":"五言古诗","c":["玉露下青冥，银河会两星。","故人当远别，独棹发前汀。","晓月沧州路，秋风泗上亭。","芰荷香欲过，杨柳翠将零。","小邑连吴郡，青山满洞庭。","官居自有适，况乃坐谭经。"]},{"t":"代德遵送严士正赴江阴训导","f":"五言古诗","c":["之官辞玉阙，送别傍金台。","暂驻城阴骑，同倾柳下杯。","念离俱缱绻，欲发更徘徊。","远树青如荠，春波绿胜苔。","路驰兼水陆，舟汎历沿洄。","之子儒家秀，前贤世德培。","羽仪明鸑鷟，器质抱琼瑰。","圣代蜚腾早，亨衢特达开。","三吴推道院，百里富英才。","习礼延陵邑，谈诗匡鼎来。","道存人自化，意澹俗无猜。","此去应相忆，题书寄雁回。"]},{"t":"题金学士画","f":"五言古诗","c":["谁写江皋趣，披图忆汉南。","清峦连岳麓，幽渚带湘潭。","树色浮青霭，岩光荡翠岚。","渔家临水静，禅刹与云参。","窈窕缘汀路，微茫隔浦帆。","平生萧散意，对此欲抽簪。"]},{"t":"题吴逸人二云山房","f":"七言律诗","c":["凌云并立两山青，山下幽居静不扃。","晴分黛色明香几，昼拥岚光落砚屏。","苍龙来问还丹诀，白鹤听谭大洞经。","门前涧底朝朝去，更采昌阳九节灵。"]},{"t":"送元先辈归吴","f":"七言律诗","c":["门巷萧条过者稀，诸孙憔悴日牵衣。","岂无幕下三年客，又送吴中一棹归。","汉树临风寒自落，江鸿带雪晚犹飞。","由来去邑怀桑梓，不是还山恋采薇。"]},{"t":"陆氏沧浪渔隐","f":"七言律诗","c":["渔村深映绿杨烟，门外沤波日放船。","兴逐浮云看不厌，坐乘流水去悠然。","横江月出时歌榜，别浦风清亦扣舷。","常年独泛沧浪曲，不羡遭逢渭水边。"]},{"t":"陈氏环翠轩","f":"七言律诗","c":["潇洒轩居翠作围，遥看郁郁又霏霏。","浓含野树晴如滴，乱湿山云晓不飞。","綵服凝辉当舞席，牙签分映满书帷。","湖波近绕阑干曲，更诧新荷好制衣。"]},{"t":"和陆伯阳池上梅花","f":"七言律诗","c":["圃里池边一树花，连松傍竹似山家。","香浮书幌风初动，影上琴床月半斜。","延客别穿幽径入，接邻更筑短墙遮。","凭教横笛休惊落，爱此来看日正赊。"]},{"t":"约蔡尚远朱存礼蔡用严尤文度杨仲举游东山","f":"七言律诗","c":["东山东望屹如帷，久待穿云蹑翠微。","五色烟霞浮宝塔，千行松竹护禅扉。","春来况复芳菲盛，客里堪嗟聚晤稀。","为报明朝著双屐，及时清赏莫相违。"]},{"t":"及期过邀朱存礼不遇用韵督之","f":"七言律诗","c":["淹留不下董生帷，徒向青春叹式微。","游赏久怀跻胜境，招寻频值掩高扉。","云开石磴看逾近，风捲花枝觉渐稀。","便趁晴明行载酒，谢公那得更相违。"]},{"t":"雨中感怀","f":"七言律诗","c":["檐前水到竹棚头，檐下雨鸣殊未休。","挟册儿童断来往，傍篱凫鸭自沈浮。","即过东家邀短筏，莫须西埠买轻舟。","客怀坐此堪惆怅，风景萧条况近秋。"]},{"t":"次韵答邓存诚见赠","f":"七言律诗","c":["清诗频诵解人颐，客里逢君恨独迟。","行枉高轩无隔日，坐谈虚馆屡移时。","潜心共慕颜生乐，携手俱忘墨氏悲。","从此相望巷南北，朝朝来往话深期。"]},{"t":"泊金口次友人韵","f":"七言律诗","c":["属玉飞鸣沙屿傍，梅花如雪照晴冈。","数家茅店临金口，百里山城望汉阳。","浣女映纱寒水碧，棹郎吹䉌暮云长。","乡关迢递乡书杳，愁立西风看雁翔。"]},{"t":"五月四日暮雨感怀","f":"七言律诗","c":["翠微清旦逐攀缘，携手翩翩记昔年。","岩际穿花经宛转，阁中御酒坐留连。","悠悠逝日随流水，杳杳高情各远天。","俱在兹晨兴暮雨，东门归处不悽然。"]},{"t":"和郑孟宣助教左掖闻莺","f":"七言律诗","c":["新莺飞集万年枝，宛宛流音欲曙时。","乍协仙韶当紫殿，更谐琼佩近彤墀。","九天春日初留听，千里云林独系思。","惟有郑虔才调绝，朝回洒翰一题诗。"]},{"t":"赋得汉阳送朱季宁湖广佥宪","f":"七言律诗","c":["大别山前爽气浮，吴王矶对庾公楼。","江流东道从何日，汉水西来会此州。","万里朝宗归一派，两城冠盖列诸侯。","先声传报迎霜节，遥想澄清澈上游。"]},{"t":"送姚侍书归觐","f":"七言律诗","c":["载笔三年侍禁闱，青春文翰有光辉。","天恩暂别双龙阙，家庆新裁五色衣。","解缆晴江杨柳绿，升堂朝馔鲤鱼肥。","凤凰池上来应早，莫待林花散乱飞。"]},{"t":"送黄叔昭归文江","f":"七言律诗","c":["赐归初买上江船，归路何因复怆然。","渡海几人还故里，到家三月及春田。","碧梧丘垄回生色，绿水园林捲宿烟。","莫叹物情非夙昔，青山还映旧门前。"]},{"t":"从狩阳山和胡学士韵","f":"七言律诗","c":["王师晨猎大江东，文武千官扈从同。","万乘旌旗随玉辇，九霄鸿鹄避彤弓。","青山半掩浮岚白，碧涧深流落叶红。","甘露满林歌瑞应，知君能赋擅才雄。"]},{"t":"从狩武冈和胡学士韵二首 其一","f":"七言律诗","c":["丹崖翠岭接岧峣，万骑交驰不惮遥。","前队綵旄穿碧树，中军黄幄丽晴霄。","云藏网罟参差出，草合冈原逦迤烧。","农事已閒脩武事，共怀词赋从銮镳。"]},{"t":"从狩武冈和胡学士韵二首 其二","f":"七言律诗","c":["雪消辇路不生尘，和气冲融已发春。","玉露应期呈上瑞，金吾传敕赐群臣。","鸿图万岁归神武，盛事三驱睹至仁。","冠剑股肱咸扈从，丹青预想画麒麟。"]},{"t":"送林佥事赴陜西","f":"七言律诗","c":["晓别词林出帝畿，关中使者绣为衣。","三年撰述推多学，一道澄清属有威。","月满渭川宜独照，霜含秦树已先飞。","君王旰食勤西顾，早晚封章达琐闱。"]},{"t":"送郑御史赴四川","f":"七言律诗","c":["青春衣绣有辉光，况复驰声白玉堂。","承诏早持班氏笔，赐归先过郑公乡。","驿亭解缆江潮急，官舫闻猿峡路长。","遥想三川旧行处，重来随地凛飞霜。"]},{"t":"送黄伴读","f":"七言律诗","c":["青春千乘发京师，花映銮镳柳映旗。","官属尽看归侍从，交游那忍话分离。","碧堂进讲趋常早，玉醴承恩出每迟。","想得公馀忆乡旧，还应题句报相思。"]},{"t":"送沙同知赴䘵州兼问克伟消息","f":"七言律诗","c":["贰车南去抚烝黎，雪色梅花满路岐。","问俗遥连交阯郡，到官正及艳阳时。","已知寡欲能胜瘴，预喜多才会变夷。","为访龙州曾贰守，久无书札寄京师。"]},{"t":"送全州知州","f":"七言律诗","c":["新年考绩天官日，第一皆传太守名。","鸣佩又辞双凤阙，挂帆遥转九江城。","天涯草色绵绵绿，湖上杨花片片轻。","还到清湘三月暮，郭南骑马劝春耕。"]},{"t":"送向武金吏目","f":"七言律诗","c":["一命微官万里程，清时行送鲁诸生。","天连粤徼孤城险，家渡湘江数口轻。","杨柳飞花沾去棹，桄榔杂树乱离情。","才高莫叹淹遐僻，政满还来谒圣明。"]},{"t":"题竹寄萧安正","f":"七言律诗","c":["修竹纷纷荫石台，高楼新傍竹西开。","青天彩凤盘云下，白日鸾歌度涧来。","南阮诗书连绛帐，东山苍翠落银杯。","桃花流水三年别，又儗青春放棹回。"]},{"t":"送刘敦信致仕","f":"七言律诗","c":["七十悬车世所稀，先生六十遂南归。","两行霜鬓辞天去，一片秋帆带雨飞。","松径晚晴苍鹿近，石田云缓玉芝肥。","休官自此无尘事，惟有门人日款扉。"]},{"t":"送周给事使西南夷","f":"七言律诗","c":["仙郎意气清如玉，每接班行共早朝。","久立银台簪彩笔，又衔丹诏下青霄。","蛮方草木含天泽，驿路风云拥使轺。","想见驰驱遍南徼，日闻重译颂唐尧。"]},{"t":"送徐崇威陜西理问","f":"七言律诗","c":["初归西掖掌丝纶，共喜中朝接缙绅。","练达久明钦恤意，迁除又拜宠恩新。","舟移汉水还经楚，路入函关远向秦。","华岳秋清五千仞，行应挂笏看嶙峋。"]},{"t":"灵谷寺建追荐征南将士水陆大斋车驾临祭先夕百官出候寺中","f":"七言律诗","c":["晚出东华赴上方，满衣月色动微凉。","钟声渐识斋坛近，松影遥连辇路长。","涧底玉泉鸣石磬，云边红烛乱星光。","欢迎天上来龙驭，一夜祗园散好香。"]},{"t":"文华门侍朝观录囚多所宽宥喜而有作","f":"七言律诗","c":["日丽文华霁色新，炉烟不断上麒麟。","大臣论谳持王制，睿旨全生体帝仁。","真儗下车兴叹泣，旋看解网动欢欣。","朝廷宽大恩波厚，庆衍皇图亿万春。"]},{"t":"卧病院中寄黄学士","f":"七言律诗","c":["三旬抱疾卧斋閤，忽报春风谢绛桃。","草色新含时雨绿，杨花纷逐晓云高。","屡承恩赐身难报，閒听朝车思转劳。","想见词垣多召命，日趋东殿独挥毫。"]},{"t":"冬至早朝遇雪和胡学士韵","f":"七言律诗","c":["履长庆罢天颜悦，和气冲融散雪来。","为瑞正当鳷鹊观，飞花还过凤凰台。","彤墀飏彩龙旂动，玉几凝辉宝扇开。","共上君王千万寿，九成歌舞进琼杯。"]},{"t":"诸公从狩龙山因登牛首山访佛窟寺胡学士有诗是日仆以病不及行想像佳游辄用次韵三首 其一","f":"七言律诗","c":["吉日鸣銮出九关，龙山扈从喜跻攀。","云迎翠辇晨先合，鸟避黄麾夕未还。","猎火依微烟岫里，鸣笳缥缈石林间。","群臣咸睹三驱乐，贱子空惭一日閒。"]},{"t":"诸公从狩龙山因登牛首山访佛窟寺胡学士有诗是日仆以病不及行想像佳游辄用次韵三首 其二","f":"七言律诗","c":["宝刹藏云近翠微，世人闻说到应稀。","千年饮马泉仍在，半夜巢松鹤自归。","碑存古刻题朝代，僧有閒情熟道机。","应话无生因坐久，不辞香雾惹朝衣。"]},{"t":"诸公从狩龙山因登牛首山访佛窟寺胡学士有诗是日仆以病不及行想像佳游辄用次韵三首 其三","f":"七言律诗","c":["寺外幽岩石径斜，岩中开士似丹霞。","心涵水月空诸法，坐对寒崖落一花。","清夜潮音翻贝叶，常时云气护袈裟。","匆匆遥望知难觅，归骑联翩拥翠华。"]},{"t":"同金谕德踏雪出长安街金坠马在告不及往问明旦奉简","f":"七言律诗","c":["云映都城一色妍，暮街骑马共翩翩。","初当分手回丝鞚，惊看翻身坠锦鞯。","鸣佩纷趋天阙下，闻钟独卧晓窗前。","平戎万里随龙驭，意气能无叹往年。"]},{"t":"题吴中书所蓄徐御史写梅","f":"七言律诗","c":["清江先生如玉雪，旧种寒梅今满庭。","閒时抚树得籀法，残岁开花映壁经。","凤沼香云隔尘滓，霜台白笔写神形。","朝回何逊谁相问，定在金陵竹叶青。"]},{"t":"别用之后其夕闻尚留江上赋此奉柬","f":"七言律诗","c":["日出高城啼曙乌，城边风色柳疏疏。","关河岁晏侵冰雪，客子天寒叹道途。","明旦乘潮应鼓枻，谁家烧烛且倾壶。","平生未解伤离别，却掩衡门坐郁纡。"]},{"t":"赠梁本之 其一","f":"七言律诗","c":["渺茫何处望泸州，已拜除书去不留。","七十慈闱双别泪，五千蜀道一孤舟。","皆传远邑民情好，亲见诸生礼数优。","到日平安寄鱼素，殷勤先慰倚门愁。"]},{"t":"赠梁本之 其二","f":"七言律诗","c":["蜀山消尽雪皑皑，江水初平滟滪堆。","问路遥穿三峡过，之官惟带一经来。","林间女负巴盐出，烟际人乘僰骑回。","莫叹遐方异风俗，此州元有穆清台。"]},{"t":"九日过宿迁县","f":"七言律诗","c":["挂席迢遥晚未休，行程逦迤望邳州。","数家农舍通篱落，几处渔舟聚洑流。","回首乡园天渺渺，惊心时序水悠悠。","紫萸黄菊非无意，沙鸟汀云漫自愁。"]},{"t":"蒙恩南还陛辞后出文明门留别词林知己","f":"七言律诗","c":["双阙凌云晃曙辉，君恩初拜下彤闱。","西山雪霁千峰出，远道天寒一骑归。","翰苑故人多契阔，离筵芳酒又分违。","相思后夜瞻银汉，奎壁光华映紫微。"]},{"t":"十月十六日侍从赴北京出江东门","f":"七言律诗","c":["十月朝天趋蓟北，城中争送向江皋。","朋俦载酒飞觥数，儿子褰裳徒步劳。","满路和风喧鼓吹，中天晴日耀旗旄。","纷纷喜气随行骑，回首钟山紫翠高。"]},{"t":"滁州陪猎次林光䘵韵","f":"七言律诗","c":["日华朝映彩云西，红树青山望不迷。","罝网合围笳鼓振，戈矛分队羽旄齐。","欢呼春动三军色，腾踏风轻万马蹄。","侍从如云陪乐事，郊原霜净不沾泥。"]},{"t":"寻醉翁亭故址","f":"七言律诗","c":["空山泉石四无邻，亭构当年已化尘。","前辈文章关气运，后来瞻仰愧乡人。","寒林缥缈荒烟外，霜径逶迤古涧滨。","景物已殊风俗在，壶浆来往见滁民。"]},{"t":"凤阳过宿族兄弘璧夜话","f":"七言律诗","c":["十五离乡今七十，版图已作帝乡民。","田园晚岁治生足，儿女全家习俗淳。","犹有诗书传世业，不胜悲喜见宗亲。","百年杨氏衰兼盛，一夜灯前语向晨。"]},{"t":"赵彦如挽诗 其一","f":"七言律诗","c":["潇洒清风满素襟，况兼文采映儒林。","圣朝贤达皆推毂，晚岁京华始盍簪。","书閤淹留春酒熟，斋房谈咏夜灯深。","年来渐觉朋游减，坐看晨星怆寸心。"]},{"t":"赵彦如挽诗 其二","f":"七言律诗","c":["邻并紫垣南畔住，寻常来往共襟期。","可怜病起分携后，无复朝回坐对时。","学行尚存舆论好，交游未澈士林悲。","凤山原下千年石，不愧当年有道碑。"]},{"t":"幽居二首简时彦学夔习礼 其一","f":"七言律诗","c":["白日红尘浑不到，金城坊里托幽居。","家贫颇类贤人巷，地静何烦长者车。","近郭好山青映户，小桥流水绿通渠。","衣冠邻曲皆邹鲁，来往清言数起予。"]},{"t":"幽居二首简时彦学夔习礼 其二","f":"七言律诗","c":["二十年来列从官，玉堂高处切金銮。","哀迟有幸迁清秩，匡辅无才愧素餐。","朝退书帷閒独坐，吟馀尘事不相干。","自怜此乐从前少，身荷君恩欲报难。"]},{"t":"爱竹堂为杨主事赋","f":"七言律诗","c":["堂前修竹先人种，看竹升堂思不禁。","正直终存君子节，清虚犹见昔贤心。","灵旂疑下云垂屋，仙佩如闻风满林。","自是著存长不忘，岂同三月爱山阴。"]},{"t":"送吴员外赴南京礼部","f":"七言律诗","c":["春坊中允同袍旧，十五年来间阔深。","此日帝城重握手，西风祖道又分襟。","苍茫蓟树凌寒景，缥缈淮云接暮阴。","知到南京公事简，紫金山色对青吟。"]},{"t":"挽金凤仪","f":"七言律诗","c":["昔为御史南京住，朝罢相过不厌频。","每爱容仪誇白璧，还看文采映青春。","飞腾云汉非关早，沦落泥涂独未伸。","空使时人嗟定命，铭文三复为伤神。"]},{"t":"次韵答仲熙庶子见寄","f":"七言律诗","c":["习懒忘机已岁馀，还应力疾效驰驱。","衰迟岂有㳙埃助，谈咏都将故旧疏。","倚槛桃花开画障，夹渠杨柳映斋居。","閒情想见城东曲，欲和阳春愧不如。"]},{"t":"金华方处士挽诗","f":"七言律诗","c":["乡里过从驾小车，平时萧散有谁如。","幽人日聚清芬閤，处士星明宝婺墟。","乘化已翔云外鹤，传家犹贮壁间书。","石梁岁岁行人度，共说何公德有馀。"]},{"t":"送刘训术归西昌","f":"七言律诗","c":["冠带逍遥桑梓间，浮云长共此心閒。","家传大父青乌秘，门对仙人白鹤山。","五年江外三回见，八月燕南一棹还。","万里归来谁得似，独无尘土涴清颜。"]},{"t":"松居为馀杭詹道士作","f":"七言律诗","c":["紫霄玄居静不扃，长松如盖对亭亭。","深涵雨露千年润，高拂烟霞万仞青。","仙子时来下白鹤，道人昼坐咏黄庭。","会当天柱峰前去，共汲丹泉煮茯苓。"]},{"t":"送胡士琏贵州按察使 其一","f":"七言律诗","c":["澹云心事坚冰操，白首如公见几人。","抚字久烦熊轼重，澄清今睹豸冠新。","乱山啼鸟蛮烟里，深树蟠蛇獠水滨。","何幸明时建官府，会持轻典播皇仁。"]},{"t":"送胡士琏贵州按察使 其二","f":"七言律诗","c":["圣主恤民频有诏，远臣宣化岂无闻。","激扬自古关王政，表率于今仗使君。","淮水扬帆侵晓月，楚皋飞旆拂秋云。","独嗟二十年相好，复此匆匆惜袂分。"]},{"t":"送彭士扬归西昌 其一","f":"七言律诗","c":["乡山南望飞云外，万里还家綵服成。","心事已同秋水净，宦情浑似晚烟轻。","亦知衰薄惭闾里，且复欢娱慰父兄。","后夜光辉动牛斗，书船应溯豫章城。"]},{"t":"送彭士扬归西昌 其二","f":"七言律诗","c":["故家独抱遗经在，蚤有清名动缙绅。","致礼特烦东道主，承欢常恋北堂亲。","龙洲晚色明红树，鱼浦秋波漾白蘋。","自是思归归未得，可堪长日送归人。"]},{"t":"送罗知州还广德","f":"七言律诗","c":["蓟门二月柳初青，未有长条折赠行。","远道共怀羁旅意，同乡不尽别离情。","花临河上家家发，山过淮南处处清。","民吏桐川迎望久，经游且莫滞双旌。"]},{"t":"陈颀佥事挽诗","f":"七言律诗","c":["早岁贤科擢俊英，明时宪府佐澄清。","常持风裁民皆畏，独以宽平政自成。","万里趋朝淹客舍，几人含泣送铭旌。","孤儿扶柩南闽路，落月啼乌最怆情。"]},{"t":"周公明教谕半竹轩","f":"七言律诗","c":["先生潇洒溪园秀，与竹从来金石交。","作室不教全代瓦，隔尘还已胜编茅。","清宜帐下诸生咏，俭任门前俗客嘲。","更傍石栏移数挺，閒常风月听笙匏。"]},{"t":"赋得花园送梁主事","f":"七言律诗","c":["地近南城尺五天，万家繁盛似云连。","花熏歌妓楼中勺，柳映行人陌上鞯。","来往纷纷皆驻毂，别离款款更张筵。","知君过此频回首，心恋彤墀玉陛前。"]},{"t":"寄思贻兄","f":"七言律诗","c":["兄弟分携总白头，楚云烟树思悠悠。","每闻夜雨怀连榻，屡看秋鸿独倚楼。","京国衣裳淹日月，乡园梦寐绕松楸。","金盘原上青山下，投老归田共饭牛。"]},{"t":"南山停云张澈郎中求赋","f":"七言律诗","c":["门对南山紫翠深，白云长日抱山岑。","清连飞涧垂朝彩，幽傍悬萝驻夕阴。","五色会看光捧日，九霄终待出为霖。","松楸只在微茫下，早晚从知系寸心。"]},{"t":"送萧雅容郎中归南京吏部","f":"七言律诗","c":["都门新酒郁金香，窈窕筝弹陌上桑。","烟柳千丝牵别恨，春花万点映行装。","碧山近带金陵郭，白雪清含粉署郎。","官府日长无一事，寄诗频到五云坊。"]},{"t":"曾复铉雪舫斋","f":"七言律诗","c":["傍溪斋舍小于舟，含素凝华曙影浮。","已喜虚明宜宴坐，何妨安稳寄寒流。","檐前风絮疑翻浪，窗外瑶林欲隐洲。","自有诗书可娱兴，不消更向剡中游。"]},{"t":"送尤文度赴贵州参议兼寄武昌故旧","f":"七言律诗","c":["三十年前江汉上，清风潇洒共襟期。","折兰閒咏离骚赋，看竹频过孝感祠。","已幸两京重论旧，何堪万里又分岐。","故人相遇应相问，为道非才负圣时。"]},{"t":"送淮安刘千户致仕归吉水","f":"七言律诗","c":["二十承官累策勋，腰间宝剑动星文。","老辞淮水归文水，閒谢青云向白云。","邻里应怀前学士，儿童争识旧将军。","芙蓉峰下沧洲曲，时采林芳与客分。"]},{"t":"刘氏松筠轩","f":"七言律诗","c":["西昌城西松竹深，开轩幽绝坐繁阴。","常疑白昼起雷雨，还乐清夜闻璆琳。","一从蓟北淹羁旅，十载天涯思故林。","亦有茅堂傍东郭，白头南望最关心。"]},{"t":"送刘生","f":"七言律诗","c":["客舍馀春雨正繁，怜渠万里到柴门。","相看已是诸孙行，渐长能知大父恩。","共爱名驹轻道路，又逢新雁忆乡园。","松筠轩里遗书在，归约良朋更讨论。"]},{"t":"挽孙子充","f":"七言律诗","c":["金璧承家好弟兄，至今乡里忆持平。","早逢兵乱真能养，晚避徵书不爱名。","流水青山遗旧隐，白云芳草閟新茔。","相思岂必曾相识，一读铭文已怆情。"]},{"t":"李县丞之官临皋","f":"七言律诗","c":["小年闾巷共嬉游，邂逅京华总白头。","奉使曾持巴郡檄，之官又买潞河舟。","岭南翠雾含津树，海上红霞映县楼。","怀抱公馀清似水，题诗还忆寄中州。"]},{"t":"尹道冲八十受封","f":"七言律诗","c":["萧散春秋八帙高，少年曾署华州曹。","恩封初出麒麟殿，宫锦新裁獬豸袍。","玉屑丹砂和石髓，青山碧树映林皋。","仙人自在烟霞外，五色凌云有凤毛。"]},{"t":"送钱侍读","f":"七言律诗","c":["日上榑桑丽九天，蓬莱高阁五云连。","才华久在论思地，明圣方需侍从贤。","归旆晓飞河济外，文星夜映斗牛边。","全家帝泽沾幽显，锦诰翔鸾百代传。"]},{"t":"送彭毓敬","f":"七言律诗","c":["临清小邑俯河滨，学馆萧条迥绝尘。","谈道胜为百里宰，开筵常接两京人。","风霜跋涉愁堪老，乡里交游意独亲。","但有声华光帝命，相逢不恨别离频。"]},{"t":"送龙公常之建宁驿丞","f":"七言律诗","c":["咸淳进士衡州佐，异代风流见远孙。","谒选三年依北阙，承恩二月发南辕。","官程僻远稀迎客，廨宇清幽不闭门。","碧水丹山足閒暇，频收书册玩微言。"]},{"t":"早入夭寿山候陪祭长陵 其一","f":"七言律诗","c":["尘起山中失路蹊，肩舆扶过石桥西。","夜深风露寒仍浅，月转星河影渐低。","傍涧几人同驻马，隔林何处屡闻鸡。","东方立待曈昽曙，紫殿前头望不迷。"]},{"t":"早入夭寿山候陪祭长陵 其二","f":"七言律诗","c":["万里苍梧去不还，宫车千古閟桥山。","日华閒映芙蓉殿，云气深连虎豹关。","扶病此时瞻玉几，伤心何处望龙颜。","遗臣泣尽馀年泪，天上乌号不可攀。"]},{"t":"送袁止安太常受诰后还馀干 其一","f":"七言律诗","c":["清庙沈沈接泰坛，十年斋洁领祠官。","奏章屡上红云殿，赐服曾无白玉冠。","常有道心如镜净，由来公署带冰寒。","新承天上丝纶宠，归及番昜父老看。"]},{"t":"送袁止安太常受诰后还馀干 其二","f":"七言律诗","c":["一鹤南飞自玉京，江东人识步虚声。","色分玉井芙蓉秀，气挹金茎沆瀣清。","道术不须丹液法，仙家元住白云城。","还携龙虎山中侣，共向蓬莱顶上行。"]},{"t":"送袁止安太常受诰后还馀干 其三","f":"七言律诗","c":["萧散浮云流水踪，少年湖海与君同。","岂知黄鹤楼前别，又向苍龙阙下逢。","圭组有时还暇逸，琴书随意共从容。","无应俱傍西江住，独自蒲帆趁北风。"]},{"t":"送李永怀归东平","f":"七言律诗","c":["霜花初下雁南飞，葭菼苍苍柳欲稀。","落日故人千里别，寒风汶水一帆归。","盛年典郡民皆爱，清代成名志不违。","几度都门聚还散，何时同返故园扉。"]},{"t":"谒长陵","f":"七言律诗","c":["忆昔六龙升御日，最先承诏上銮坡。","论思虚薄年华远，霄汉飞腾宠命多。","空有赤心常捧日，不禁清泪欲成河。","文孙继统今明圣，供奉无能奈老何。"]},{"t":"谒献陵","f":"七言律诗","c":["海宇洪熙戴至尊，愚臣殿陛最蒙恩。","常依黼扆承清问，每荷纶音奖直言。","万古兹山藏玉剑，九霄何路从金根。","馀生莫罄㳙埃报，血泪横膺不忍论。"]},{"t":"送陈正伦御史赴南阳知府","f":"七言律诗","c":["盛时冠豸兼衣绣，柏府霜台岁已深。","宦达共嗟门似水，家贫新赐带横金。","褰帷绿野观春稼，拄笏黄堂对晓岑。","正已斋中有馀暇，青编还究古人心。"]},{"t":"酬张子俊中书惠画","f":"七言律诗","c":["不尽平生山水兴，劳君健笔写清幽。","流云欲送千峰雨，飞瀑深涵五月秋。","玉笋匡庐浑在目，天台秦望亦忘忧。","白头经济曾何补，只好投簪约共游。"]},{"t":"太常丁博士升工部员外赴南京","f":"七言律诗","c":["颂台迢递切红云，博士官閒净俗氛。","礼典曾陪青琐议，仙韶常到紫坛闻。","蓟门柳暗欣簪盍，潞渚荷香惜袂分。","此去升迁展才用，共谁时论考工文。"]},{"t":"送江御史兼寄林懋弘","f":"七言律诗","c":["十年冠豸侍明廷，词苑编摩况有声。","不效䧹鹯驰世誉，直将冰檗重台评。","吴城霜下迎骢马，浙水秋高驻旆旌。","应共三山林宪使，玉壶寒露烱双清。"]},{"t":"送陈时显归南京兼简广哲 其一","f":"七言律诗","c":["联官玉署多年别，考绩金台两度逢。","往昔知心成落落，即今分手复匆匆。","蓟门雨挟风声急，潞渚波连海气浓。","无限离情阻相送，青山杳杳树濛濛。"]},{"t":"送陈时显归南京兼简广哲 其二","f":"七言律诗","c":["素襟不受一尘缁，文苑英游共所知。","旧羡丰姿清似玉，今看衰鬓亦成丝。","柏堂昼掩无公务，竹槛春吟有妙辞。","想共东邻欧主事，清谈常过夕钟时。"]},{"t":"寄胡若思宾客","f":"七言律诗","c":["乐静忘忧养性灵，豫章城外一茅亭。","窗涵南浦千寻碧，门对西山万叠青。","每羡林泉归倦翼，独怜江海尚浮萍。","已知安邑浑无累，犹有人求伏氏经。"]},{"t":"己酉元夕偕行俭学夔公绪百鍊并携稻秫市中观灯遂过退庵小酌即席赋诗得谁字","f":"七言律诗","c":["貂帽藜筇信所之，良朋稚子暮追随。","物情已觉春光好，烛影还于月色宜。","一世缁尘空老大，几人白首共襟期。","今宵且对灯前醉，来岁灯前知对谁。"]},{"t":"送刘参议赴广东","f":"七言律诗","c":["二十馀年联近侍，挥毫常在凤凰池。","每怜分署疏欢聚，况及逢春又别离。","满地绿阴榕树合，绕檐红颗荔枝垂。","时平画省多公暇，预想清吟续隐之。"]},{"t":"早朝应制","f":"七言律诗","c":["天香初引玉炉熏，日照龙墀綵仗分。","阊阖九重通御气，蓬莱五色护祥云。","班联文武齐鹓鹭，庆合华夷致凤麟。","圣主临轩万年寿，敬陈明德赞尧勋。"]},{"t":"从狩密云早发次韵幼孜","f":"七言律诗","c":["鸡鸣沧海浴朝暾，起换征裘倒别尊。","上马好音喧鼓吹，逼人清气满乾坤。","旌旗云拥中军幄，剑戟霜明列校屯。","载笔从容侍田猎，暮年有幸共承恩。"]},{"t":"驻跸峪口少师蹇公少保金公尚书胡公及予奉旨先归道中风寒小憩洪胜寺","f":"古风","c":["圣主深恩恤老臣，赐归先渡白河滨。","御营昼日承三接，驿路飙风共四人。","满地寒芜行雉?，谁家荒冢伏麒麟。","山僧颇解空王法，延客焚香话六尘。"]},{"t":"送潘景昭致仕归永嘉","f":"七言律诗","c":["素节清名玉不如，忽承优诏赐閒居。","青坊旧振郎官笔，金匮新藏史氏书。","归橐人嗟一羽重，悬车谁及二毛初。","黄花翠竹温州郭，晏岁高情乐有馀。"]},{"t":"送吴敏德南京佥都御史","f":"七言律诗","c":["九重图治任才贤，白简凝霜载画船。","共喜芝兰出萧艾，已知鸾凤异鹰鹯。","淮山渺渺飞云外，蓟树亭亭落照前。","相好相违重相忆，好音时听路人传。"]},{"t":"丹徒何彦澄皆春堂","f":"七言律诗","c":["百亩药畦春浩荡，济人浑是太和心。","泉香橘畔苏眈井，花满云边董奉林。","灵剂不须酬白璧，丹砂自可致黄金。","南徐城下沧江水，会比何家阴德深。"]},{"t":"送张嘉会赴封川","f":"七言律诗","c":["绣衣前日下台端，百里清霜绿幕寒。","不恨逢人双眼白，共怜为国寸心丹。","苍茫晏岁迁除远，缱绻同乡执别难。","自有平生冰操在，岭梅还似旧时看。"]},{"t":"过鹞儿岭巡检司悼萧长史 其一","f":"七言律诗","c":["王门辅相真公选，老病思归竟不归。","尽职总知行直道，爱身翻见蹈危机。","山笼晓雾深迷戍，滩响寒涛近绕扉。","白首来经迁谪地，感怀惟有泪沾衣。"]},{"t":"过鹞儿岭巡检司悼萧长史 其二","f":"七言律诗","c":["万里边隅千叠山，桑乾河上閟榛菅。","向来物论嗟投玉，至竟天恩未赐环。","早以传经重闾里，曾看奏疏动朝班。","平生一片贞松色，犹在交游梦寐间。"]},{"t":"送陈廷器通政","f":"七言律诗","c":["公材士行总推贤，宪府儒宫近屡迁。","共识丹心明白日，也应华发叹流年。","芙蓉浦溆秋风后，鸿雁汀洲夕照前。","此地相逢又相送，交情长为别离牵。"]},{"t":"赐文渊阁五色菊一本应制","f":"七言律诗","c":["一簇秋香护锦屏，联芳竞彩自天成。","何须芝瑞矜三秀，已似奎躔聚五星。","开处正当彤陛好，赐来还称玉堂清。","世传此植能颐寿，万岁千秋祝圣明。"]},{"t":"绍兴王氏居竹轩","f":"七言律诗","c":["万玉森森翠作林，王家清致自山阴。","开轩六月暑气薄，闭门一径秋云深。","晴当霄汉看鸾舞，夜或风雨闻龙吟。","岁寒栗冽不改色，共矢平生金石心。"]},{"t":"庆行俭初度并赠礼闱校文之行 其一","f":"七言律诗","c":["三朝冠绂殿东头，人物当今第一流。","银汉奎文光午夜，玉壶寒露炯清秋。","终知鼎鼐归台辅，共待经纶阐大猷。","二月帝城春似海，寿筵先醉紫金瓯。"]},{"t":"庆行俭初度并赠礼闱校文之行 其二","f":"七言律诗","c":["高门奕奕县东西，文献杨王自昔齐。","当代飞腾联玉署，半生华宠共金闺。","风霜樗散惭空老，霄汉鹏抟望不迷。","未许明时慕丘壑，须将旱岁作云霓。"]},{"t":"庆行俭初度并赠礼闱校文之行 其三","f":"七言律诗","c":["三载兴贤选俊英，九重宣诏付铨衡。","从来节操推公道，况是文章擅老成。","春院下帘心独苦，夜灯开卷眼偏明。","抡才为国真无忝，预咏薹莱颂太平。"]},{"t":"送孙修撰","f":"七言律诗","c":["五色衣裁绣锦明，三年归谒称深情。","芙蓉浪飐娟娟净，杨柳风生澹澹清。","帆影晓经扬子渡，剑光秋望富州城。","词垣官俸堪多酿，遥想高堂聚德星。"]},{"t":"赐游西苑同诸学士作 其一","f":"七言律诗","c":["东风御苑物华新，吉日游观命近臣。","金瓮特颁千日酝，玉盘兼赐八珍淳。","翠含杨柳桥边雾，香汎芙蓉水上云。","鱼跃鸢飞皆化育，须看海宇颂皇仁。"]},{"t":"赐游西苑同诸学士作 其二","f":"七言律诗","c":["广寒高出倚晴霄，清暑开临螮蝀桥。","凤阙九重通窈窕，龙章五彩护岧峣。","霞明翠浪成漂锦，风振琼林协奏韶。","山水足供仁智乐，千春万岁奉唐尧。"]},{"t":"赐游西苑同诸学士作 其三","f":"七言律诗","c":["日照千门万户开，参差楼观出飞台。","地灵长看红云绕，天近时迎翠辇来。","绝好西山如华岳，何须东海觅蓬莱。","微臣几度陪游豫，欲继卷阿愧乏才。"]},{"t":"赐游西苑同诸学士作 其四","f":"七言律诗","c":["玄洲阆苑五云迷，紫殿彤楼众岫低。","日射飞甍金署榜，虹连阁道玉为梯。","洒筵好雨霏微过，傍席清禽睍睆啼。","欲报深恩何以祝，皇图帝寿与天齐。"]},{"t":"送孙从吉主事","f":"七言律诗","c":["河上蒹葭初著霜，临河挝鼓发官航。","面承天语朝辞阙，身著宫袍昼近乡。","锦树拂云明使旆，碧山如画对仙郎。","由来襟抱清于玉，写得梅花好寄将。"]},{"t":"送解祯期兼忆大绅","f":"七言律诗","c":["万里赐环辽海外，凤池依旧宠恩浓。","共欣遭际承千载，又沐优閒谢九重。","草草离觞对寒菊，迢迢归棹逐秋鸿。","临岐重有伤心处，不见名家阮嗣宗。"]},{"t":"赠族侄之勉","f":"七言律诗","c":["盛时杨氏三登仕，文献西昌第一家。","诸老仪刑随逝水，百年谱牒看分瓜。","远来论旧欢娱浅，临别题诗感慨赊。","独近五云洲畔住，好敦忠信作生涯。"]},{"t":"斋宿次韵曾学士","f":"七言律诗","c":["退朝斋閤息精神，接席香帷总缙绅。","茶送蒙山兼顾渚，琴弹子夜又阳春。","坐闻玉漏传西掖，起看龙光绕北辰。","吉日郊禋集繁祉，庆成预拟拜枫宸。"]},{"t":"送萧生下第南归","f":"七言律诗","c":["少年怀宝谒京畿，又向明时下第归。","蓟北莺啼春后满，淮南树色雨中微。","手披经史常忘食，家傍园林静掩扉。","终待秋风六翮健，九霄云净看高飞。"]},{"t":"怀来应制","f":"七言律诗","c":["霜红碧树被岩阿，流水青山喜再过。","田事总知今岁好，人烟况比昔年多。","彩云飞盖随雕辇，白玉行尊载紫驼。","圣主时平此巡省，会闻游豫出讴歌。"]},{"t":"留别罗学古员外并解佩剑赠之","f":"七言律诗","c":["紫塞西风九月秋，千官祗从六龙游。","故人邂逅能青眼，老我驱驰已白头。","马上拥貂晨共发，尊前烧蜡暮相留。","关城又是分襟处，解赠吴钩慰别愁。"]},{"t":"上清袁止安寄诗余以写竹奉酬并步来韵","f":"七言律诗","c":["京华一别岁频更，长忆同年老弟兄。","轩冕无心暂同俗，山林有道竟违荣。","石田过雨琼芝润，金箓开函玉女清。","貌得昆丘青凤羽，因风遥答故交情。"]},{"t":"题竹送周侍郎","f":"七言律诗","c":["雁下蒹葭泽国寒，扁舟独去路漫漫。","年来已恨旧交少，老至偏伤远别难。","亲见谋猷禆国计，极知劳瘁济民艰。","一竿淇上清于玉，持赠南州岁晚看。"]},{"t":"送刘巡检赴广东","f":"七言律诗","c":["奏最晨看拜紫宸，升官遄赴海南滨。","身趋玉陛祗辞主，家过金川喜觐亲。","红蓼桂花明水驿，青松柳叶暗蛮津。","休言弓马非吾事，会有恩威服远人。"]},{"t":"萧时中挽诗","f":"七言律诗","c":["当日兴贤对大廷，天门金榜冠群英。","一经勤苦承家世，千载遭逢荷圣明。","溟海鹍鹏真自致，兰苕翡翠不胜清。","可怜万里归埋玉，欲赋招魂惨不成。"]},{"t":"送张宗海修撰致仕","f":"七言律诗","c":["京国交情三十载，别离忧绪百千端。","故人有道相违远，多病无能自效难。","已看文章留玉署，也知江海忆金銮。","扶摇九万公先奋，会待云霄接羽翰。"]},{"t":"送梁绍辉三衢教授","f":"七言律诗","c":["两朝国史奏书成，济济官曹进秩荣。","郡守方需汉博士，泮宫行对鲁诸生。","莺啼燕语连城绿，水色山光绕郭清。","应似高斋赵阅道，捲帘吟咏畅幽情。"]},{"t":"送崇述谒告还乡并问讯若思","f":"七言律诗","c":["白发朝冠在石渠，故园松竹梦幽居。","暂封国史收金匮，荣拜天恩下玉除。","晓岸绿芜飞燕子，春江新水上鲥鱼。","经过定见颐庵老，为谢衰迟久旷书。"]},{"t":"自题东皋小像","f":"七言律诗","c":["玉华之东鸥渚浔，柴门萧萧松竹阴。","平生自乏经济略，抱瓮已忘荣䘵心。","一日天书照云谷，十年蓬鬓戴朝簪。","文章无补治世用，矫首南山烟树深。"]},{"t":"送冯钦训郎中持节使安陆","f":"七言律诗","c":["金册颁恩玉玺封，秋清四牡出南宫。","九华飞翠迎江上，白雪操弦候郢中。","使者通经才不忝，亲王祗命礼兼隆。","故家文献存遗谱，归过沙溪觅姓冯。"]},{"t":"送柴侍郎","f":"七言律诗","c":["大将行边净楚氛，多才司马更能文。","岑参陇外多传赋，韩愈淮西力赞勋。","刁斗三更鸣塞月，旌旗千队拂关云。","阵前敌忾功谁最，早致封章玉陛闻。"]},{"t":"吴教授席上同伯阳汲井咏","f":"五言绝句","c":["皎洁如明镜，铜瓶下愈深。","妆成不照影，应恐坠金簪。"]},{"t":"长沙三咏 其一 定王台","f":"五言绝句","c":["台高登望迥，台平驰射宽。","平高各有志，民力空独难。"]},{"t":"长沙三咏 其二 贾谊井","f":"五言绝句","c":["迢迢俯碧甃，濛濛翳紫苔。","犹传贾太傅，知历汉朝来。"]},{"t":"长沙三咏 其三 马王宫","f":"五言绝句","c":["君王全盛日，宫殿此沈沈。","歌舞无人见，唯馀钟梵音。"]},{"t":"送龙参归南昌","f":"五言绝句","c":["渌水明堪染，桃花吐未齐。","君归渡南浦，春草正萋萋。"]},{"t":"画兰","f":"五言绝句","c":["湘灵结芳馨，含思望遥浦。","夫君殊未来，兰佩徒容与。"]},{"t":"姚山给事求山居六咏 其一 山斋","f":"五言绝句","c":["春至还往稀，日照山窗静。","时有石泉鸣，泠泠入孤听。"]},{"t":"姚山给事求山居六咏 其二 玩古轩","f":"五言绝句","c":["常好古人言，玩索此轩中。","谁言千载上，不与此心同。"]},{"t":"姚山给事求山居六咏 其三 竹涧","f":"五言绝句","c":["修竹荫南涧，翛翛净于洗。","独往坐清阴，弹琴对流水。"]},{"t":"姚山给事求山居六咏 其四 清阴谷","f":"五言绝句","c":["阳和二三月，绿柳垂满地。","春风吹暂开，望见南山际。"]},{"t":"姚山给事求山居六咏 其五 白石坡","f":"五言绝句","c":["松间白石坡，复带莓苔碧。","常有素心人，独行看鸟迹。"]},{"t":"姚山给事求山居六咏 其六 野亭","f":"五言绝句","c":["秋日野亭上，四望尽青山。","飞鸟去无极，白云相对閒。"]},{"t":"过谷亭","f":"五言绝句","c":["明月转樯竿，露下孤篷湿。","欲系谷亭舟，沙头风正急。"]},{"t":"早发长沟","f":"五言绝句","c":["秋水被堤岸，牵舟不可涉。","渺渺见平湖，北风吹荷叶。"]},{"t":"画鱼","f":"五言绝句","c":["水清菱叶稀，洞见溪流下。","出入多慎重，恐有垂纶者。"]},{"t":"临川谢氏双节堂 其一","f":"五言绝句","c":["独抱孤儿在，空帷泣夜深。","谁家姑与妇，相继柏舟吟。"]},{"t":"临川谢氏双节堂 其二","f":"五言绝句","c":["谢氏悬双璧，团团似月圆。","光辉百年后，长为照临川。"]},{"t":"题五清小画 其一","f":"五言绝句","c":["昔年林下住，扫石坐成群。","已愧颜光䘵，幽情咏五君。"]},{"t":"题五清小画 其二","f":"五言绝句","c":["山林含古翠，萧爽水亭虚。","岂乏幽栖者，临清此玩鱼。"]},{"t":"题五清小画 其三","f":"五言绝句","c":["何人不扰扰，一棹独萧閒。","天霁疏林外，乘流坐看山。"]},{"t":"题五清小画 其四","f":"五言绝句","c":["不学袁安卧，悠然敞素轩。","山林明一色，清意满乾坤。"]},{"t":"题五清小画 其五","f":"五言绝句","c":["南枝与北枝，葳蕤动寥廓。","自有岁寒心，不随横吹落。"]},{"t":"题兰 其一","f":"五言绝句","c":["澧浦月浮津，曾逢解佩人。","至今香露夕，思杀楚乡春。"]},{"t":"题兰 其二","f":"五言绝句","c":["骑马向长安，冠尘每日弹。","不知幽谷里，谁坐揽芳兰。"]},{"t":"度石门岭","f":"五言绝句","c":["石径浮云上，攀缘险莫当。","一心祗扈跸，不敢戒垂堂。"]},{"t":"萧氏石冈十景诗为省身赋 其一 石冈桥","f":"五言绝句","c":["君家石冈侧，门对石桥幽。","桥下澄源水，还归萧峡流。"]},{"t":"萧氏石冈十景诗为省身赋 其二 石壁","f":"五言绝句","c":["危石翠如削，影浸澄湖波。","六月不知暑，香风生芰荷。"]},{"t":"萧氏石冈十景诗为省身赋 其三 青泥滩","f":"五言绝句","c":["近接金鱼埧，来往弄轻桡。","水清下见底，白石如琼瑶。"]},{"t":"萧氏石冈十景诗为省身赋 其四 梁家潭","f":"五言绝句","c":["江流汇为潭，其下深无极。","时有云雾兴，疑是蛟龙宅。"]},{"t":"萧氏石冈十景诗为省身赋 其五 长泒洲","f":"五言绝句","c":["逶迤长泒洲，近带珠林浦。","八月秋风清，瀰漫熟禾黍。"]},{"t":"萧氏石冈十景诗为省身赋 其六 箬湖砦","f":"五言绝句","c":["嶕峣紫霞表，周回石如栉。","曾逢百岁人，閒说兵戈日。"]},{"t":"萧氏石冈十景诗为省身赋 其七 拜雨亭","f":"五言绝句","c":["寸云起东谷，行空散为霖。","殷勤望拜者，宁识云无心。"]},{"t":"萧氏石冈十景诗为省身赋 其八 王仙祠","f":"五言绝句","c":["骑鹤去已远，庭馀昔年树。","扰扰祈灵人，鼓钟动朝暮。"]},{"t":"萧氏石冈十景诗为省身赋 其九 吉祥庵","f":"五言绝句","c":["石冈清绝处，兰若傍岩开。","年远僧稀少，经廊生绿苔。"]},{"t":"题四皓子期子猷太白四图 其一","f":"五言绝句","c":["万叠青山外，林居頫涧滨。","翛然四老者，知是茹芝人。"]},{"t":"题四皓子期子猷太白四图 其二","f":"五言绝句","c":["潇洒林下居，清泠膝上琴。","高山与流水，千载一知音。"]},{"t":"题四皓子期子猷太白四图 其三","f":"五言绝句","c":["冻合千山雪，荒村愁未眠。","谁知乘兴者，夜棹剡溪船。"]},{"t":"题四皓子期子猷太白四图 其四","f":"五言绝句","c":["灵岳乾坤秀，飞泉河汉垂。","超然山水兴，身在白云涯。"]},{"t":"画牛 其一","f":"五言绝句","c":["万物各有适，逍遥大化中。","当知画史意，重有育民功。"]},{"t":"画牛 其二","f":"五言绝句","c":["策马二十年，常怀颠蹶忧。","蚩蚩弄雏者，真乘百斛舟。"]},{"t":"画牛 其三","f":"五言绝句","c":["散诞春耕馀，牧儿亦有乐。","常以蓑笠随，为防风雨作。"]},{"t":"画牛 其四","f":"五言绝句","c":["牧人归不早，溪头风雨急。","还顾母子情，相追未相及。"]},{"t":"居庸关弹琴峡","f":"五言绝句","c":["峡石记弹琴，泠泠流水音。","不知行路者，谁有听琴心。"]},{"t":"沙城","f":"五言绝句","c":["临水一荒城，风沙常眯目。","城里半流人，荆扉掩茅屋。"]},{"t":"揽辔","f":"五言绝句","c":["款段独行迟，揽辔亦自适。","天清无片云，遥遥见山色。"]},{"t":"晓晴","f":"五言绝句","c":["周庐夜半雨，萧萧不成响。","晓起看晴明，雪满青山上。"]},{"t":"赠筇竹","f":"五言绝句","c":["爱尔生正直，仗尔扶衰老。","道路有险夷，出入常相保。"]},{"t":"代筇答","f":"五言绝句","c":["正直余何有，道义卿所持。","但自保坚固，无论险与夷。"]},{"t":"龙虎台","f":"五言绝句","c":["高台久已倾，蒿蓬纷簇簇。","犹存龙虎名，常散牛羊牧。"]},{"t":"通州 其一","f":"五言绝句","c":["城倚红云下，门临绿水滨。","宝鞍驰骏马，多是帝京人。"]},{"t":"通州 其二","f":"五言绝句","c":["清浅潞河流，常维万里舟。","越罗将蜀锦，充满潞滨楼。"]},{"t":"题画 其一","f":"五言绝句","c":["仙桃千岁红，青爵相因依。","知是瑶池使，东来几日归。"]},{"t":"题画 其二","f":"五言绝句","c":["花开檐卜林，双禽弄香雪。","动植乘化机，当此艳阳月。"]},{"t":"画鹑 其一","f":"五言绝句","c":["秋至禾黍熟，霜含枸杞红。","鹑衣自有适，潇洒立西风。"]},{"t":"画鹑 其二","f":"五言绝句","c":["疏菊吐幽华，清鹑澹无与。","独立亦翛然，襳襹艳文羽。"]},{"t":"题画","f":"古风","c":["鸟啼花落春暮，云白山青雨馀。","溪南有客访隐，林下何人著书。"]},{"t":"晚发安山驿和答金公素 其一","f":"古风","c":["津头卖瓜未过，村中酿黍才沽。","薄暮安山道上，萧萧白苇黄榆。"]},{"t":"晚发安山驿和答金公素 其二","f":"古风","c":["荒渚菰蒲带雨，隔河篱落飞烟。","淮南渺渺何处，怅望秋鸿去边。"]},{"t":"题山水小画赠康甥归西昌","f":"古风","c":["凫渚斜通鹤径，水亭静对林扉。","群峰云际相待，一棹江南未归。"]},{"t":"荨麻林早发","f":"古风","c":["四更零露衣湿，十里飘风帽斜。","足底河流石涩，马头月色云遮。"]},{"t":"次韵王山人二月十六日对雪","f":"七言绝句","c":["初和柳絮飘侵槛，复共梨花舞傍人。","一种妍华看不定，只凭高调和阳春。"]},{"t":"次韵题向诚所藏苏明远写菊","f":"七言绝句","c":["金门五朝一下直，静乐轩中坐日长。","为看秋花有真意，只题诗句不焚香。"]},{"t":"次韵蒋立恭清明上冢","f":"七言绝句","c":["去年载酒东郊路，水畔花前醉咏诗。","今日垄头空洒饭，伤心思忆去年时。"]},{"t":"枯木竹石为王山人题 其一","f":"七言绝句","c":["苍楠翠柏含烟雾，总以抡才入庙廊。","自在空山名散木，珊瑚石畔老冰霜。"]},{"t":"枯木竹石为王山人题 其二","f":"七言绝句","c":["独持贞操立云根，春雨秋风阅历频。","不觉流年成老大，眼中浑见凤毛新。"]},{"t":"寄萧德通兄弟 其一","f":"七言绝句","c":["金殿瑶阶紫禁闱，戴星趋拜戴星归。","一官侍从浑无补，惭愧当年旧布衣。"]},{"t":"寄萧德通兄弟 其二","f":"七言绝句","c":["桃花源上昔投閒，长忆君家玉树间。","酒散凉亭红日晚，石台临水看青山。"]},{"t":"题李伯高画","f":"七言绝句","c":["芙蓉峰下沧洲畔，碧水回环漾白沙。","闻说草堂邻杏坞，年年花发照春霞。"]},{"t":"题金侍讲云山障子","f":"七言绝句","c":["浮云满山如玉洁，山光下映幽人居。","柴门落叶可俯拾，林下日长应著书。"]},{"t":"玉峡山人","f":"七言绝句","c":["玉峡山人雪满颠，初承徵诏远朝天。","赐归还向峡中去，春雨沤波好放船。"]},{"t":"寄思贻兄 其一","f":"七言绝句","c":["思贻先生守道园，池边竹下敞幽轩。","焚香坐隐乌皮几，隔水苍山正对门。"]},{"t":"寄思贻兄 其二","f":"七言绝句","c":["溪上流虹映壁经，溪头春树拂檐青。","小车閒日何人到，会有光华动德星。"]},{"t":"寄思贻兄 其三","f":"七言绝句","c":["未报君恩未乞身，每看南雁重伤神。","清溪亦是朝宗水，遥想临流忆远人。"]},{"t":"寄思贻兄 其四","f":"七言绝句","c":["螺湖盘古白云堆，忆著常因梦里回。","得似篮舆引诸弟，年年霜露及时来。"]},{"t":"寄蒋用文院判 其一","f":"七言绝句","c":["冬风淅沥隔窗纱，丹室红光蔼曙霞。","想见病馀清似鹤，閒研玉雪咏梅花。"]},{"t":"寄蒋用文院判 其二","f":"七言绝句","c":["旦气清明体力轻，未堪鸣佩拜彤庭。","缉熙斋里熏金鸭，应著医经几卷成。"]},{"t":"简胡学士索木芙蓉栽 其一","f":"七言绝句","c":["牡丹芍药皆姱丽，总怯风霜不耐秋。","只好芙蓉伴修竹，清华晚映北窗幽。"]},{"t":"简胡学士索木芙蓉栽 其二","f":"七言绝句","c":["闻种拒霜遮水槛，春前分乞数枝栽。","总知宋玉才情绝，会约花时作赋来。"]},{"t":"挽颜子明 其一","f":"七言绝句","c":["五彩春霞绣绮袍，文章无复看挥毫。","相思惟有南山色，彷佛当年意气高。"]},{"t":"挽颜子明 其二","f":"七言绝句","c":["贵里侯家甲第开，经过长是勒车回。","守玄宅里寻常到，此去何因更一来。"]},{"t":"挽颜子明 其三","f":"七言绝句","c":["南浦江山一旦空，行吟谁复继高踪。","薇垣柏府多知己，犹为传经惜马融。"]},{"t":"九日怀黄学士 其一","f":"七言绝句","c":["年年赐宴捧萸觞，同沐皇恩近御床。","今日江南望江北，不知何处醉重阳。"]},{"t":"九日怀黄学士 其二","f":"七言绝句","c":["去时相约看黄花，花满园林未到家。","惆怅别来无一字，西风极目雁行斜。"]},{"t":"送梁本之纳溪教谕 其一","f":"七言绝句","c":["西过泸洲是纳溪，锦江还在纳溪西。","此去家乡五十里，青山朝暮对猿啼。"]},{"t":"送梁本之纳溪教谕 其二","f":"七言绝句","c":["烟楠雾柏富奇材，梁柱还须匠石裁。","刀布不劳赍计吏，圣朝今选学官来。"]},{"t":"早至仪真","f":"七言绝句","c":["白沙岸头秋气清，仪真郭里早潮生。","五云北望金台路，初是朝天第一程。"]},{"t":"早至淮安","f":"七言绝句","c":["百丈牵船夜未休，满衣凉露不胜秋。","前林欲近闻鸡唱，城郭昽昽见楚州。"]},{"t":"夜过徐州","f":"七言绝句","c":["怒涛翻河乱石横，牵船上洪初月明。","夜中不辨黄楼处，惟听层城钟鼓声。"]},{"t":"望济宁","f":"七言绝句","c":["疏翠轻红水岸迂，渔家远近映菰蒲。","高城前望晴云下，却记行程是半途。"]},{"t":"花园望北京","f":"七言绝句","c":["黄金宫阙望都门，预喜明朝谒圣君。","万岁山高腾王气，五云天上焕龙文。"]},{"t":"奉天门早见后午被召至右顺门晚退口号","f":"七言绝句","c":["紫禁西连万岁山，宣呼重入觐龙颜。","拜承圣语丁宁训，满袖天香出九关。"]},{"t":"早过良乡","f":"七言绝句","c":["马上风沙拂面飞，凝霜如雪堕征衣。","平明行尽良乡郭，茅屋人家未启扉。"]},{"t":"莫州同王邦彦张伯原饮道傍民家","f":"七言绝句","c":["雄县城南水没路，莫州市里酒如油。","客行相聚且一醉，不见越人空古丘。"]},{"t":"阻风雪德州有怀王邦彦司直","f":"七言绝句","c":["萧条风雪夜深寒，短棹临津欲发难。","却忆故人单骑去，谁家茅店解征鞍。"]},{"t":"重过安山驿怀金公素","f":"七言绝句","c":["共买兰舟北去时，尚书相送此分违。","伤心未抵今朝重，万里承恩只独归。"]},{"t":"送张令赴麻阳","f":"七言绝句","c":["乱山蛮树向人低，遥绾铜章赴五溪。","为想春风与嘉政，新年俱到夜郎西。"]},{"t":"题陆伴读伯阳草书后","f":"七言绝句","c":["兰绕春庭露气清，往年同咏谢宣城。","龙蛇满纸看遗墨，忽乱山阳笛里情。"]},{"t":"题梅送胡方大归庐陵","f":"七言绝句","c":["葭菼萧条半著霜，故人迢递溯归航。","东风无限江南意，因尔牵情万里长。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其一","f":"七言绝句","c":["玉堂新署绿阴凉，日想承宣近御床。","班马雄词真特达，唐虞化日正舒长。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其二","f":"七言绝句","c":["平明阊阖九天开，玉佩趋朝百辟来。","圣主正需调鼎用，诸公应荐和羹梅。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其三","f":"七言绝句","c":["盛世才华翰苑多，龙光星彩贯天河。","自怜同在承恩地，不奈频年远别何。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其四","f":"七言绝句","c":["头白目昏过五十，不禁四体病交攻。","君恩未有涓埃报，却怪书来感叹同。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其五","f":"七言绝句","c":["绣锦传来五色丝，翔鸾翥凤粲离离。","知公头白丹心在，况是文章老不衰。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其六","f":"七言绝句","c":["朝回清坐广文毡，病起閒逃苏晋禅。","了彻六尘成梦觉，迩来三月已无眠。"]},{"t":"胡学士在北京闻予病寄诗慰问次韵奉酬 其七","f":"七言绝句","c":["尽恋长生养性灵，力求大药扣玄扃。","庄生自有逍遥论，不道千龄胜百龄。"]},{"t":"红心驿","f":"七言绝句","c":["马头近见红心驿，茅屋参差半酒家。","潇洒赤栏桥外柳，西风吹折数枝斜。"]},{"t":"夜宿临淮营梦种子 其一","f":"七言绝句","c":["肠断经年隔死生，因何随梦到行营。","营前淮水深千丈，得及人间父子情。"]},{"t":"夜宿临淮营梦种子 其二","f":"七言绝句","c":["绕膝踉跄捧一编，分明梦里见娟娟。","临淮营内中宵月，应照来生未了缘。"]},{"t":"早过宿州","f":"七言绝句","c":["月转西林晓雾收，霜华如雪拥貂裘。","马前清景山无数，带得馀酣过宿州。"]},{"t":"陪谒徐王庙","f":"七言绝句","c":["闵子乡中询父老，徐王庙下驻旂旄。","庙前山势如鸾凤，万古涂山相对高。"]},{"t":"范增墓","f":"七言绝句","c":["千年宝剑无光气，衰草寒烟野水邻。","同是遗骸葬徐土，当时陵母识天人。"]},{"t":"题赵仲穆画马 其一","f":"七言绝句","c":["紫雾团身白玉蹄，权奇倜傥渥洼姿。","王孙惯见升平事，貌得当年入贡时。"]},{"t":"题赵仲穆画马 其二","f":"七言绝句","c":["十二天闲总骏才，追风蹑景是龙媒。","曾随六御临关塞，亲过流沙万里来。"]},{"t":"子启学士见过仆适他出不遇奉简 其一","f":"七言绝句","c":["西城过雨净无泥，杨柳风轻散马蹄。","虚有琴徽待高会，却惭书札负前题。"]},{"t":"子启学士见过仆适他出不遇奉简 其二","f":"七言绝句","c":["东邻西舍总风流，何处垂杨系紫骝。","想见斜阳拥归旆，不同雪夜剡溪舟。"]},{"t":"子启见和再用韵奉简时曾新市马 其一","f":"七言绝句","c":["雨晴沙净不沾泥，新试娇骢白玉蹄。","款款金城坊里去，过门凤字不教题。"]},{"t":"子启见和再用韵奉简时曾新市马 其二","f":"七言绝句","c":["城上西山翠欲流，爱山不骤紫骅骝。","还如扬子江头看，万叠芙蓉近綵舟。"]},{"t":"习礼见和用韵奉酬并简宗琏 其一","f":"七言绝句","c":["玉署词华照紫泥，逢人不慱铸金蹄。","绿杨庭馆閒风月，朝退从容每自题。"]},{"t":"习礼见和用韵奉酬并简宗琏 其二","f":"七言绝句","c":["绿阴池沼擅风流，长系青骡当紫骝。","自爱官曹清似水，不妨书舍小于舟。"]},{"t":"习礼见和用韵奉酬并简宗琏 其三","f":"七言绝句","c":["不解高阳醉似泥，一壶时共荐豚蹄。","半酣藻思如泉涌，锦轴华笺取次题。"]},{"t":"习礼见和用韵奉酬并简宗琏 其四","f":"七言绝句","c":["雅操俱当第一流，逸材千里见骅骝。","閒来同坐北窗下，如在清风李郭舟。"]},{"t":"胡祭酒食葵而病戏用奉简兼谢惠蔬 其一","f":"七言绝句","c":["雨后畦蔬嘉可观，忽闻憔悴卧幽轩。","非是安心无妙法，谁教放手刈葵根。"]},{"t":"胡祭酒食葵而病戏用奉简兼谢惠蔬 其二","f":"七言绝句","c":["万虑澄清不入怀，饭蔬饮水小茅斋。","却惭口腹犹贻累，频致园官菜把来。"]},{"t":"简胡祭酒 其一","f":"七言绝句","c":["重阳醉后又三日，想见黄花绽始多。","门巷深沈无俗客，高斋清坐养天和。"]},{"t":"简胡祭酒 其二","f":"七言绝句","c":["满城冠佩趋朝谒，得似颐庵独自閒。","心与天光共明净，朝朝爽气对西山。"]},{"t":"简胡祭酒 其三","f":"七言绝句","c":["朝来邂逅西江客，报道今年盛有秋。","但得万方同岁稔，吾生贫病不须愁。"]},{"t":"唐人醉归图为金学士题","f":"七言绝句","c":["翩翩六骏出腾骧，醉里衣冠见盛唐。","彷佛开元无事日，不知谁是贺知章。"]},{"t":"正月廿九日戏简仲熙庶子三绝句时邹徙舍城东 其一","f":"七言绝句","c":["萧散双吹碧玉箫，与君同郡复同袍。","金城坊里清如水，却爱东飞学伯劳。"]},{"t":"正月廿九日戏简仲熙庶子三绝句时邹徙舍城东 其二","f":"七言绝句","c":["新岁新斋好著书，文明门里会文儒。","隔邻春酒蒲萄熟，谁绾青丝送玉壶。"]},{"t":"正月廿九日戏简仲熙庶子三绝句时邹徙舍城东 其三","f":"七言绝句","c":["正月已终将二月，城中咫尺见还难。","金门朝籍皆先送，独遣同寮待长官。"]},{"t":"题小画寄史志静 其一","f":"七言绝句","c":["春含竹树翠淋漓，玉立苍苍太古姿。","久别仪曹文翰侣，江南蓟北赠相思。"]},{"t":"题小画寄史志静 其二","f":"七言绝句","c":["为有高情共岁寒，别来相忆访平安。","凭将一片南州意，寄与清曹粉署看。"]},{"t":"金幼孚挽诗 其一","f":"七言绝句","c":["独携书史傍林泉，荣利由来意澹然。","时绕金川看玉笥，未曾轻到县门前。"]},{"t":"金幼孚挽诗 其二","f":"七言绝句","c":["雪崖风节凛飞霜，蕙带兰袆道味长。","剩贮诗书遗诸子，乡人共诧白眉郎。"]},{"t":"金幼孚挽诗 其三","f":"七言绝句","c":["昔岁京华住接邻，论文来往日频频。","十年不见成终古，洒泪东风为故人。"]},{"t":"题画寄思贻兄","f":"七言绝句","c":["多情不忍看离群，况复双清共拂云。","蓟北江南六千里，白头兄弟两乡分。"]},{"t":"非所秋夕寄示康甥 其一","f":"七言绝句","c":["一点寒灯照黯然，哀蛩四壁夜无眠。","傍人解识词垣老，为叹重来未十年。"]},{"t":"非所秋夕寄示康甥 其二","f":"七言绝句","c":["五十无闻将六十，不才孤负宠恩深。","惟应一片清秋月，解照平生报主心。"]},{"t":"非所寄习礼 其一","f":"七言绝句","c":["舍外周遭无隙地，积刍曾畏短檐间。","紫茄绿瓠霜前摘，拟借西园五尺閒。"]},{"t":"非所寄习礼 其二","f":"七言绝句","c":["采采黄花定满枝，东邻西舍共襟期。","银瓶注酒清于玉，醉里题诗看少谁。"]},{"t":"题画","f":"七言绝句","c":["竹树纷纷翠欲迷，山云半敛水禽啼。","何人自有清幽趣，不放扁舟过剡溪。"]},{"t":"南昌罗氏仰高楼 其一","f":"七言绝句","c":["红尘市里浩漫漫，车马东西引避难。","独起高楼出尘外，青山天际卷帘看。"]},{"t":"南昌罗氏仰高楼 其二","f":"七言绝句","c":["隔浦飞来万仞青，仰高楼外玉为屏。","南昌千古西山并，别有东湖孺子亭。"]},{"t":"题溧阳两王先生归荣图 其一","f":"七言绝句","c":["壮岁青云雁序分，白头归里更情亲。","一门寿俊联双璧，海内于今见几人。"]},{"t":"题溧阳两王先生归荣图 其二","f":"七言绝句","c":["昼锦相辉入故园，连枝竞爽并高年。","从前心事清如水，晚得幽閒不愧天。"]},{"t":"题溧阳两王先生归荣图 其三","f":"七言绝句","c":["康乐才名我素交，惠连文苑旧同袍。","眼看逸翮联翩去，不尽中情怅望劳。"]},{"t":"过将台 其一","f":"七言绝句","c":["风云长护崇台下，昔日文皇此誓师。","至竟苍天辅真主，英雄捲地从龙旂。"]},{"t":"过将台 其二","f":"七言绝句","c":["指挥虎旅誓皇天，旧将犹能说往年。","龙去鼎湖云渺渺，遗臣过此重潸然。"]},{"t":"有怀子启行俭时彦时勉诸君子","f":"七言绝句","c":["霜满貂裘月满天，四更骑马白河边。","玉堂学士无公务，正拥青绫足晏眠。"]},{"t":"扈从巡边至宣府往还杂诗 其三","f":"七言绝句","c":["关柳行行叶乍稀，西风犹未振霜威。","圣情预悯随营士，敕下尚书尽赐衣。"]},{"t":"扈从巡边至宣府往还杂诗 其四","f":"七言绝句","c":["圣恩不已恤残躯，老拙深惭报效无。","屡酌金壶赐甘醴，还令中使护轻舆。"]},{"t":"扈从巡边至宣府往还杂诗 其五","f":"七言绝句","c":["边屯今岁盛丰登，仓庾家家积粟盈。","何幸王师此游豫，大车藁秸进行营。"]},{"t":"扈从巡边至宣府往还杂诗 其七","f":"七言绝句","c":["边阃当时任老臣，边头千里净无尘。","御营上谒多恩赉，天语还闻奖谕频。"]},{"t":"侍从海子飞放应制 其一","f":"七言绝句","c":["碧山翠海帝王州，凤盖霓旌护冕旒。","何幸升平无事日，衣冠祗从六龙游。"]},{"t":"侍从海子飞放应制 其二","f":"七言绝句","c":["帝德含弘在至仁，乾坤万物总皆春。","天池浩浩嬉鱼鸟，御苑跄跄集凤麟。"]},{"t":"侍从海子飞放应制 其三","f":"七言绝句","c":["灵沼融融冬不冰，如云凫雁与鹍鹏。","吾皇盛德惟蕃育，不重鹰雕搏击能。"]},{"t":"侍从海子飞放应制 其四","f":"七言绝句","c":["罝网临郊一面张，凌云排雾任飞翔。","古今田猎三驱乐，惟有殷汤与圣皇。"]},{"t":"侍从海子飞放应制 其五","f":"七言绝句","c":["玉座金舆俯绿漪，水光林影漾龙旂。","岂如汉武横汾乐，正似周文在沼时。"]},{"t":"题金文鼎清风楼卷 其一","f":"七言绝句","c":["白日红尘深复深，九衢车马骤骎骎。","小楼独坐清风里，如在湘川渭水浔。"]},{"t":"题金文鼎清风楼卷 其二","f":"七言绝句","c":["世上浮荣了不知，閒调绿绮理朱丝。","楼头只许徽之造，楼外从人歌竹枝。"]},{"t":"题金文鼎清风楼卷 其三","f":"七言绝句","c":["清风飒飒清云深，六月楼中暑不侵。","朝阳光辉下凤彩，暮雨髣髴闻龙吟。"]},{"t":"题金文鼎清风楼卷 其四","f":"七言绝句","c":["百年谁继赵松雪，近数毗陵王绂高。","忽复乘云去无迹，登楼怀忆使心劳。"]},{"t":"题金文鼎清风楼卷 其五","f":"七言绝句","c":["先生已别金陵去，归住吴淞近海滨。","淇澳潇湘随处有，清风明月共何人。"]},{"t":"题墨菊寄宗琏 其一","f":"七言绝句","c":["曾伴金城坊里住，邻园日日看花来。","高秋九月毗陵郡，潇洒何人共酒杯。"]},{"t":"题墨菊寄宗琏 其二","f":"七言绝句","c":["思诚斋里清如水，坐对幽花晚自香。","共有故园螺渚上，几时归去赏秋芳。"]},{"t":"索子俊中书画松","f":"七言绝句","c":["千岁徂徕古翠蟠，拂云含雾泻风湍。","毕宏韦偃君今是，烦写高堂五月寒。"]},{"t":"蓟州道中见菊花有怀子启时彦行俭时勉诸君子 其一","f":"七言绝句","c":["秋光渐近重阳节，缓辔垂鞭踏软沙。","却忆玉堂閒白画，谁家庭馆看黄花。"]},{"t":"蓟州道中见菊花有怀子启时彦行俭时勉诸君子 其二","f":"七言绝句","c":["想见联镳西出城，酒壶诗卷共高情。","看山骑马渔阳郭，也似平坡寺里行。"]},{"t":"滦河道中同杨太常宣夏二员外小酌柳下观鱼 其一","f":"七言绝句","c":["四人坐酌垂杨下，共爱清阴覆绿渠。","未尽一壶还上马，却将閒散羡游鱼。"]},{"t":"滦河道中同杨太常宣夏二员外小酌柳下观鱼 其二","f":"七言绝句","c":["云白山青护四围，水边杨柳翠如帏。","人间无处无幽境，何补明时独未归。"]},{"t":"题梅赠以穰","f":"七言绝句","c":["携手河梁欲别难，故乡南去路漫漫。","一枝林下清如玉，但保风霜到岁寒。"]},{"t":"遇山居老有感 其一","f":"七言绝句","c":["细柳鲜桃潋滟春，白云流水净无尘。","看渠鹤发林居者，只傍青山老此身。"]},{"t":"遇山居老有感 其二","f":"七言绝句","c":["著处溪山可置身，古人求志不求闻。","从前未有匡时术，只合携家傍白云。"]},{"t":"梦亡妻 其一","f":"七言绝句","c":["孟光憔悴病来容，昨夜苍茫梦里逢。","还似往年临别日，匆匆劳苦为纫缝。"]},{"t":"梦亡妻 其二","f":"七言绝句","c":["经时未遂葬山丘，贤行终身恸不休。","勤俭成家长儿女，一生辛苦为黔娄。"]},{"t":"送彝训兼问讯子勤 其一","f":"七言绝句","c":["銮坡凤沼接清班，忆昔同朝侍圣颜。","此日相逢又相送，伤心回首见桥山。"]},{"t":"送彝训兼问讯子勤 其二","f":"七言绝句","c":["之官渺渺江南去，便道还家著锦衣。","万里谁无桑梓意，同乡惆怅未同归。"]},{"t":"送彝训兼问讯子勤 其三","f":"七言绝句","c":["故人为郡端溪上，前月书来叹索居。","同是贞元旧供奉，因君更问近何如。"]},{"t":"题菊送别","f":"七言绝句","c":["送行渐及黄花节，江北江南白露寒。","为有清香宜晚岁，独怜彭泽未休官。"]},{"t":"唐马为士启题 其一","f":"七言绝句","c":["玉花骢马大宛来，俶傥权奇见异材。","不道开元四十万，驽骀安得望龙媒。"]},{"t":"唐马为士启题 其二","f":"七言绝句","c":["雄姿逸气真龙种，赤雾团身白玉蹄。","自是西来第一匹，东风萧散不闻嘶。"]},{"t":"鬼谷圮桥东山云房四图为金学士题 其一","f":"七言绝句","c":["靡靡王风叹黍离，周公已远仲尼衰。","乘车拥盖诸侯客，只说阳城鬼谷师。"]},{"t":"鬼谷圮桥东山云房四图为金学士题 其二","f":"七言绝句","c":["神遇圮桥岂偶然，君臣契合亦千年。","不逢龙准真明主，三杰何人解识贤。"]},{"t":"鬼谷圮桥东山云房四图为金学士题 其三","f":"七言绝句","c":["莫道征西旧司马，平生山水惬幽寻。","白头匡济成何事，回首东山感慨深。"]},{"t":"鬼谷圮桥东山云房四图为金学士题 其四","f":"七言绝句","c":["云白山青琪树绿，神仙咫尺隔尘凡。","九还真诀逢师授，自此流传到吕岩。"]},{"t":"杨学士以海棠双鹊图赠其弟归求题 其一","f":"七言绝句","c":["杨家庭馆风光好，花萼连枝锦不如。","况是和鸣双翠羽，相亲相乐似雍渠。"]},{"t":"杨学士以海棠双鹊图赠其弟归求题 其二","f":"七言绝句","c":["万里京华临别日，海棠花发欲春深。","遥知晴鹊先将喜，啼满龙津碧树林。"]},{"t":"张缉熙监丞挽诗 其一","f":"七言绝句","c":["二十年前同史馆，北京邂逅更情亲。","伤心此日贤关外，相向西风哭故人。"]},{"t":"张缉熙监丞挽诗 其二","f":"七言绝句","c":["八品儒官坐辟雍，白头心事古人同。","至今鼓箧桥门者，洒泪相思说至公。"]},{"t":"张缉熙监丞挽诗 其三","f":"七言绝句","c":["两京学省聚贤英，试问何人不负丞。","官舍一毡清似水，后来相继属谁能。"]},{"t":"张缉熙监丞挽诗 其四","f":"七言绝句","c":["死去悲吟满缙绅，共嗟直道不忧贫。","不知驷马高车客，身后如公有几人。"]},{"t":"王孟安笔花轩 其一","f":"七言绝句","c":["丝纶阁下染龙香，幸得蒙恩侍玉皇。","元自笔花轩里进，常时亲洒出天章。"]},{"t":"王孟安笔花轩 其二","f":"七言绝句","c":["清世高才与博闻，轩中来访日纷纷。","文章谁合传千载，三秀灵芝五色云。"]},{"t":"王孟安笔花轩 其三","f":"七言绝句","c":["当代中书海内传，尚论勋业不论钱。","赠公凭写天人策，肯逐扬雄浪草玄。"]},{"t":"王御史竹索题","f":"七言绝句","c":["千尺云霄翥翠鸾，画图犹似倚窗看。","台中别有凌霜柏，与尔青青共岁寒。"]},{"t":"题马 其一","f":"七言绝句","c":["满身云影湿津津，何用能空冀北群。","踣铁犹矜千里足，连钱时动五花文。"]},{"t":"题马 其二","f":"七言绝句","c":["曾随六御历沙场，初解钩膺白玉镶。","只合清时谢羁束，春风散诞华山阳。"]},{"t":"钱舜举松溪待渡图为姜司谏题 其一","f":"七言绝句","c":["翠黛连山绿涨堤，扁舟长倚岸东西。","人家知是吴兴往，还傍苕溪傍霅溪。"]},{"t":"钱舜举松溪待渡图为姜司谏题 其二","f":"七言绝句","c":["槿篱茅舍水村幽，林彩山光积翠浮。","空使行人愁望渴，隔溪閒却木兰舟。"]},{"t":"五月八日史馆困睡梦侍献陵顾问边事觉而感赋","f":"七言绝句","c":["阴山瀚海已澄清，犹似当年轸圣情。","万事伤心同梦过，白头清泪不胜零。"]},{"t":"文渊阁前芍药盛开对酒偶成","f":"七言绝句","c":["东风又放玉堂春，丽色清香满意新。","有酒相欢莫虚负，今年顿减去年人。"]},{"t":"黄母王夫人挽诗 其一","f":"七言绝句","c":["珠翟云冠五福身，綵衣看舞瑞麒麟。","乘鸾一去知何处，女范长留教后人。"]},{"t":"黄母王夫人挽诗 其二","f":"七言绝句","c":["口训诗书手辟纑，月涵沧海出明珠。","夜中环佩归来些，啼杀堂前返哺乌。"]},{"t":"杨河竹枝 其一","f":"七言绝句","c":["屯堡人家住不多，屯边屈曲是杨河。","褰裳濡足不计数，河上行人愁奈何。"]},{"t":"杨河竹枝 其二","f":"七言绝句","c":["客子离家半月程，风沙引起忆家情。","河中鲤鱼不得觅，尺素何由寄北京。"]},{"t":"挽彭叙古 其一","f":"七言绝句","c":["年过二十工书法，往往挥毫逼古人。","身被君恩无一岁，可怜埋玉楚江滨。"]},{"t":"挽彭叙古 其二","f":"七言绝句","c":["死别才知见面难，旅坟荒草暮云寒。","几回东角楼前过，拾得遗书不忍看。"]},{"t":"甲寅初度感怀 其一","f":"七言绝句","c":["翰苑春坊清切地，从来未有效涓埃。","天朝三十三年禄，虚负君恩养不才。"]},{"t":"甲寅初度感怀 其二","f":"七言绝句","c":["先茔夜夜梦家山，身系君恩未遣还。","祭厚不如生养薄，奠杯秪益涕汍澜。"]},{"t":"回銮","f":"七言绝句","c":["万乘回銮指玉京，行营笳鼓杂歌声。","山灵亦有欢愉意，数点瑶华送羽旌。"]},{"t":"题倪元镇画","f":"七言绝句","c":["琴床书几一尘无，散发云林不受呼。","清閟阁中宾客尽，时因遗墨见倪迂。"]},{"t":"居庸道中竹枝 其一","f":"七言绝句","c":["牵车驰马夜无停，不辨容颜只辨声。","非是长歌即长叹，一般行路两般情。"]},{"t":"居庸道中竹枝 其二","f":"七言绝句","c":["千车万骑度关山，独坐肩舆帖帖安。","传与家人莫相忆，不曾辛苦不曾寒。"]},{"t":"次韵弘济过居庸佛院怀幼孜 其一","f":"七言绝句","c":["又随翠辇度居庸，不复当年语笑同。","下马还寻旧游处，伤心寒树起秋风。"]},{"t":"次韵弘济过居庸佛院怀幼孜 其二","f":"七言绝句","c":["并登仙阁愧才庸，三十年间进秩同。","何日南帆溯潇峡，冢前持酒酹西风。"]},{"t":"时思堂 其一","f":"七言绝句","c":["树有深根水有源，音容梦寐记生存。","堂中日日蘋蘩荐，不称从来罔极恩。"]},{"t":"时思堂 其二","f":"七言绝句","c":["春雨秋霜系所思，伤心舞綵竟无期。","后来六簋陈祠祭，得似承欢菽水时。"]},{"t":"送尤安礼 其一","f":"古风","c":["君子之马，六辔如丝。","言念君子，如璋如圭。","其德不爽，敬慎威仪。"]},{"t":"送尤安礼 其二","f":"古风","c":["君子之马，六辔沃若。","言念君子，如金如锡。","其德不回，威仪抑抑。"]},{"t":"送尤安礼 其三","f":"古风","c":["岂无他人，不如友生。","邂逅相遇，德音不忘。","惠而好我，示我周行。"]},{"t":"送尤安礼 其四","f":"古风","c":["言笑晏晏，维予与女。","女转弃予，谁与独处。","中心养养，往送于野。"]},{"t":"送尤安礼 其五","f":"古风","c":["与子成说，方何为期。","既曰归止，曷云能来。","子宁不来，悠悠我思。"]},{"t":"卧病集杜答黎信十首 其一","f":"七言古诗","c":["隔户杨柳弱袅袅，孰知茅斋绝低小。","人生留滞生理难，强移栖息一枝安。","朋知来问腼我颜，安得广厦千万间。","青春欲尽急还乡，身欲奋飞病在床。","荆扬春冬异风土，终日戚戚思羁旅。","形神寂寞甘辛苦，世人那得知其故。","自断此生休问天，浊醪粗饭任吾年。","将诗不必万人传。","小儿学问止论语，恰有三百青铜钱。"]},{"t":"卧病集杜答黎信十首 其二","f":"七言古诗","c":["天时人事只相催，怀抱何时独好开。","气酣日落西风来，口虽吟咏心中哀。","亦知穷愁安在哉，生前相遇且衔杯。","江上人家桃树枝，千朵万朵压枝低。","风妒红花却倒吹。","人生几何春已夏，应须旨酒送生涯。"]},{"t":"卧病集杜答黎信十首 其三","f":"七言古诗","c":["今日苦短昨日休，万壑东逝无停留。","江花未尽会江楼，长歌短咏还相酬。","请公一来消我愁。"]},{"t":"卧病集杜答黎信十首 其四","f":"七言古诗","c":["此乡之人气量窄，我独觉子神充实。","十日不一见颜色，时复看云泪沾臆。","感时抚事增惋伤，人生会合不可常。","草閤柴扉星散居，不道故人无素书。","素书一月凡一束，纸长要自三过读。","故人相见未从容，令我心中苦不足。","寒雨飒飒枯树湿，欲往城南忘南北。","感君意气无所惜，昔者相过今不得。","此心烱烱君应识。"]},{"t":"卧病集杜答黎信十首 其五","f":"七言古诗","c":["乡里衣冠不乏贤，煎胶续弦奇自见。","前者途中一相见，去马来牛不复辨。","令渠述作与同游，宿昔一逢无此流。"]},{"t":"感遇答夏四秀才三首 其一","f":"五言律诗","c":["摇曳双彩凤，欲集无珍木。","昨下阆风岑，飘扬竟何托。","梧桐巢燕雀，反栖恶木根。","人生难称意，雄豪安足论。"]},{"t":"感遇答夏四秀才三首 其二","f":"五言律诗","c":["绿帻谁家子，灼灼芙蓉姿。","银鞍照白马，玉壶系青丝。","行行未能已，冶游方及时。","我志在删述，但为此辈嗤。"]},{"t":"感遇答夏四秀才三首 其三","f":"五言律诗","c":["去去复去去，天地一逆旅。","石火无留光，良辰竟何许。","取酒会四邻，行乐须及春。","黄金高北斗，浮荣何足珍。"]},{"t":"驺虞诗","f":"古风","c":["维天至仁，涵育万类。","维我皇明，一德作配。","穆穆太祖，奄有八埏。","仁覆其人，大哉如天。","皇帝仁圣，同符太祖。","天命人归，缉熙九五。","皇帝曰祗，予临兆民。","上天皇考，予承维仁。","乃诏多方，乃循旧章。","乃求遗逸，乃登俊良。","德教宣明，霈泽覃敷。","靡彊不驯，靡弱不扶。","濡槁涤污，起废疏堙。","天叙秩秩，人文彬彬。","□□□□，小大熙熙。","夏葛冬裘，不知渴饥。","声教渐被，孰有内外。","迩悦远来，极地所载。","雕题漆齿，椎结辫发。","梯航重译，俯伏北阙。","至和孚洽，恊于天人。","无远弗庭，百祥萃臻。","嘉禾瑞麦，甘露芝草。","白雉黄犀，皇不为宝。","维钧有山，在彼周疆。","乃产异兽，皓质缁章。","酋耳脩尾，身虎而驯。","食不生物，性麟之仁。","维周亲王，往钧于田。","迫之弗惊，扰之以还。","曰斯驺虞，皇仁之符。","不远千里，献于皇都。","王拜稽首，皇帝仁圣。","维仁动天，灵祥恊应。","帝曰匪予，予弟仁孝。","发祥周邦，维王之召。","王曰匪臣，万邦帝治。","帝德致祥，臣敢冒之。","群臣百工，观视嗟叹。","自昔有闻，于今实见。","欢欣拜舞，帝仁所来。","帝曰予仁，曾曷下施。","予怀忠贤，为国之祯。","菽粟布帛，民资以生。","时无不获，予治斯德。","嘉祥异物，岂予攸亟。","群臣拜手，皇帝圣德。","大禹不伐，商宗恭默。","皇心一揆，皇寿万岁。","维天降祥，如川方至。","臣职载记，获睹休异。","敬陈歌诗，永告来世。"]},{"t":"圣孝瑞应诗","f":"古风","c":["惟皇御极，八纮率俾。","曰孝曰仁，爰教爰理。","惟皇考妣，著存无间。","岂曰羹墙，斯须有见。","洋洋圣灵，陟降在天。","遑遑孝思，皇心有虔。","乃循玄范，乃脩金录。","爰伸终慕，暨惠普率。","惟皇渊衷，斋庄纯一。","对越有严，有恪有翼。","上帝有言，忱孝予子。","百神有言，笃恭于主。","至诚感孚，祯应骈臻。","缟鹤傞傞，青鸾䎙䎙。","下上坛壝，周旋庑序。","徘徊翱翔，如掖神驭。","煜煜宝盖，绛节黄麾。","流越端门，如神往来。","复有神人，有言有告。","出入倏忽，邈不可究。","复有卿云，五章烂垂。","轮囷葳蕤，琪叶金支。","粲粲天乳，湑湑甘露。","既零道苑，亦降陵树。","厌浥琼脂，淋漓玉津。","以荐以餐，统和天人。","讫事秉虔，如盥未荐。","绳绳休徵，叠出层见。","有深规甃，有泉潗潗。","苾芬充达，沾者酡颊。","穹祇发祥，式昭孝诚。","群臣拜手，皇德之徵。","皇曰匪予，天地考妣。","降鉴畀祐，锡时蕃祉。","自昔明圣，膺祥务敬。","汝予恊恭，庶臻永庆。","群臣拜手，惟皇圣明。","皇不自圣，臣敢怠宁。","有臣士奇，纪载是职。","敬陈歌诗，永播无极。"]},{"t":"瑞星诗","f":"古风","c":["惟天之高，荡荡难名。","仁覆万类，大德曰生。","惟君宪天，行天之道。","仁育群生，下民是保。","天监君德，有允肖之。","来享来歆，为祥为祺。","皇钦天命，嗣临大宝。","严孝宗庙，祗奉圣母。","夙夜恭勤，惟德之霈。","始于家邦，弘及四海。","饥者食之，寒者衣之。","槁者濡之，仆者植之。","如艺黍稷，薅莠与稂。","驱去螟螣，罔俾害伤。","矜恻鳏孤，抚字无告。","有昧弗率，勉勉教诏。","除其凛冽，敷之融和。","化戚以愉，易啸以歌。","立纲布纪，惟贤之庸。","推亡固存，履道大公。","乃脩德化，制礼作乐。","天叙有常，人文焕若。","芒芒四裔，雨露所坠。","慕义归诚，靡或弗至。","上帝曰俞，允光予命。","何以报锡，式鸿厥庆。","嘉禾异麦，骈出于下。","骈出于上，庆云膏露。","宣德庚戌，月维己丑。","其日丁亥，夕瑞在酉。","大星如丸，九斿之傍。","有彗若射，金玉其煌。","素蟾东生，皎乎相辉。","河汉为蒙，参井为微。","厥名含誉，太史敷奏。","百辟嵩呼，贺祥献寿。","皇德仁圣，谦让是崇。","归功穹祇，归功祖宗。","归功圣母，亦及臣子。","申命饬励，敬哉无怠。","稽古大圣，轩辕唐虞。","咸有瑞星，昭德之符。","皇德格天，前圣一致。","肆用作诗，永告来世。"]},{"t":"仁安堂诗为任敬立赋八章","f":"古风","c":["奕奕高堂，丽于城隅。","有植其?，有列其书。","高堂奕奕，既闲且殖。","展矣君子，秉心之德。","其心伊何，相人予均。","其德伊何，侯利安于民。","民之颠沛，维予之殆。","民之憯憯，维予之瘁。","民之瘁矣，予胡宁居。","言遄赴之，弗步而趋。","民乃定矣，予心则夷。","维予心之夷，曷报曷施。","帝怀康靖，弗懈夙夜。","孰遏其升，不显在下。","南有松柏，以柱以楹。","聿观尔升，诞惠厥宁。"]},{"t":"蒋氏三径诗九章","f":"古风","c":["瞻彼三径，于湖之侧。","鹤岭在南，凤冈在北。","瞻彼三径，于湖之干。","有植桓桓，有蔽栾栾。","维此幽人，辟之治之。","维此幽人，宅之宜之。","不亢而迕，不伛而妩。","中心儢儢，爰来爰处。","爰率我先祖。","维我先祖，予恒游息。","既宽既硕，予是仪是式。","厥有旨酒，亦有肥牲。","时洽我邻，及我良朋。","式优以游，式燕以休。","曷竞曷柔，曷畀曷求。","相此幽人，胡乐陶陶。","相彼贪人，亦孔之劳。","有图有文，既昭且宣。","暨予作诗，申告弗谖。"]},{"t":"东川迎养图诗十章","f":"古风","c":["东川之漘，栾栾柏松。","君子于行，其乐融融。","栾栾柏松，东川之漘。","君子于行，其从彬彬。","首之皤皤，仪之䄡䄡。","君子有父，聿来自南。","峨峨翟冠，兰充其祎。","君子有母，自南偕来。","君子拜稽，言笑嘻嘻。","父母圣仁，不我遐遗。","维父与母，眉寿而康。","维兄与弟，左右扶将。","行其野矣，有桑有麻。","入其邑矣，有弦有歌。","奕奕高堂，式燕以嬉。","匪直孝恭，其施孔宜。","凡厥庶民，各有所生。","孰时观之，弗感而兴。","懿是孝德，有肇有循。","肆庸作歌，以告厥民。"]},{"t":"听乌轩诗为刘宗韶作","f":"古风","c":["民物之生，厥赋惟均。","气禀既殊，灵秀维人。","其生之初，父子之慈。","民物斯同，靡或有亏。","林栖者乌，性纯且仁。","反哺维勤，其参其鶱。","维父维母，生我鞠我。","父母孔劳，我心曷舍。","雨露既濡，履之则悲。","哀我父母，我宁以时。","乌鸣且和，养适其私。","静言听之，我心何如。","天之高矣，日之远矣。","哀哀父母，我心曷已。","立身扬名，维孝之大。","勖尔君子，敬励于志。"]},{"t":"后山诗为江西林宪副作","f":"古风","c":["崔崔后山，清漳之漘。","下蟠厚坤，上摩穹旻。","山有嘉植，维松维柏。","亦有令人，维英维特。","维子润甫，恺悌君子。","奕奕高堂，在山之趾。","道积于躬，静与山处。","及时奋庸，怀山曷已。","山则升云，兴雨祁祁。","有道于施，君子之宜。","大江之西，维国南服。","政纪之明，不严以肃。","肃如秋霜，示民之威。","熙如春阳，维民之怀。","维山之崇，不迁厥常。","维君子誉，式永其彰。"]},{"t":"题辉侄兰","f":"古风","c":["幽澹其芳，介于贞石。","何彼鸾凤，而栖枳棘。","言念君子，可以观德。"]},{"t":"题升龙","f":"古风","c":["阳德中正，与时偕行。","乾元九五，天下文明。"]},{"t":"题降龙","f":"古风","c":["云行雨施，万物咸春。","收敛神用，渊潜自珍。"]},{"t":"承训堂诗","f":"古风","c":["奕奕高堂，有父有母。","父母孔慈，锡我教诱。","其教伊何，曰义与仁。","于爱之真，于言之谆。","敬恭听之，允率履之。","父母孔仁，而敢怠违。","父母犹天，敬事朝夕。","我行或怠，贻我父戚。","孝哉旸也，永钦尔终。","尔德式嗣，福禄来崇。"]},{"t":"具庆堂诗","f":"古风","c":["郁郁乔林，发厚于本。","源厚且深，其流斯远。","维邢井宗，世服善仁。","迨大父父，厥脩益勤。","父也在廷，祗帝任使。","帝锡宠加，简升其子。","子尚贵主，联姻天潢。","玉鞶麟衣，貂蝉煌煌。","乃作高堂，奉父与母。","致隆爱敬，日献春酒。","春酒在尊，鼎荐芬芳。","父母眉寿，允乐且康。","允乐且康，孝心孔宁。","立身事君，维孝之经。","士奇作诗，用谂都尉。","具庆百龄，令闻长世。"]},{"t":"永思堂诗","f":"楚辞体","c":["南山之木，厥有本根。","浩浩川流，则亦有原。","凡世之氓，孰无父母。","生我育我，忧勤是保。","我疾在躬，父母怦怦。","我躬既平，父母载宁。","我事父母，千载未足。","云胡一朝，去我不复。","林栖者乌，则有反哺。","哀哉小子，欲养无所。","岂无厚禄，岂无华缨。","我无父母，于谁为荣。","靡旦靡夕，孔怀弗忘。","父兮母兮，如睹羹墙。","居则以思，行则以思。","音容慌焉，梦寐对之。","父天母地，覆载同德。","哀哀我心，何穷何极。","先哲有训，立身忠君。","我惇用之，敢怠于勤。","无敢怠勤，恒恭敬止。","终焉永怀，悠悠曷已。"]},{"t":"题张子俊山水","f":"古风","c":["高山崔崔，青川浏浏。","息有幽居，济有轻舟。","已远人境，同志来求。","优哉游哉，足以忘忧。"]},{"t":"题陈宪虎","f":"古风","c":["虨虨其文，眈眈其视。","岂不虓怒，父子仁在。"]},{"t":"题陈宪龙","f":"古风","c":["云行雨施，阳德之亨。","丰穰以成，天下以平。"]},{"t":"荣寿堂诗","f":"古风","c":["奕奕高堂，奉父与母。","父母善仁，天锡多祜。","厥祜伊何，耆耄皆臻。","和乐且康，皓首赪颜。","云章自天，式显贲之。","命服煌煌，封秩貤之。","孰无父母，偕老几何。","云谁之居，被时宠嘉。","福禄鼎来，其奚自致。","嗣有君子，熙帝之载。","桓桓君子，奠此南服。","民恃方伯，朝倚岳牧。","维敬维仁，以共帝命。","维孝维忠，以乐具庆。"]},{"t":"题白云山房图","f":"古风","c":["高山在上，清流在下。","懿彼幽人，托此适处。","英英者云，菀菀者林。","懿彼幽人，其潜之深。","有舟有梁，莫或以之。","嗟此幽人，优哉游哉。","翩翩飞翼，夕倦斯还。","逝予从之，以终岁年。"]},{"t":"题泉坡学士龙","f":"古风","c":["时而渊潜，时而云升。","乾元九五，天下文明。"]},{"t":"题水仙","f":"古风","c":["汉广之滨，清洛之汭。","留此娟好，邂逅谁遗。"]},{"t":"题菊","f":"古风","c":["秋霜既肃，黄花始妍。","爰掇爰餐，聊可永年。"]},{"t":"题谖草","f":"古风","c":["对此谖草，粲乎有章。","我自陶陶，何忧何忘。"]},{"t":"题玉簪","f":"古风","c":["姑射之姝，翠旌如帏。","惟显簪玉，不睹容辉。"]},{"t":"题兰","f":"古风","c":["懿此芳兰，在彼岩阿。","为佩为带，怀哉九歌。"]},{"t":"题鹡鸰图","f":"古风","c":["人之亲爱，至性所有。","维兄与弟，如足如手。","兄弟急难，我心则疚。","兴言赴之，匍匐敢后。","沿江历湖，自南而北。","遥遥万里，敢遑暇息。","亦既晤觏，季也其羸。","沦坠泥涂，伯也伤悲。","矢辞吁天，天听高高。","伯也怦怦，中心孔劳。","昔我始来，青阳肇序。","日月云迈，岁聿斯暮。","念桑与梓，我行将归。","顾视予季，予宁不怀。","顾谓予季，予岂汝违。","予行复来，春以为期。","鹡鸰之诗，在昔有作。","兄弟急难，视古何怍。"]},{"t":"蒋隐溪挽辞 其一","f":"楚辞体","c":["顾瞻兮堂前，卷帷幕兮藉兰荃。","陈清醑兮载肥鲜，韵悲管兮切哀弦。","凄风激兮棂轩，云黯黪兮灵来旋。","恍如睹于形色兮俨若聆夫笑与言，言可聆兮意不传，怅思公兮临几筵。"]},{"t":"蒋隐溪挽辞 其二","f":"楚辞体","c":["北风凛凛兮天雨霜，木叶脱落兮百草黄。","翩铭旌兮辞高堂，岂灵车兮秀冲冈。","蒿里歌兮哀以伤，玄室一閟兮夜甚长。","魂渺渺兮何方，螺山崔崔兮螺川汤汤。","青原与白鹭兮郁相望，怅思公兮游故乡。"]},{"t":"蒋隐溪挽辞 其三","f":"楚辞体","c":["玉佩兮琼琚，霓衣兮霞裾。","秉元化兮握灵枢，列缺从兮丰隆趋。","倏阴而阳兮忽卷而舒，睨视浊世兮如污渠。","飘然乘风兮凌太虚，参王乔与韩终兮列仙为徒。","游紫微兮帝之都，怅思公兮邈天衢。"]},{"t":"题岁寒三友图","f":"楚辞体","c":["松苍苍兮虬枝，竹翛翛兮凤羽。","梅皎皎兮琼芳，凛寒节兮偕处。","芬芳菲兮春晖，倏零落兮秋露。","惟所禀之贞洁，阅岁年于迟暮。","含匏笙兮云中，和清角兮月下。","谅同志兮金石，渺予怀兮延伫。"]},{"t":"盘谷草堂 其一","f":"楚辞体","c":["盘之中兮崇丘，交青葱兮松柏。","怀先祖兮永逝，托吉壤兮玄宅。","跽酌兮寒泉，荐兰秀兮芳菊。","春雨零兮秋露，耿孝思兮无斁。"]},{"t":"盘谷草堂 其二","f":"楚辞体","c":["盘之中兮幽居，聊逍遥兮栖迟。","朝采兮林芳，夕揽兮岩芝。","仁与义兮是明怀，孔颜兮吾师。","安吾分兮蹇劣，何富贵兮可期。"]},{"t":"盘谷草堂 其三","f":"楚辞体","c":["盘之中兮良畴，下宜稻禾兮高宜来牟。","春出耕兮夏耨，旦勤斯兮夕休。","或雨旸兮匪时，何仓庾兮有秋。","怀古人兮食力，吾弗力兮谁尤。"]},{"t":"送别辞","f":"楚辞体","c":["留石瑱兮洞庭，遗兰佩兮澧浦。","羌不怀兮别离，独徘徊兮延伫。"]},{"t":"题林静小景","f":"五言古诗","c":["幽居无俗韵，山人有馀清。","鸣湍泻晴壑，高秋啭早莺。","相携一散躅，亦得畅其情。"]},{"t":"题朱四智梦草轩","f":"五言古诗","c":["骨肉皆钟爱，兄弟重连枝。","生为同一气，殁为永别离。","谁言永别离，夜夜梦见之。","梦见何所为，和乐如故时。","忽觉各分散，泣下横交颐。","中堂理单篪，声悲不能谐。","绵绵而弗忘，中自长相思。","谢子笃天伦，梦感著声诗。","因之名我轩，恒用著所怀。"]},{"t":"听艾仲宣弹琴","f":"五言律诗","c":["公子散烦襟，留客抚清琴。","一弹黄鹄操，再鼓阳春吟。","洋洋发冲响，泠泠谐素心。","非今同胜会，谁闻奏雅音。"]},{"t":"赠沈教谕奔丧归闽","f":"五言古诗","c":["禄养欣有遂，何言奄弃兹。","哀哉风树怀，百折不自持。","列帷辍弦诵，岂但蓼莪诗。","晨起饯旋归，烟波满川泜。","徘徊一顾望，忧人益增悲。","谅感天地恩，宁为悲别离。","须臾为千里，缅焉安可期。","唯应问业者，恻恻此江湄。"]},{"t":"题邓秀才寒翠轩","f":"五言律诗","c":["清轩大江畔，前有竹松林。","萧条霜雪时，爱此碧森森。","窗中看掩映，席上对阴沉。","非将玩适重，岁暮可论心。"]},{"t":"题太乙真人莲叶舟图","f":"五言古诗","c":["至人乘汗漫，遗世若虚游。","不假桂为楫，飘飖一叶浮。","仰观天宇澄，俯视洪波流。","茫茫荡无垠，泛泛任去留。","富贵多忧虞，仙道我所求。","弱流倘共济，从之览十洲。"]},{"t":"寿吴孟勤先生 其一","f":"五言古诗","c":["大明有硕士，乃在国南乡。","被服夫容衣，皋兰袭芬芳。","雄辞由令德，粲粲发奎章。","名声布远迩，延颈谁不望。","昔者螺水湄，今来鹄山阳。","高筵酌甘醴，欢乐诚未央。"]},{"t":"寿吴孟勤先生 其二","f":"五言古诗","c":["峨峨黄鹄山，直上凌五城。","仙人驾彩虹，飘飖临我庭。","借问此谁欤，陵阳与容成。","玉杯注丹焰，磬折奉长生。","达人含至道，自与元化并。","遨游紫庭中，逍遥龟鹤龄。"]},{"t":"缪都指挥挽诗","f":"五言古诗","c":["龙飞肇淮土，维公奋云从。","挥戈逐代北，跃马趋山东。","峥嵘摧劲敌，意气当前锋。","百战有爵位，屡迁乃益崇。","洞庭与彭蠡，先后填巨邦。","百岁焉足多，一朝上埃风。","灵车发华屋，祖送出崇墉。","萧萧众马悲，凄风激大江。","去去虽已矣，垂誉恒无穷。"]},{"t":"送贝惟学还会稽得此字","f":"五言古诗","c":["高堂双舞衣，日奉慈颜喜。","先垄别经时，何堪恋桑梓。","杳杳浙江濆，依依汉川涘。","怀往忻已遂，伤离方未弭。","即路有忧欢，去年俱若此。"]},{"t":"奉寄李丈人","f":"五言古诗","c":["晨登黄鹄岭，引望陵阳岑。","陵阳渺天末，何由见所钦。","自昔携手时，萧散大江浔。","出言谐鼓瑟，中孚利断金。","一朝分袂来，寒暑三四侵。","翰飞薄远霄，鳞泳循清潭。","高深旷不接，隔我浮与沉。","堂中侍愉色，膝下俨缨簪。","禄养崇甘肥，欢乐日骎骎。","久要焉独忘，一往无遗音。","尚希保眉寿，以慰饥渴心。"]},{"t":"题三泖归耕卷赠管时勉归吴松","f":"五言古诗","c":["客从云间来，自言家远村。","用世阙材具，委身服田园。","开春起东作，良苗日愈蕃。","下无螟螣苦，上有霖雨恩。","年和易坚好，为力诚不烦。","当秋负穫归，如坻积我门。","公家且轻税，岂复忧饱温。","贤妇持机杼，稚子牧鸡豚。","傍舍数老翁，欢会无晨昏。","其人虽朴野，皆有忠厚言。","相与墟曲间，焉知市朝喧。","违此未几时，九扈鸣已繁。","去去情益敦，浮荣终不论。"]},{"t":"题艾仲宣兰","f":"五言古诗","c":["昔年春月夜，弭棹湘川湄。","邂逅鼓瑟人，佩纕纷陆离。","宁知忽不见，芳馨贻在斯。"]},{"t":"题艾仲宣菊","f":"五言古诗","c":["高堂二月中，粲粲罗芳树。","日夕凉飙来，纷然已如雨。","君看篱下姿，可用怡迟暮。"]},{"t":"题伯牙鼓琴图","f":"五言古诗","c":["平生山水意，托此孤桐丝。","之子无旋期，茫茫谁复知。","閒来幽树下，欲奏已迟迟。"]},{"t":"题彭宪佥白海青图","f":"五言古诗","c":["由来搏击威，云鸿不敢即。","伫睇极青冥，群飞皆戢翼。","柏府坐看时，重有秋霜色。"]},{"t":"赠陆伯阳 其一","f":"五言律诗","c":["粲粲白玉琚，本生昆山阳。","一朝蒙采择，高列珩与璜。","佩服合其仪，和鸣日锵锵。","珷玞昔同椟，頫仰方自量。"]},{"t":"赠陆伯阳 其二","f":"五言律诗","c":["妖媚园中花，岂不当春荣。","孤高陵上柏，严霜厉坚贞。","匠氏来相求，藻绘升栋楹。","固知君子人，特立以成名。"]},{"t":"赠陆伯阳 其三","f":"五言律诗","c":["南岳有威凤，竹梧得其依。","五章备文采，鸣声合金徽。","圣皇莅九五，四海扬德辉。","翙翙初来仪，雍雍复旋归。"]},{"t":"题萧德通所藏崔白鹅","f":"五言律诗","c":["众鸿厉高鶱，逍遥薄天汉。","讵无肃肃羽，而独怀波澜。","特立谅不群，振鸣终伴奂。","名书亦奚为，懿此焉足换。"]},{"t":"赋丘原芳林隐","f":"五言古诗","c":["达士布高位，幽人在中林。","贵贱有定命，聊用得吾心。","方宅五亩馀，灌木郁萧森。","浮阳映密叶，清云散庭阴。","回风激兰薄，馀芳袭我襟。","虽无丝竹清，嘤鸣怀好音。","残帙不停披，旨酒恒独斟。","独斟忽复醉，时时吐高吟。","幸无异患侵，自适非陆沉。","知分理攸宜，谁谓倦华簪。"]},{"t":"萧安正赠白纻赋诗为报","f":"五言古诗","c":["朱明变寒节，曜灵赫南驰。","端居念初服，感激悲慈帏。","春晖奄遒尽，谁为游子衣。","岂不荷重纩，后时非所宜。","君子见存恤，缟纻贻赠之。","素质飏白雪，纤理瑩文漪。","裁缝被弱体，济济生光仪。","逝将表明惠，永歌无斁诗。"]},{"t":"解筠涧先生挽诗","f":"五言古诗","c":["东山千馀仞，其下文水驰。","驰水去不还，高山黯无辉。","夫子在世时，芳名扬四陲。","夙志骛姬孔，肆力究皇羲。","窅窅万化原，玄悟探其微。","秋荷袭裳衣，春兰充佩袆。","发轫蹈佳轨，周旋岂踰规。","道存希有济，才高未见施。","旷视六合中，时时写雄词。","奋如蛟龙跃，烨然云章垂。","济南讲遗经，河汾论匡时。","翘翘问业者，诜诜日来归。","居常以乐天，逍遥介期颐。","一朝随埃风，飘然远去兹。","奄忽历星霜，今来四五期。","嗟余忝乡郡，夙昔仰蓍龟。","引睇鉴湖阡，徒怀后时思。","頫仰杳茫茫，中伤公讵知。"]},{"t":"送黎信归故乡","f":"五言古诗","c":["商飙起西陆，倏忽为素秋。","客行惜迟暮，怀归逝不留。","舟楫晨已具，送子河之洲。","千里远结交，三载笃绸缪。","欢洽谐琴瑟，夙昔同衾裯。","云何当乖分，私情怅悠悠。","山川绕归路，岂不思同游。","俯观江汉水，滔滔俱东流。","惜哉南飞鸿，孤鸣违匹俦。","别离诚难任，斯须亦何忧。","终当返旧林，岁暮共优游。"]},{"t":"夜宿山家待宋惟宪不至","f":"五言律诗","c":["主人罢尊酌，稚子具衾毡。","稍稍松火息，寥寥独未眠。","林高风响迅，窗虚月色悬。","行侣时相失，怀抱自悽然。"]},{"t":"寄题王氏槐阴轩","f":"五言古诗","c":["结宇临长衢，开轩面嘉树。","灵根沃鲜泽，由来深且固。","柯叶浮青冥，垂云羃囱户。","纷华避春节，孤芳弄秋素。","王生屏世营，端居多暇豫。","潜玩圣贤言，常怀往古务。","荫止谐夙心，还因动遐慕。","仰惟先人德，封培昔已屡。","敬承乃汲汲，时存荒逸惧。","穷达知有命，非缘高爵故。","因歌寄幽轩，为子写中愫。"]},{"t":"送王经历奔丧还偃师","f":"五言古诗","c":["清代服朝命，怀此好爵縻。","安知失所怙，抱恸俄在兹。","辍理遵反路，岁暮风凄凄。","行行泣且悲，血泪不可挥。","归当趋故庭，益复哀以思。","竭力谅弗逮，致身犹可希。","庶几强节恸，显扬以为期。"]},{"t":"黄侍读家赏瑞菊","f":"五言古诗","c":["霜降丰钟鸣，虎啸谷风生。","气类各有召，何况善所徵。","君子际昌期，冠绂趋明庭。","致勤靡夙夜，惟恭秉忠贞。","至诚会感孚，嘉祥聿来应。","众卉悴寒节，贞菊粲前楹。","同叶迸赪蕤，骈芳出紫茎。","动如比翼翔，静若连理荣。","夕下玉堂中，高贤集良朋。","玩赏验至理，讴吟播芬馨。","孰云微植兹，从知兆方兴。","谨始永弗渝，奕世垂休声。"]},{"t":"送杨参政景衡考绩还福建","f":"五言古诗","c":["恭命佐南服，缅临山海区。","旬宣尽臣职，夙夜忘其劬。","恻恻轸民隐，宛宛运良谟。","明如孤月悬，温如春阳舒。","八州谅闳远，惠化罔不敷。","行身著表率，下者无侵渔。","千里亘弦歌，遐迩皆晏如。","考绩属兹岁，整驾趋皇都。","峨峨双龙阙，彤闱焕金铺。","剑佩森九陛，朱衣肃来趋。","拜辞遽徂征，言归即脩途。","相送国南门，何以赠离居。","宦成古所戒，善始贵无渝。","期君永终誉，庶贻青简书。"]},{"t":"赋得快阁送曾日章使安南","f":"五言古诗","c":["朝日丽金闺，赪霞焕彤庭。","拜辞出君门，岁暮万里行。","行指古交州，南云杳冥冥。","骏马向风嘶，翩翩逐行旌。","遥经彭蠡泽，还过西昌城。","杰阁何巍巍，弭节一来登。","章水朝宗去，三山如秣陵。","思忆双龙阙，北望心怦怦。","怀远由圣君，宣德命九卿。","载驰实臣职，岂敢稽王程。","伊昔黄太史，遗祠并南楹。","且复礼前脩，感激慕忠贞。","逝矣慎树立，千春齐鸿名。"]},{"t":"送吴寺丞归滁州","f":"五言古诗","c":["白露下梧桐，秋风激砧杵。","策马出都城，扬舲越江浦。","朋游皆伫立，望望滁阳路。","昨晤恨已迟，晨别嗟何遽。","念君将门子，恬澹如韦布。","文藻发篇章，游情在毫素。","前者抚茕嫠，攀辕惜其去。","归来官太仆，优游九卿副。","三载畜蕃息，考绩腾令誉。","琅琊山水清，周游昔已屡。","归心复遄飞，斯须不相顾。","安得往从之，一写予所慕。"]},{"t":"送邹尚友赴澧川","f":"五言古诗","c":["新春散寒冱，旭日明江浦。","浦树净亭亭，犹含夜来雨。","远客促行迈，故人皆出祖。","初来自西川，遄征溯南楚。","离别即须臾，晤言方几许。","圣朝悯茕嫠，简贤需召杜。","恺悌终荐达，承流寄绥抚。","澧水出涔阳，东连洞庭渚。","其俗本惇朴，其民素贫窭。","竭力供县官，何尝厌勤苦。","兹晨望贤牧，蚤暮急延伫。","行矣敷仁恩，殚心副当宁。"]},{"t":"赠王行敏","f":"五言古诗","c":["芙蓉丽晨旭，粲烂云锦垂。","采折欲有赠，徘徊增离思。","嘉晤讵几日，星言复南驰。","滔滔逝长驶，流光奄如之。","念子昆山秀，皎皎瑚琏姿。","终当膺荐达，磨琢贵及时。","高斋面山水，卉木含华滋。","栖迟固适意，静脩谅所宜。","勉哉慎树立，以副平生怀。"]},{"t":"蒋用文院判静学斋诗","f":"五言古诗","c":["斋居临广衢，靓深绝尘氛。","嘉卉粲前列，芳帙左右陈。","君子抱异尚，稽古夙所敦。","鸡鸣整冠佩，肃肃趋枫宸。","既退此閒逸，旷然谢纷纭。","农轩回夭折，周孔明义仁。","往轨悬日星，力探冀身臻。","志宁启妙悟，黾勉忘宵昏。","静虑而有得，尝闻先哲云。","看君振高策，奕世扬清芬。"]},{"t":"题王孟瑞写竹寄本之","f":"五言古诗","c":["北风起郊甸，寒声骤长林。","引领睇溧阳，怀贤思弥深。","耿介直士节，幽贞君子心。","平生惇契好，如彼双南金。","昔别夏未届，今来春载临。","吴丝将蜀桐，和谐会相寻。","岂乏桃李花，秋霜易见侵。","懿此岁寒操，持贶心所钦。"]},{"t":"胡学士山居八景之二首竹坞云林 其一","f":"五言律诗","c":["衡门对芳坞，上有脩竹林。","旦暮碧云合，晻霭成幽森。","云起歘乘运，从龙沛甘霖。","终焉君子节，永矢岁寒心。"]},{"t":"胡学士山居八景之二首竹坞云林 其二 夫容寒雪","f":"五言律诗","c":["结庐在沧洲，前对夫容好。","寒冬飞雪凝，开门玩琼岛。","皎洁如我心，揽之以为宝。","出处自不渝，可与知者道。"]},{"t":"题三顾山刘氏文会堂卷","f":"五言古诗","c":["岧峣三顾山，飞流下澄澈。","灵秀之所萃，爰昔钟贤哲。","正学明纲常，直气遏邪孽。","至今乡闾士，堂堂仰清节。","书台郁崷崒，遗风耿未灭。","比屋俨缝掖，群居蹈高洁。","之子抱贞素，曾何污缁涅。","奕奕峙堂搆，翛翛荫林樾。","岂乏谷粟储，群书富罗列。","同志五六辈，时来共怡悦。","研覃溯周孔，辨析穷毫发。","至道日有得，中怀炳昭㫼。","明善固所资，诚身理逾切。","愿惇辅仁训，庶不忝先烈。"]},{"t":"题商颜东山二图 其一","f":"五言古诗","c":["迢递商颜下，优游晏岁时。","玉泉流石乳，青松荫紫芝。","非为文成君，姓名谁见知。"]},{"t":"题商颜东山二图 其二","f":"五言古诗","c":["夙尚在高洁，雅怀非陆沉。","东山讵云远，苍生望亦深。","孰谓高卧者，而无匡济心。"]},{"t":"盘龙晓翠诗","f":"五言古诗","c":["英年擅文翰，雅韵超凡庸。","家临文水湄，门瞰盘龙峰。","蜿蜒带城闉，崒嵂凌高穹。","诘朝敞东轩，初旭明瞳眬。","宿霭静阴翳，秀色开青葱。","凝辉射虚牖，含润清帘栊。","正襟此晤对，澹然浮虑空。","趣与妙景会，心将玄理融。","稽古率攸行，进退其有穷。","恒惇旦气养，庶期日新功。"]},{"t":"西畴耕读","f":"五言古诗","c":["幽栖寡世营，结庐在西墅。","充室惟诗书，开门绕田圃。","方春九扈鸣，俶载向南亩。","高原燥宜黍，下隰湿宜稌。","种植既得时，耘耔亦无苦。","况当长养节，霢霂承膏雨。","朝耕暮还息，潜心以稽古。","上窥姚姒馀，下掇姬孔绪。","黾勉究微言，优游启玄悟。","所得欣日新，逍遥自容与。","年登秋穫竟，穰穰溢我庾。","击鼓荐牺牛，欢娱报田祖。","傍舍数老人，言行皆邹鲁。","相与知帝力，讴歌颂明主。","陶然墟里间，终岁同乐处。"]},{"t":"龙给事湖心草堂图","f":"五言古诗","c":["巢湖介淝舒，子昔所栖迟。","葺茅结幽宇，远托湖中坻。","开轩面远岫，绕槛荡文漪。","幽坡藉丰茸，芳林揽葳蕤。","远绝往还迹，閒适惟诗书。","朅来游虎闱，逦迤登赤墀。","驰声倚文翰，焯有好爵縻。","岂不怀初服，引睇渺天涯。","致身义所重，在旧仁不遗。","自公有馀暇，披图写遐思。"]},{"t":"送周孟简乃兄","f":"五言律诗","c":["龙楼彻五鼓，城上乌啼曙。","客子思故乡，晨衣出门去。","犹顾玉堂馆，忽别金陵浦。","明日大江干，相思荆树寒。"]},{"t":"王孟宣挽诗","f":"五言古诗","c":["四时迭迁易，化运无停机。","人命合坚固，忽为朝露晞。","平生所亲爱，谁不悲永违。","况乃德之良，特达众所希。","惇行孝与弟，蹈履慎其微。","百岁自恒道，胡为中路萎。","不见凉薄人，高年踰耄耆。","古谓仁者寿，圣言岂云非。","松柏绕丘坟，萧萧起寒飔。","即此杳长夜，念之增歔欷。"]},{"t":"送王裕归临川","f":"五言古诗","c":["朔风暮已厉，蓟门凛寒霜。","之子返故邑，星言肃遐装。","长跽拜慈父，含悽别高堂。","亲爱自天性，谁不情内伤。","所怀在重闱，晨夕遥见望。","驱车逐徒侣，欲往仍徬徨。","为孝行所先，养志古所臧。","翩翩丹凤雏，五色会高翔。","含辉璞在石，戒溢川维防。","爱子以进脩，眷言赠斯章。"]},{"t":"玄默斋诗","f":"五言古诗","c":["至道本无为，达人识其原。","静居玩群化，通复皆自然。","物理谐妙契，缅邈适大观。","怀中老聃书，置之已忘言。","冲澹颐性灵，寂寞卧云山。","松柏荫庭外，众卉罗松边。","聊以验气序，随时乐吾天。","余始识其人，翩翩复高骞。","何当往从之，俱游象帝先。"]},{"t":"赠曾生景铭","f":"五言古诗","c":["君子重时命，有塞必有通。","古来才智人，岂必畎亩终。","晚成见大器，特达会奋庸。","曾生格有司，迢遥理归篷。","璞玉宁久閟，志士宁久穷。","林居有馀暇，往懋切磋功。"]},{"t":"孙给事小画","f":"五言古诗","c":["俱怀坚贞节，云根偶相遇。","投我双翠翘，报以珊瑚树。","永矢冰霜时，欢依共迟暮。"]},{"t":"送陈生还吉水","f":"五言古诗","c":["家住文江头，东望秦淮涘。","恋恋父子情，迢迢隔山水。","粤昔奉父母，留侍大母居。","重闱供甘旨，旦夕承婉愉。","久违父膝下，仰慕闻诗礼。","况乃大母心，惓惓念行子。","北地困远涉，风霜多苦颜。","幸复荷荣宠，何时见斓斑。","昨者促我来，令我慰羁旅。","腊月达京城，升堂拜父母。","我父见子来，惊起还悲叹。","别时汝总角，汝今已胜冠。","我母见子来，怜我克孝敬。","念我涉苦辛，问我行久近。","各言问大母，大母今寿康。","听荅未及已，零泪沾衣裳。","我留侍父母，蔼蔼天伦乐。","诲语日殷勤，离怀顿舒豁。","舒怀未几许，我父呼我言。","父母喜汝来，大母傒汝旋。","我未报国恩，养亲诚赖汝。","事父汝日长，遄归勿辞苦。","拜跪受父教，黾勉惟敬承。","晨起别高堂，扬舲复南征。","维时二月初，春风动杨柳。","父执书赠言，朋游劝行酒。","人生尚孝行，子归重操脩。","矧子英妙年，勉学循嘉猷。","而翁我同朝，且复同乡郡。","何以赠子行，努力崇令问。"]},{"t":"送黄学士还永嘉 其一","f":"五言律诗","c":["圣皇御宸极，垂拱朝万方。","时康洽泰和，化理侔虞唐。","公卿侍黼扆，文儒列成行。","济济集天衢，辉辉被宠章。"]},{"t":"送黄学士还永嘉 其二","f":"五言律诗","c":["宠章一何盛，㴑源嘉所生。","文锦盘双龙，奎光焕然明。","岂但隆褒敡，重以命秩荣。","馀龄沐天泽，感激深中情。"]},{"t":"送黄学士还永嘉 其三","f":"五言律诗","c":["深情仰都畿，逝将谒天子。","夕发斗城隅，晨趋阊阖里。","鹤发耀冠缨，龙颜顾为喜。","拜稽颂万年，惓惓未能已。"]},{"t":"送黄学士还永嘉 其四","f":"五言律诗","c":["惓惓事君忠，虽耄志益强。","载来即华馆，嘉庆洽中堂。","怡愉奉甘旨，拜跽陈寿觞。","眷言皇天慈，奕世弗可忘。"]},{"t":"送黄学士还永嘉 其五","f":"五言律诗","c":["弗忘在君亲，桑梓翳丘园。","别离未几时，履此霜露繁。","遥遥遵返路，靡靡涉川原。","来归诚所忻，恋阙心弥敦。"]},{"t":"萧处士挽诗","f":"五言古诗","c":["悬象无停运，四时迭迁逝。","人非金石坚，百岁忽如寄。","有生必有终，惟德世所贵。","夫子武夷秀，家承兰陵系。","寡欲出天赋，惇行在伦谊。","饬躬仗忠贞，及物崇惠施。","栖迟恒采芝，淹留聊攀桂。","逍遥以卒岁，颓然谢尘世。","天道显而信，世泽久益大。","令子奋六艺，华声扬旆旆。","身有好爵縻，行惟先人似。","源深自流远，绳绳殊未替。","頫仰念潜德，因之徵来裔。"]},{"t":"退思轩为淮阳刘千户赋","f":"五言古诗","c":["结发在军中，幸际熙明时。","声教洽四海，不闻羽檄驰。","家承厚禄贵，身有好爵縻。","虽怀铅刀用，一割不及施。","自顾草木微，芳泽振华滋。","感激天地恩，胡能分寸禆。","惟应笃忠贞，庶不忝恩私。","庶事如猬毛，何以适攸宜。","发已一失经，臣职隳自兹。","岂但羞荣宠，安危诚系之。","歉歉内自怀，兢兢恒自持。","高轩敞弘丽，退食时在斯。","先哲有明训，揭以为箴规。"]},{"t":"题范仲伦纪善攀桂轩","f":"五言古诗","c":["团团青桂树，高高凌紫虚。","根本积深厚，柯条郁纷敷。","风云荡杳霭，雨露涵浸濡。","当春竞妍华，不与桃李俱。","秋气悴万卉，孤芳乃芬如。","金彩耀朝晖，天香含满裾。","轩居延爽霁，静对古人书。","观道可适怀，何必倾一壶。","居止得嘉荫，悠然尘虑袪。","缅惟种植勤，今来百岁馀。","先人义方训，遗我以良图。","幽贞媲令德，安敢废斯须。","光华际昌辰，歘起应时需。","攀援聊淹留，非为乐其初。","念兹保明诫，岁晏以终誉。"]},{"t":"送王孝子归成都","f":"五言古诗","c":["蜀岭春雪消，秦淮新水衍。","万里蜀中人，见水思乡县。","去年在亲侧，今年在帝畿。","非缘同产故，谁肯离亲闱。","一朝复一朝，思亲心若燬。","问君刲股时，痛迫何如此。","初发白鹭洲，忽过黄鹤楼。","巴陵寻旧里，荆门溯上游。","家林行渐迩，算程应预喜。","猿啸岂关情，鹃啼空在耳。","倚门望莱衣，踉蹡五色归。","供馔黄鱼美，登盘丹荔肥。","亲年方寿考，归来誓相保。","长承膝下欢，不出门前道。"]},{"t":"送陈景著编脩以母老乞近地得福州教授","f":"五言古诗","c":["振佩谢彤陛，驱车出重城。","堂中有寿母，奉以趋脩程。","秉志存事君，母也迫衰龄。","仰荷圣主仁，俯谐乌鸟情。","维时六月中，流金赫炎蒸。","行路岂不难，适愿心孔宁。","济济玉堂侣，祖饯罗冠缨。","眷言夙昔好，何以赠子行。","易得四海誉，难致乡里名。","矧乃来学众，逝将于我承。","黾勉慎所操，庶用闳休声。"]},{"t":"送聂教谕赴贵州","f":"五言古诗","c":["往与子别者，乃在江汉湄。","江汉日夜流，岁月忽如驰。","相思隔川岳，于今已十期。","子家清江曲，夙有温厚资。","少小入乡校，育德穷书诗。","中岁登成均，鸿鹄摩天涯。","金石恊其音，佩玉昭其仪。","拜为博士官，小试百里师。","诜诜游学徒，左右侍皋比。","成德与达才，造就咸适宜。","九载绩用成，入奏趋彤墀。","升迁荷荣宠，欣欣遂其私。","职不踰文教，出不越皇畿。","明晨整行装，王程讵能违。","嗟子契阔怀，慰悦宜在兹。","终焉乖所愿，坐以职务縻。","过门弗及迓，出祖弗及追。","引望池阳峰，曷慰中渴饥。","幸逢熙明运，会合谅有时。","惟应保贞素，迟暮以为期。"]},{"t":"题访戴图","f":"五言古诗","c":["寒宵雪初霁，明月照庭前。","独酌山阴酒，含咏招隐篇。","良朋忽兴念，怀往方浩然。","溯洄剡中行，玉色晃山川。","道长兴易穷，回舻遽言旋。","性情自不羁，动止故无牵。","放旷非可则，犹为画者传。"]},{"t":"题文丞相字","f":"五言古诗","c":["惠风布和气，流云度春阴。","时卉播芳润，嘤鸣怀好音。","邑中理琴罢，逍遥翰墨林。","图帙左右陈，永谢浮虑侵。","静观悟玄化，油然适我心。","奄忽百岁馀，名德扬至今。","烨烨文山书，尚照文水浔。","惟应嗣世者，持用宝南金。"]},{"t":"谢赐嘉禾诗","f":"五言古诗","c":["玄天肇昌运，皇明启隆祚。","有赫清泗滨，笃生我皇祖。","于维皇祖圣，桓桓秉神武。","于时草昩际，阴氛蔽寰宇。","受命提天戈，吊民麾虎旅。","吴楚扫欃枪，幽并驱罴虎。","函夏复清宁，穷櫩息咻喔。","迤逦五教敷，从容九功叙。","弦歌亘远域，锄耰隘荒墅。","浸淫俗化淳，汪洋德施普。","昊天监昭事，骈蕃荅纯嘏。","五纬无留逆，四时皆顺序。","休祉万斯臻，丰年岂惟屡。","大田毓祯谷，芃芃映黍稌。","圣世跻泰和，圣情聊暇豫。","雍雍发歌咏，辉辉粲毫素。","文如虬龙跃，又如鸾凤翥。","音如咸韶会，气如春阳煦。","上乐帝眷顾，下乐民康富。","丕显并周文，不矜同姒禹。","于维我皇祖，功德侔三五。","俯睨汉与唐，陋哉畴比数。","宸章隐中秘，至宝终明著。","陛下握乾符，垂衣缵鸿绪。","琬琰昭大刻，臣工拜嘉予。","旦旦睹奎光，渊渊仰皇度。","诚由陛下圣，心存有虞慕。","益勤继述志，遂隆显扬务。","睿制超百王，至孝踰千古。","敬撷舆人言，陈诗献当宁。"]},{"t":"望云诗","f":"五言古诗","c":["少小失所怙，鞠我仰母氏。","我今已成立，母氏隔千里。","朝亦思母慈，暮亦思母慈。","愁肠日九回，朝暮千万思。","官列九卿贰，迎养失所愿。","母来止岁馀，母乐归乡县。","虽有两贤弟，致敬奉母居。","我独不在侧，何以纾郁纡。","荷君恩宠深，忆母道途远。","仰首望飞云，秦山长在眼。","小儿解父意，愿父勿忧叹。","我归养大母，父但忠王官。","一门隆孝行，父子及兄弟。","所以白发亲，怡怡膺寿祉。","敦行用表率，岂不自一身。","观感动乡里，咏歌扬缙绅。","君亲同所尊，忠孝匪二道。","努力慎克终，来世焯有耀。"]},{"t":"明明处士挽诗","f":"五言古诗","c":["岧峣金螺山，螺山水逶迤。","螺水逝不还，螺山空云飞。","我怀贤达人，寂寞今安之。","在世无所系，去去忽如遗。","郁郁乔松树，舟车谅所宜。","何为南山中，空负高洁姿。","寒暑若循环，四时屡迁移。","傲兀冰与霜，欣荣迟暮时。","中有丹凤雏，五章备羽仪。","高举戾阿阁，嗈嗈鸣朝曦。","凤雏忽已去，乔松复倾摧。","瞻望杳不及，行者皆歔欷。","俯仰念畴昔，我独有馀悲。","矫首睇螺山，阁泪书此辞。"]},{"t":"挽永嘉胡处士","f":"五言古诗","c":["流波逝不息，时序无停迁。","嗟彼泉下人，一往不复还。","追惟在世时，卓荦称英贤。","芳馨佩兰茝，被服夫容鲜。","幽居玩玄化，历探羲皇前。","步履率周行，饮濯必清泉。","一朝逐征风，飘然若云烟。","反终自常道，怀德谅难捐。","幸睹五色雏，及时厉高鶱。","黾勉务显扬，夙夜志惓惓。","煌煌金石词，足为永代传。"]},{"t":"送谢宪使还广西","f":"五言古诗","c":["谢公青云器，发身自科名。","初命属司寇，特达蜚贤声。","十年典大郡，政化龚少卿。","遂升董外宪，八桂歌澄清。","展矣冰雪操，谅哉矜恤情。","圣人御寰宇，简贤寄嫠茕。","安得皆若人，四海臻咸宁。","春兰花始开，述职趋明廷。","我昔尝同朝，相见慰平生。","握手甫一再，驱车复南征。","故写向往意，聊赠万里行。"]},{"t":"送黄知府还琼州 其一","f":"五言律诗","c":["萧萧朔风劲，慄慄年岁徂。","积雪横山冈，凝冰塞川途。","念子万里行，相送城南隅。","寒树渺苍茫，谁能忍离居。"]},{"t":"送黄知府还琼州 其二","f":"五言律诗","c":["离居昔不浅，晤语今还促。","郡府分南溟，烝黎望贤牧。","寒晖动飞旆，浮埃暗驰毂。","远举凌冥冥，临岐羡鸿鹄。"]},{"t":"送黄知府还琼州 其三","f":"五言律诗","c":["鸿鹄翔翩翩，倏忽天之涯。","丈夫抱奇才，致用贵及时。","山川历缅邈，何以赠仳离。","永矢冰雪操，迟暮以为期。"]},{"t":"挽凌孝子","f":"五言古诗","c":["闽有凌孝子，十六丁丧乱。","辛苦奉双亲，岩谷日奔窜。","晨汲寒涧饮，暮拾枯薪爨。","跬步皆畏途，触目增愁叹。","百死幸脱归，双亲遄弃违。","艰难殡浅土，恸哭血泪挥。","孤身惟影伴，㷀㷀竟何依。","经年寇盗息，来返乡园扉。","拮据葺屋庐，黾勉遂家室。","处宗仁有施，处乡义无失。","宁辞荐辟荣，甘就原丘逸。","云胡未下寿，盖棺事奄毕。","昔有江巨孝，汉史高其人。","谁言千载下，令德无与伦。","天道远弗爽，为善福必臻。","凌氏身后荣，煌煌垂不泯。"]},{"t":"陶氏荣节堂","f":"五言古诗","c":["人生伉俪情，所愿偕白首。","二九归陶家，三八为孀妇。","抱持襁中儿，辛苦难具论。","矢心只如一，儿大今有孙。","紫凤衔天书，光华见旌表。","孙长登科名，更觉门庭好。","皇天佑节义，降福无穷期。","永歌荣节堂，聊继柏舟诗。"]},{"t":"挽诗","f":"五言古诗","c":["欧乡有贞士，萧散离尘俗。","家庭崇孝德，宗姻重惇睦。","交友执信义，恂恂在乡曲。","雅度廓有容，好善如不足。","浮云抗志尚，兰茝充佩服。","爱子以力学，诗书贮连屋。","飞腾自庭下，玉立见鸾鷟。","高堂致滫瀡，十载京华禄。","八十馀三龄，长往遽不复。","怀贞写哀些，聊为蒿里续。"]},{"t":"题古木幽禽图","f":"五言律诗","c":["古木含春泽，纷敷枝叶清。","群飞各有类，动息相和鸣。","蔼蔼天地间，品物遂生成。","无轻画史意，可怡仁者情。"]},{"t":"送彭学修之兴宁知县","f":"五言律诗","c":["平生慕为县，可以恤嫠茕。","不得真由命，傍观却怆情。","吾乡有彭子，发轫宰兴宁。","送尔慎树立，行看起令名。"]},{"t":"追赋袁氏瞻衮堂","f":"五言古诗","c":["中岁谒金阙，恭承明圣恩。","千载之所遭，锡命久益蕃。","重爵与厚禄，颂台烨高鶱。","泰坛切紫霄，清庙凌绛云。","天子奉明禋，周旋严骏奔。","祀事国所重，为荣安可言。","朅来遂悬车，言归东海濆。","何以报盛德，惓惓中心存。","兴居兼食息，一惟我圣君。","祗若聸龙衣，肃若仰临轩。","仰祝万万寿，悠久齐乾坤。","大书揭中堂，庶庸示无谖。","嗟哉逝已远，敬率惟后昆。"]},{"t":"题梅","f":"五言古诗","c":["桃李盛芳妍，春风一朝歇。","穷冬岁华尽，见此枝上雪。","天寒渺空阔，清香表高洁。"]},{"t":"馀姚陈处士挽诗","f":"五言古诗","c":["桂树生堂阶，秋霜悴其英。","秋霜自恒化，能不怀芳馨。","人无金石资，安得独长生。","形质虽化尽，惟善远益称。","缅彼林居士，素履笃幽贞。","恂恂孝友德，坦坦君子行。","推己务惠济，洁身谢浮云。","一朝尽天年，奄兹三纪盈。","松柏绕丘墓，凌云郁青青。","终令怀德者，凭轼怆中情。"]},{"t":"题山水图","f":"五言古诗","c":["结缨二十载，素发忽盈簪。","才薄识且疏，驱驰百不任。","忧虞积怀抱，流尘暗衣襟。","潇散此谁与，结庐在幽深。","危峰叠苍翠，灌木郁成阴。","奔泉泻石涧，浮岚掩遥岑。","骀荡时物荣，交交响春禽。","趣与清景会，而无尘俗侵。","窗中南华篇，流玩以澄心。","相知一二辈，囊琴亦来寻。","更迭为我弹，泠泠皆雅音。","怡然乐吾天，抚卷心为歆。","俛首发长叹，怅然兴越吟。"]},{"t":"脩敬斋","f":"五言古诗","c":["士学之所本，乃在方寸间。","出入慎省察，奉持常拳拳。","执虚如执玉，处独如临尊。","主一不二适，存养静以专。","益久虚且明，万理自森然。","所以德之聚，古人有名言。","罗生豫章裔，家学探渊源。","脩敬揭斋扁，瞻对如孔颜。","肃中戒外驰，宴坐必衣冠。","云谷有明训，昕夕勤钻研。","勉哉在惇行，勿云知者难。"]},{"t":"桃源县","f":"五言律诗","c":["泊舟桃源县，满目生秋草。","不见桃花林，但见牛羊道。","临江尽茅舍，绕屋惟桑枣。","尚有淳朴风，何由恣幽讨。"]},{"t":"九日发桃源遇便风","f":"五言古诗","c":["出门已六日，嘉节逢重九。","旭日明秋空，川原净氛垢。","寥寥数家村，茅檐荫榆柳。","绿醑堪旋沽，黄花何处有。","张帆乘便风，舟行疾于走。","前岸渺弥望，瞬息属回首。","桃源下百里，不待晨炊后。","北京缅迢递，王程畏迟久。","举觞问河神，明晨还送否。"]},{"t":"新安驿奉简蹇公及公素","f":"五言古诗","c":["解缆未十里，峥嵘乱云黑。","北风吹波立，进咫退已尺。","努力度前湾，依林聊暂息。","船窗雨穿溜，狼藉沾衣席。","局蹐拥毡毳，愁坐终日夕。","仆夫劳敝馀，饥寒皆失魄。","对此伤人心，奈何远行客。","中宵豁阴翳，青天流月色。","同舟各解颜，安卧免欹侧。","人事有仓卒，天道叵测识。","向来行路难，未有新安驿。"]},{"t":"送周布政还广西","f":"古风","c":["周子湘中彦，桂芳昔同官。","清姿玉瓒贵，雅量湖海宽。","所发必归厚，所履必由端。","霜台既展骥，秋曹亦翔鸾。","中尝擢近职，所树皆桓桓。","遂授方岳寄，八桂开大藩。","勉勉敷上德，孜孜救民难。","温若春阳煦，润若时雨?。","劳勤十载馀，坐镇边隅安。","考绩进禄秩，蒙恩复南辕。","嗟予久间阔，暂晤仍鲜欢。","相送即脩途，相期惟岁寒。","何以表中愫，聊赠青琅玕。"]},{"t":"送芮长史致政还乡","f":"五言古诗","c":["芮君毗陵彦，发轫贤能科。","十年凤凰池，近侍增光华。","简升春宫臣，司经侍讲席。","朝绅五品贵，旦暮储皇侧。","鞠躬勤小心，言行恪有常。","出入谨仪度，玉佩鸣玱玱。","再升亲藩辅，所寄诚独重。","正道与直言，肯惭贾与董。","春秋登七十，从容告归休。","拜稽辞贤王，归朝谢宸旒。","我昔官桂芳，于君实联署。","况复紫垣南，廨宇相邻住。","相亲日相好，岁久交谊深。","明月映澄潭，两照知己心。","暮龄乃乖分，关山隔南北。","时诵停云诗，相望但相忆。","今来语未竟，遽复倒离尊。","重晤知何时，黾勉频加餐。"]},{"t":"题枯木竹石","f":"五言律诗","c":["乔木风霜古，贞石金铁如。","所以尚志人，乐偕木石俱。","况有淇澳姿，清风当座隅。","力田有馀暇，足用适诗书。"]},{"t":"送徐提点被召赴北京","f":"五言古诗","c":["圣人嗣天位，郊庙亲玉鬯。","明堂一弘新，禋祀徵助相。","之子奉纶音，诘朝戒征两。","岧峣万岁山，双阙五云上。","鹓行余将簉，鹤驭子先倡。","纷若明汉星，皆维北辰向。"]},{"t":"送史常","f":"五言古诗","c":["君子达义命，不为外物骛。","孳孳脩其身，贵贱安所遇。","青蝇污白璧，自古有不虑。","曾参不杀人，谗言令母惧。","直生见诬金，赏之亦不忤。","暧昩须臾间，光明悬竹素。","之子抱夙尚，雍容伟仪度。","读书膺荐达，操节致时誉。","遂拜二千石，分符牧黎庶。","所务廉与仁，果得茕嫠慕。","磷缁出媒蘖，不辨亦不怒。","怡然返初服，脱洒谢羁马。","拜辞出都门，春华未迟暮。","白云动高兴，清莺满长路。","家在溧水阳，行行见乡树。","上堂悦父母，下堂洽亲故。","人生有至乐，岂必贵与富。","念子相知旧，此别何时晤。","浩浩缱绻怀，因诗一披露。"]},{"t":"赠萧大庆教谕诗","f":"五言古诗","c":["西昌邑东南，桃源擅潇洒。","萧氏所世居，彬彬见文雅。","我识斯贤翁，魁厚称长者。","昔在元季时，寇敚充四野。","翁奋捐帑藏，保障厥邻社。","其季安敬甫，清襟浩倾泻。","惜哉不永年，乡闾共嗟咤。","德邻自幼孤，好学出陶冶。","于义必踊跃，于利岂苟且。","穰也有凤毛，幼学勤不舍。","黄卷三万轴，一目数行下。","诜诜群伦中，指谓千里马。","昨领乡书升，会试登榜亚。","除授金乡邑，饯别持杯斝。","索我赠行言，顾我今衰也。","惟敩学之半，黾勉无自假。","德义士所珍，富贵直土苴。","勖哉务进脩，勿言知者寡。","诲人在善诱，不在楚与夏。","愚直苟不遗，可用膺纯嘏。"]},{"t":"送罗崇本进士归省","f":"五言古诗","c":["北阙雨新霁，上林莺正飞。","朝侍岂不荣，关山远庭闱。","经年定省旷，累月音书稀。","摇摇一寸心，遑知渴与饥。","恭承圣主赐，宁亲暂南归。","高堂寿且康，承欢足光辉。","家庆诚所乐，王程顾无违。","赠子淇澳咏，自脩慎其微。","中和饬德性，昔贤有佩韦。"]},{"t":"忠孝堂诗","f":"五言古诗","c":["少小天所生，㷀㷀罔怙恃。","永怀鞠育劳，食息靡暂置。","黾勉务显扬，卓卓挺立志。","初命属鸿胪，敬恭事廷序。","西江吉名郡，再命升幕贰。","颛颛秉诚节，孳孳究职事。","岂直简牍间，期禆贤守治。","忠孝表厥居，夙夜图罔愧。","古来勋德人，皆起自奋励。","蒙泉达于海，寸萌干云际。","维持不息功，无远弗可至。","资孝以为忠，人道第一义。","勖哉在方寸，何古不可跂。"]},{"t":"送曾蒙训分教弋阳","f":"五言古诗","c":["明珠产合浦，奇璞出蓝田。","士生礼义门，由来端且贤。","曾氏吾同里，诗书奕世传。","科名起特达，赫赫光后先。","之子禀赋异，秀质何娟娟。","少小服家训，一志勤简编。","插架皆手泽，旦夕侍钻研。","致恭闾曲间，出入恒颛颛。","名达部使者，荐上吏部铨。","天子试文辞，挥毫玉陛前。","擢佐百里教，往分博士筵。","维时七月中，芙蓉秋满川。","驱车出潞滨，问买江南船。","弋阳几日至，定及黄花鲜。","训迪敦表率，荐祀致精虔。","劲翮在远霄，宁当久翾翾。","功行贵及时，无为孤盛年。","流光逝不处，伫聆清誉宣。"]},{"t":"题画送陈景茂归金华","f":"五言古诗","c":["孟冬寒气肃，霜叶坠纷纷。","把酒别故人，含情睇征轮。","忆子初升时，永乐第二春。","简入丝纶阁，一见心相亲。","于时几务殷，旦夕翰墨勤。","开口见肺肝，躬劳迈群伦。","两京三十载，恭事四圣君。","方来未壮龄，鬓毛忽成银。","幡然辞宠禄，归偶击壤民。","失足遇一跌，观过知其仁。","平生恻怛心，倾家振饥贫。","九重嘉行义，自天荣命新。","万里谢彤庭，兴逐南飞云。","峨峨金华山，流泉下潾潾。","梧竹荫我屋，白石为我邻。","于兹坐閒逸，超超绝尘氛。","重晤当何时，安常以自珍。"]},{"t":"送杨礼郎中还南京","f":"五言古诗","c":["季夏当炎熇，时雨集行潦。","宛宛晴莺鸣，空埃净于扫。","子来未几日，告归一何早。","爱子闽山秀，襟宇清皓皓。","诗书出桥门，瑞玉出文缫。","峨峨天官属，最绩屡书考。","子家贤伯兄，勋庸四朝老。","所重同气良，相见心倾倒。","连床夜听雨，方兹豁离抱。","晨起复暌违，中怀增懆懆。","我亦惇同宗，交情久逾好。","聚合焉可常，仳别未足道。","敬身誉所兴，崇饮匪自保。","相期南山柏，苍翠拂穹昊。"]},{"t":"慈节堂诗","f":"五言古诗","c":["桓桓萧将军，秉义奋英武。","提剑雄万夫，委身报明主。","于时羽林孤，未龀恸何怙。","鞠育兼训教，劬劳仰慈母。","母抱金石志，矢天与天语。","惓惓未亡人，肯愧黄泉下。","诏下录功勋，遗忠上天府。","寡稚沐宠恩，棨戟光门户。","鹤发寿且康，珠翟明翠羽。","儿大八尺躯，卓卓挺禦侮。","操廉赞雄藩，言言浙江浒。","入门祗奉养，出门饬师旅。","一心君与亲，夙夜怀靡盬。","惟患忝所生，讵辞躬勤苦。","令德萃一堂，肇光自贤父。","闻之谩成咏，用示观风者。"]},{"t":"送王希积训导归西昌","f":"五言古诗","c":["子家县城西，我家县城东。","两家世婚媾，况复文献风。","我生甫十年，时节诣王氏。","所重先代交，肯耻遗孽子。","王氏两尊翁，颙昂众具瞻。","长翁春阳煦，次翁秋霜严。","矜我故人孙，每见垂接诱。","或頫摩其颠，或引执其手。","随事赐诲教，不间精与粗。","亦或厉颜色，绳过及砭愚。","我稍辨路蹊，两翁厌尘世。","老成一凋亡，如矇迷所逝。","后来琼台公，亦得承切磋。","终焉聚时少，不如别日多。","中岁仕京华，而翁亦继起。","同在玉堂署，还同职文史。","同心奉四圣，两京三十春。","出入常相比，居止常相邻。","有酒相劝酬，有诗相赓咏。","襟怀同一清，冰雪炯相映。","众星不逮旦，松柏见严冬。","向来亲好人，存者两衰翁。","王氏森佳儿，玉树照庭庑。","顾我独何为，忧煎迫心苦。","子出自昆冈，佩服书与诗。","他乡屡邂逅，无几辄乖离。","朝家有大事，匍匐万里至。","因遂跻高堂，觐省慰亲意。","十月蓟北寒，朔风断河流。","岂不恋侍下，公程迫难留。","我具斗酒酌，送子即远道。","追惟子先祖，中怀惄如捣。","峨峨邑黉宫，诜诜于子师。","问学资其求，言动表其仪。","才器之所成，必出良模范。","子家崇庆守，前矩犹可鉴。","为教在立本，致道而笃行。","逝川苟不息，沛然达沧溟。","坦坦白龙洲，湜湜金鱼浦。","庶闻百里间，士习追邹鲁。"]},{"t":"题陈宪山水","f":"五言律诗","c":["乔林远人境，山水满幽庭。","薰风昼南来，嘤鸣清可听。","居贞守恬寂，聊自颐性灵。","杳杳清冥上，谁见少微星。"]},{"t":"题青山白云图赠宾畿老弟南归","f":"五言律诗","c":["白云三万顷，水木共清华。","衡庐不可辨，依约见仙家。","赠尔江南去，秋高八月槎。","离情方浩浩，矫首雁行斜。"]},{"t":"题宾畿弟竹石图","f":"五言古诗","c":["园林春雨后，新竹翠凌云。","还荫云根润，虨虨绿藓文。","清风来白日，潇洒净尘氛。"]},{"t":"题宾畿弟木石图","f":"五言古诗","c":["少耽木石趣，家与木石邻。","清涤涧泉冷，润含山雾春。","应无射虎者，时有斸苓人。"]},{"t":"赠杨晟参政还福建","f":"五言古诗","c":["杨子河南俊，诗书夙所务。","蚤膺大廷选，从事玉堂署。","步履循周行，居心在忠素。","抽毫立螭陛，鞠躬谨常度。","济济近侍班，娟娟水玉柱。","一朝起高擢，万里南闽路。","大藩开海隅，卓卓挺疏附。","寒操凛清严，春阳播温煦。","八郡五十邑，讴歌出黎庶。","丈夫千载志，功业及时树。","肯堕尘俗流，甘同草木腐。","念子予故交，仳别岁已屡。","耳熟道路言，良慰心所慕。","玄冬十一月，风凄气寒冱。","朅来一晤对，告归复何遽。","因诗寄深衷，勉植后来誉。"]},{"t":"纪梦","f":"五言律诗","c":["昼眠梦故里，扶竹过西家。","邻翁爱敬客，延赏辛夷花。","一觞歌一曲，不觉红日斜。","觉来空怅惘，飘泊尚天涯。"]},{"t":"送夷行伴读赴西川","f":"五言古诗","c":["陈宗吾外家，俊彦森玉立。","永别昆山丞，梦寐恒在目。","令子敦厚资，诗书克嗣续。","温温秉谦恭，超超出尘俗。","暌违十七年，驱驰怜仆仆。","远邑分教席，亲藩陪讲读。","所乐事贤王，何尝厌微禄。","兹来忻慰藉，言别复匆促。","对酒念离合，后期安可卜。","于时积雨霁，仓庚鸣灌木。","西瞻万里桥，戚戚冲炎燠。","善保千金躯，用副意所属。"]},{"t":"送陈祭酒","f":"五言古诗","c":["邂逅不尽意，仳离难成欢。","况子我素交，俱属衰暮年。","夙游玉堂署，文彩金琅玕。","潇洒绝埃氛，磊落出肺肝。","托好三纪馀，贞松见岁寒。","升迁既遐处，怀思常漫漫。","北觐初盍簪，南顾遽回辕。","迢迢东海陬，鄞山青郁盘。","恻恻念桑梓，去去承明恩。","良会后靡期，晚节道攸惇。","黾勉各自珍，用副平生言。"]},{"t":"小瀛洲","f":"五言古诗","c":["晨下蓬莱宫，言访瀛洲君。","瀛洲咫尺地，东与东华邻。","结宇非崇高，潇洒净埃氛。","虽无弱水限，门绝尘俗人。","金葩间瑶草，阶戺扬清芬。","琼简兼赤书，充列太古文。","常时白玉堂，飘拂来清真。","相与共玄谭，造诣精入神。","盘出枣如瓜，森侍皆凤麟。","意超紫霞表，道匪玉局抡。","旷视六合内，逍遥任大钧。"]},{"t":"送张万中","f":"五言古诗","c":["十年祗奉命，四牡驰騑騑。","考最荣升擢，新恩出彤闱。","肃肃秋官署，迢迢赴南畿。","梅花岁寒姿，皎皎扬清辉。","君子比素节，钦哉念无违。"]},{"t":"题陈宪章巡检山水","f":"五言古诗","c":["山翠悦人心，清流堪洗耳。","浩浩名利途，扰扰何穷已。","画史有高怀，披图思千里。"]},{"t":"题梅寄蒋子夔","f":"五言律诗","c":["别卿四十年，思乡邈万里。","朝陪玉堂讲，暮醉金壶醴。","我有一株雪，持用赠君子。","置之三径中，清白宛相似。"]},{"t":"步过田家有述","f":"五言古诗","c":["联步营南门，偶寻野人庐。","庐舍类南土，缭垣树扶疏。","初柳扬青条，杏萼亦已舒。","皤皤舍下叟，迎客近门枢。","客问何乡人，理生今焉如。","跽答家徐州，始来十五馀。","生男皆壮夫，有孙亦跄趋。","大男荷戈殳，众男务菑畬。","公私昔少事，温饱常晏居。","老身就衰颓，官长日侵渔。","去年旱复潦，所穫瓶盎储。","何以备家食，指顾屋南隅。","园畦五六亩，果木百十株。","折李接桃根，为力勤亦劬。","三岁结李实，累累蕃且腴。","盈筐易斗粟，足给朝夕需。","言已意自得，闻之亦惭余。","机巧予所厌，所悯为利驱。","博树起后世，要非仁者徒。","两戕合一体，缠纠封皮肤。","虽能夺天造，本末固已殊。","物性循自然，古人岂其愚。","兴怀淳朴风，俛默增叹吁。"]},{"t":"题郭仲举雪景山水","f":"五言律诗","c":["乾坤播清气，冈原同一色。","启户得奇观，放舟浩有适。","从知山泽农，丰岁占三白。","何况牧守者，对此忘忻怿。"]},{"t":"早出安定门","f":"五言律诗","c":["结束出门行，鸡鸣夜过半。","长衢骤车马，明星烂河汉。","霜压紫貂轻，风掠微醺散。","自无匡直才，敢发驱驰叹。"]},{"t":"谒宣府庙学","f":"五言古诗","c":["下马趋黉宫，敬谒先圣师。","圣颜俨温穆，从祀森威仪。","簠簋备法制，堂庑何岿巍。","斋居豁明敞，富列书与诗。","童冠数十辈，济济咸肃祗。","俯仰动忻怿，亦复兴叹咨。","上谷秦所郡，逢掖时所讥。","寥寥千载后，振举昉自兹。","圣代崇文教，涵濡浃边陲。","伟哉谭公劳，焕耀无穷期。"]},{"t":"杨学士乃弟仲宜归建安以道中五景求诗赠之 其一 淮阴秋色","f":"五言古诗","c":["摇摇河上舟，迢迢远归客。","昨发潞水湄，今度清淮侧。","霜落秋树红，云连夕畴白。","矫首鸿雁群，联翩接飞翼。","念我玉堂人，亲爱渺南北。"]},{"t":"杨学士乃弟仲宜归建安以道中五景求诗赠之 其二 广陵夜雨","f":"五言古诗","c":["泊舟淮南渚，向昔闻清钟。","飒飒飞雨来，潇潇洒孤篷。","沿洄距几日，气序变寒冬。","望乡行有期，怀别坐无悰。","何时连枝会，将复彭城同。"]},{"t":"杨学士乃弟仲宜归建安以道中五景求诗赠之 其三 金山晓钟","f":"五言古诗","c":["扬舲越京口，中流睇金山。","昩旦闻禅钟，声出岛云间。","急应潮生渚，飘随月堕湾。","灵境富奇观，宁不怀跻攀。","逦迤瞻乡邑，浩荡棹歌还。"]},{"t":"杨学士乃弟仲宜归建安以道中五景求诗赠之 其四 鹅湖晴云","f":"五言古诗","c":["投策憩鹅湖，山水含清妍。","流云映华旭，粲粲五彩鲜。","云边有精舍，能不怀当年。","哲人崇丽泽，至道以昭宣。","归哉懋钻仰，覃思在遗编。"]},{"t":"杨学士乃弟仲宜归建安以道中五景求诗赠之 其五 闽岭停骖","f":"五言古诗","c":["辞家上京国，念我同气良。","会难别何易，归途阻且长。","行行及闽山，停骖见故乡。","故乡欣已即，北望仍徬徨。","伯也独远居，我怀焉能忘。"]},{"t":"送刘参政赴四川诗","f":"五言古诗","c":["璞玉不自衒，良工知求之。","君子安义命，知者宁自遗。","刘子敦朴资，敬恭励操守。","蚤暮勤职业，一志忠厚施。","郎署三十年，何尝较崇庳。","上荷圣主明，下承上官知。","一朝奋高翔，佐藩戒西驰。","平生所负挟，展效庶及时。","当宁念遐僻，宵旰恒孜孜。","旬宣天子德，惠泽洽茕嫠。","郡邑仗表率，贪渔待薅治。","用以光国命，亦副知己期。","霖雨夏初霁，高树鸣黄鹂。","缱绻杯酒间，念子当远离。","窃效仁者赠，殷勤歌此词。"]},{"t":"题竹送徐侍郎之南京户部并简黄少保","f":"五言古诗","c":["徐卿起毗陵，卓卓才行良。","遭时长郎署，特达清誉彰。","圣朝重守边，简贤赞军政。","爰陟少司马，肃肃将帝命。","甘州国西鄙，密比戎狄疆。","宛宛筹画运，煜煜威武扬。","扫荡边尘净，旋归觐丹闱。","天颜为悦霁，褒赉隆光辉。","当宁所孜孜，养民为首事。","龙虎壮南都，遂进司徒贰。","维时五月中，暑雨亘昏晨。","草草戒行李，匆匆发河津。","河水方茫洋，舟行疾于羽。","溯济乱淮流，超然越江浦。","念昔西行日，醉折杨柳枝。","如何复斯别，托意淇上猗。","兹植殊凡植，贞操挺桓桓。","耻效艳丽姿，傲兀冰霜寒。","元老东莱公，勋庸五朝旧。","我别才四旬，旷若三春久。","卿行烦致声，善保金玉躬。","上以翼圣明，下以宁瘝痌。"]},{"t":"送御史方懋德还新安诗","f":"五言古诗","c":["荆璞遇卞和，骐骥遇伯乐。","物遇固有时，识者亦不数。","方生禀令资，夙志励问学。","遭逢圣明世，贤科早超擢。","从事词林馆，简陟颂台幕。","言必循礼度，动不踰矩矱。","雍容侪辈间，俨然鸡群鹤。","一朝峨廌冠，莅事加秉恪。","持宪恕且公，守身澹以约。","中怀瑩澄澈，外不事表襮。","虽然知己希，俛仰靡愧怍。","顷出浙水西，沨沨誉声作。","旋归居无何，冠缨反丘壑。","风高秋气清，农田纷始穫。","林桂吐丹葩，吹香散寥廓。","执手送子行，感叹怀抱恶。","子当强仕年，余发久已皬。","后晤未有期，努力追先觉。"]},{"t":"题李绍检讨梅花","f":"五言古诗","c":["严冬朔风劲，草木俱凋瘁。","气机运无停，奄属贞元际。","寒梅动根荄，勃勃出生意。","鲜葩皎玉雪，芳馨播天地。","清素自厥赋，宁效夭桃媚。","君子禀至性，兹植夙所契。","幽斋坐相对，中怀净氛滓。","相忘主与宾，讴吟舒泄泄。","朅来玉堂馆，念之心弗寘。","谁写当座隅，悠然见高致。"]},{"t":"送萧仲南归吴江","f":"五言古诗","c":["蚤登西掖垣，累陟仪曹署。","祗命事四朝，年华未衰暮。","任贤属方隆，引疾遄南去。","自惟止足分，非惮淹留故。","于时八月末，翩翩戒行路。","丹林乱曙霞，黄华浥秋露。","踰淮绝大江，前望东吴树。","慰情接亲交，致恭展丘墓。","具区涵洲溆，修梁亘津渡。","散策恣逍遥，扬舲从逸豫。","却思京华日，岂复简书虑。","相好三十载，履行悉平素。","云胡当乖分，欲挽不可住。","矫首云飞鸿，聊写予所慕。"]},{"t":"送钟宏彰修撰归省兼致意彝训绍隆","f":"五言古诗","c":["荆山有奇璞，恒为庙堂珍。","英才履忠信，安得山泽沦。","钟子力学殖，行义修诸身。","遭逢昭明代，怀瑜谒紫宸。","遂登白玉堂，出入陪辅臣。","晨趋启沃筵，暮归思经纶。","鞠躬以效职，光华映青春。","忠孝并所惇，念我鹤发亲。","八年旷定省，梦寐心䞭䞭。","臣切乌鸟私，伏陛一再陈。","归宁丹诏许，拜荷圣主仁。","维时春冰泮，长河浩潾潾。","初发清潞漘，遄溯沽水津。","暄风芍药开，照耀斑衣新。","上堂献寿卮，慈颜和以忻。","次第省耆旧，亦复展戚姻。","欧乡有君子，昔者联朝绅。","超然谢尘鞅，还山侣逸民。","南北遥相望，有怀赋停云。","子归定相见，为予致慇勤。"]},{"t":"送林行简修撰归省","f":"五言古诗","c":["都城七月初，馀暑尚郁蒸。","南闽八千里，念子当远行。","岂不惮驰驱，庭闱激中情。","自违定省来，荏苒十周星。","幸沾近侍禄，况荷褒封荣。","家庆未躬拜，夙夜心怦怦。","仰承圣主仁，玉音赐归宁。","相送出词馆，严装戒晨征。","升堂及秋中，丹桂扬芳馨。","椿萱霭晴昼，兰蕙罗阶庭。","被服金绣袍，焕然五色明。","雕盘进甘脆，春酒献寿觥。","歆艳倾里闾，欢娱洽亲朋。","壶山为增秀，莆水为益清。","人生慕乐事，此乐难具称。","大哉君亲德，荡荡不可名。","忠孝必两尽，北归罔稽程。","春风杏花鲜，迟尔清潞亭。"]},{"t":"送杨宁郎中","f":"五言古诗","c":["杨生青云器，文彩辉白璧。","腰间龙泉剑，别来将远适。","吾闻禹徂征，舞干致苗格。","所以宣尼训，服远修文德。","好谋而有成，明明垂警饬。","如何材智士，宏议博古昔。","含忿忽远图，急功幸苟得。","宁论万里行，糗粮豫峙积。","汉廷所遣帅，孰是赵充国。","子行职赞襄，黾勉摅良画。","虽有斗酒饯，不能写胸臆。","临岐念素交，聊赠绕朝策。"]},{"t":"杏园雅集","f":"五言古诗","c":["鞠躬奉臣职，肃肃恒自旦。","朝下趋经帏，临夕出东观。","釐务日有常，黾勉在文翰。","衰龄皆沈疴，宁不怀泮奂。","仰惟宠禄隆，而敢厌羁绊。","兹晨属休沐，联镳越闾闬。","适我同志良，萧爽坐林馆。","维时天宇澄，青阳候过半。","好鸟鸣交交，芳卉罗绚烂。","朱弦一再弹，图帙亦娱玩。","肥甘列中筵，旨酒崇玉瓒。","主宾相和敬，济济圭璋粲。","清言发至义，连续如珠贯。","雅韵含宫商，高怀薄云汉。","合欢情所洽，辅仁道攸赞。","各期励乃修，庶用表桢干。"]},{"t":"送罗汝敬侍郎致仕南归","f":"五言古诗","c":["丈夫有壮志，力学希济时。","时来奋挺出，磊落见设施。","罗君吉阳彦，束发抱负奇。","明经起科第，玉署攻文词。","既持纂述笔，亦奏雅韵诗。","敷陈及时政，厥志将有为。","赐豸入霜台，肃肃纲纪司。","遂陟冬卿贰，将命南交驰。","绯袍明象笏，万里扬旌麾。","蛮方瞻使节，如旱甘雨垂。","手中五色诏，山海承华辉。","顿令阴曀区，豁然睹赫曦。","归来奏丹扆，龙颜霁融怡。","夙兴佐司空，立侍白玉墀。","朝回坐粉署，职务勤所思。","东南吴越邦，贡赋国所资。","奉旨督漕运，综理适攸宜。","于时严武卫，所重在西师。","四牡行騑騑，改途越邠岐。","兵彊自饷厚，笃意理畬菑。","豪横辍侵敚，游惰归耘耔。","河渠靡不溉，田芜靡不治。","雨旸属时若，仓庾崇如坻。","张掖暨灵武，周巡以诹咨。","所可利下人，计不遗毫丝。","矢心弗自顾，屡冒艰与危。","岁久罄劳瘁，上轸天恻慈。","明恩锡休致，超超赴南归。","老骥思旧枥，倦翼投故枝。","而况达士怀，物理鉴成亏。","亲交并祖饯，酣歌舞僛僛。","诘旦发潞河，薄暮经淮沂。","流莺沸驿路，飞花满弯埼。","溯江越彭蠡，挂席捷于飞。","船头见玉峡，霞彩煜英蕤。","振袂儒林坊，迓者陈杯匜。","展席老人亭，会者皆及耆。","一返安乐窝，永谢尘务羁。","顾余樗散质，衰疾加倍之。","乞身朝夕间，盍簪不远期。"]},{"t":"奉送参政方相公南归并托致意两司相公诚有私渎伏惟高明不以区区私家而废公法是见爱甚厚不敢忘大德也","f":"古风","c":["庐江山水清，从昔挺英杰。","周陶暨包马，先后奋功烈。","方君服诗书，夙志希往哲。","发轫自成均，簪缨俨朝列。","丛脞冬官务，旦暮劳?屑。","鞠躬殚臣职，肯用愆毫发。","群侪混污流，独秉清素节。","上荷当宁知，简升遂超越。","豫章佐方岳，雅度湖江阔。","咨诹得民隐，封章屡陈说。","荏苒三周星，报政谒金阙。","于余同朝旧，邂逅两相悦。","祖送崇文门，盛夏赫炎热。","道路念驱驰，况复当远别。","朝望东岱云，夕对秦淮月。","到官秋及中，丹桂香堪折。","置酒劳还归，芳筵集藩臬。","因声谢诸公，有渎恕老拙。","细人困穷櫩，所仗明仁活。","薰莸本异物，善恶在旌别。","大田植黍稷，必去螟螣?。","所以古仁人，除恶当果决。","致公而平施，岂为有势夺。","贱子固甚愚，公理敢私灭。","明达高贤心，幸不诮干聒。"]},{"t":"挽俞汉远诗","f":"五言古诗","c":["穷通各有命，匪人所克为。","俞生越乡彦，落落荆璞资。","一朝污苍蝇，弃置在涂泥。","良工屡回顾，昧者掩抑之。","俞生安义分，浩浩旷达怀。","庭阶绝尘杂，春草含碧滋。","对之襟宇融，点染出天机。","兴来写川岳，奋笔疾若飞。","以斯自陶适，贵富邈罔知。","自偶清者游，宁惭俗流疵。","如何逐化物，奄忽在今兹。","岂徒同侪憾，上有慈母悲。","幽室杳冥冥，怀旧书此词。"]},{"t":"题谢廷循作山水 其一","f":"古风","c":["结缨四十年，鸡鸣候朝谒。","晨趋白玉堂，暮下青?闼。","岂不勤寸心，曾何效毫发。","对此图中人，空惭头上雪。"]},{"t":"题谢廷循作山水 其二","f":"五言律诗","c":["秋日明锦树，秋水漾轻舻。","得鱼足充庖，亦足供酒壶。","青山常为邻，白鸥常为徒。","不识簪缨贵，焉知忧与虞。"]},{"t":"进善侄南归书此与之为别到家宾畿老弟亦可观也","f":"五言古诗","c":["秋高蓟北寒，念尔远离别。","老人七十馀，临别增悽切。","九年在北京，扶持多资尔。","尔有仲父望，惓惓心未已。","黄花浥白露，买舟发潞河。","江湖六千里，慎哉所经过。","到家冬已半，升堂拜仲父。","仲父喜侄来，深怜远行苦。","取酒慰骨肉，欢极情还悲。","子侄能几人，衰年频远离。","停杯有咨询，从知先老拙。","缱绻兄弟怀，殷勤尔能说。","十载隔南北，瞀聩兼沈痾。","无由归聚首，怅望其如何。","丘原展先垄，里闬省亲故。","除岁又新年，相期戒行路。","正月春冰解，桃杏鲜花繁。","老人注两目，望尔东南门。"]},{"t":"送万太守归严陵","f":"五言古诗","c":["圣人御宸极，宵衣念元元。","简贤付绥抚，申以奖励恩。","万子豫章彦，文科起高鶱。","十年峨豸冠，北面奉至尊。","绣衣艳丰采，白笔敷直言。","遂膺郡符寄，高盖拥彤幡。","严陵古睦州，山水清郁盘。","民淳风俗良，政务故不繁。","所尚简为治，教养心弥敦。","诗书振黉宫，耒耜勤田园。","东风蔼林垌，里胥无及门。","远迩诵贤守，声闻重玙璠。","念子吾故交，久别情郁烦。","兹来未几日，匆匆复南辕。","尝闻范与赵，为睦令绩存。","勖哉绍前修，以副平生言。"]},{"t":"题蒋婿重梅","f":"五言律诗","c":["北风振长林，黄叶萧萧下。","大地一清肃，梅花独潇洒。","纷看雪满枝，已觉春在野。","不有贞白心，谁知岁寒者。"]},{"t":"题汤节都指挥兰雪斋","f":"五言古诗","c":["汤侯心迹清，潇洒兰与雪。","惟兰媲芳馨，惟雪儗素洁。","读书负高志，武爵承世勋。","缓带杜元凯，雅歌祭将军。","分阃帅淮南，大藩佐江右。","兰雪凛清风，从初未尝有。","功并西山立，名与章江流。","金貂图麟阁，努力追前修。"]},{"t":"题欧阳广汤梅花","f":"五言古诗","c":["西昌欧阳生，明经起科目。","当宁敬刑罚，擢官秋卿属。","生抱忠厚资，况奉先训笃。","夜烛治官书，求生于死狱。","所听两造词，不厌四五覆。","明鉴靡遁情，被辜皆诚服。","门庭净若洗，襟怀皎于玉。","勉勉持廉虚，孜孜存洞属。","司寇上贤绩，爰进秩与禄。","特达腾声誉，恬澹寡嗜欲。","阶砌绝氛埃，不杂桃李俗。","雪色素梅花，先春烂盈瞩。","公馀坐相对，人物两清馥。"]},{"t":"题竹寄子谟同知","f":"五言古诗","c":["修筠生平陆，荆棘丛翳之。","荆棘承雪霜，摧折遽无遗。","修筠当岁寒，秀色终不移。","小人抱龌龊，志与君子违。","枘凿岂相入，萋斐腾诬辞。","溷夷而廉蹠，岂云天可欺。","天道匪茫昧，谗夫宁几时。","达士固贞节，安命诚奚疑。","臧氏不见尤，大贤有明规。","因成修筠咏，遥赠心所期。"]},{"t":"题梅花赠别朱与言","f":"五言古诗","c":["久别欣会合，将离怀缱绻。","何况夙心亲，家居接乡县。","念子五云秀，束发异群彦。","明经掇贤科，立志挺高狷。","温润玉无瑕，精劲金百鍊。","荆益奠大藩，白简佐司宪。","雍雍春阳度，肃肃秋霜面。","幽隐亟咨诹，贪浊严惩劝。","蜚英达宸聪，登崇自廷荐。","南京根本地，都台纪纲建。","秉诚敷献替，致明决议谳。","孤特昔张升，正贞今赵抃。","昨者考绩来，谒帝大明殿。","引疾却奏函，归展膺天眷。","夏初气清和，杨花竞飞燕。","岂无一斗酒，衰老违郊饯。","赠此玉梅花，聊慰情所恋。","期共保清素，岁暮长相见。"]},{"t":"送李员外致仕","f":"五言古诗","c":["荆玉韫在石，光润被林丘。","明珠潜九渊，清耀亦上浮。","君子未显达，芳誉难可廋。","挺特松柏心，耻与桃李侔。","一朝被采择，共睹升琳璆。","岂不贵且重，廊庙未及收。","邓林有奇才，匠石当知求。","丈夫高世节，焉能衒自售。","冉冉年岁驰，决意无淹留。","九河潦水净，行云淡油油。","零露浥丹桂，天香满道周。","飘然拂衣去，清风含九秋。"]},{"t":"中秋夕过澹斋戏柬","f":"五言律诗","c":["秋霄爱月华，徐步过东家。","主人喜客至，汲井瀹春茶。","青帘在邻馆，无钱不可赊。","何似陶彭泽，重阳把菊花。"]},{"t":"题竹送何士彦宣城训导并寄声袁太守","f":"五言古诗","c":["何君璞玉良，产自荆山中。","中怀缜而栗，外仪温且恭。","家学邃六义，允绍武冈公。","顷膺宣城聘，分教侯頖宫。","随牍谒金门，考艺趋九重。","诘朝奉除书，戒行遽匆匆。","经年忝交谊，祖送城之东。","何以赠仳别，聊托修竹丛。","此植挺特姿，千仞凌高空。","生际太平世，盛年须奋庸。","启迪贵知本，表率自饬躬。","况兹山水郡，昔贤多显融。","作兴谅匪难，行当律成功。","寄声袁太守，勉续黄与龚。","学教同振起，达材佐时雍。"]},{"t":"贝锦贻魏洪二侍郎","f":"五言古诗","c":["修竹本孤直，丛蒿掩翳之。","丛蒿岂不蕃，竹色青不移。","经星丽崇霄，阴雾蔽其辉。","终焉安得蔽，阴雾宁几时。","小人抱龌龊，君子素肯违。","青蝇与贝锦，盈庭腾诽辞。","平陆起波涛，岂云天可欺。","天道固包含，堲谗有往规。"]},{"t":"题梅花有赠","f":"五言律诗","c":["相见桃源下，相送长淮侧。","清谈夜向中，月照蓬窗白。","爱君好心事，况复真颜色。","聊赠玉梅花，交情矢无斁。"]},{"t":"采石夜泊与仰善之夔二侄话别","f":"五言古诗","c":["暮发金陵浦，前瞻采石矶。","渺渺江潮上，娟娟江月辉。","昔离忻乍合，明发念将违。","嘉卉岂乏观，三春艳芳菲。","不如柏与松，凌云起百围。","君子坚贞操，敬哉慎其微。"]},{"t":"鲁港","f":"五言律诗","c":["经旬坐舟中，局蹐心郁郁。","度江见青山，苍翠连延出。","好风从北来，持杯兴浩发。","宛转听棹讴，开蓬对明月。"]},{"t":"九华山","f":"五言古诗","c":["昔年李太白，吟咏秋浦清。","一览九峰秀，被之九华名。","夫容发菡萏，宛然天削成。","苍翠五千仞，日照云锦明。","上与泬寥通，下绝世俗情。","岂无冥栖者，鍊药希长生。","吾将往从之，何由谢尘缨。"]},{"t":"题竹寄卢邦臣","f":"五言古诗","c":["结交已三纪，玉署昔联官。","重以同江乡，词垣日聚欢。","升迁历中外，屡见岁华殚。","昨来谒京师，仍嗟会晤难。","共荣师席尊，犹忆客毡寒。","我行过匡南，怅望隔林峦。","久要意不尽，聊寄青琅玕。"]},{"t":"题梅与从孙翙","f":"五言古诗","c":["吾本清白宗，西昌四伯祀。","孝友惇家庭，诗书累科第。","炳然冰雪持，靡间处与仕。","先德既日远，后裔流或异。","我出四十年，归来重嗟喟。","诸孙森森中，静厚颇见翙。","言动弗佻轻，乡闾免讥议。","以兹恒近之，出入左右侍。","老人行有日，王程敢稽迟。","临别赠瑶华，老人有深意。","尔翙尚勉旃，力学无废坠。","旦暮事简册，躬行在仁义。","慎勿效流俗，龌龊苟污利。","明明待制公，清名传良吏。","子孙当敬念，庶不忝先世。"]},{"t":"题梅赠李学士","f":"五言古诗","c":["春皋麦欲黄，春城柳纷绿。","君子枉青顾，东来过茆屋。","邻瓮分浊醪，书窗剪明烛。","平生金兰交，一笑欢未足。","仆夫晨在门，跽言农事促。","执手送将归，飞花烂盈目。","何以赠兹植，孤芳挺贞淑。","高斋坐相对，岁晏人如玉。"]},{"t":"峡江留别汝敬侍郎","f":"五言古诗","c":["始夏积雨霁，浩浩沧江平。","故人念久别，又复怜远行。","慰我金洲馆，送我玉峡驿。","缪绸解晤言，缱绻重离析。","我出四十年，暂归席未暖。","何如君子怀，坦荡恣萧散。","远绝廛市聒，啸咏山水清。","庭无干渎人，坐有吾伊声。","赠子以瑶华，爱子心相类。","何日遂投簪，归来同晏岁。"]},{"t":"德州城下题竹寄刘仲兼","f":"五言古诗","c":["谬忝玉堂署，荏苒四十年。","始来当壮龄，不觉今皓颠。","水木有本源，谁能忘桑梓。","耿耿旦暮心，迢遥七千里。","仰承圣主仁，优诏赐暂归。","归来入闾巷，十室已九非。","素交皆下泉，存者才百一。","容颜变故常，聆音但彷佛。","岂乏后来者，貌同多异心。","鸱枭产凤窠，枳棘生桂林。","感我衰病怀，忧来向谁道。","前后左右人，雷同讥我耄。","贤哉吏部孙，夙昔吾所知。","居贞而履素，身老心不移。","念我久仳离，时来相慰藉。","言必合典则，义不苟取舍。","譬如群飞中，见此五色鸾。","又如丛荟中，见此青琅玕。","我行有程期，过别情缱绻。","别来未几日，忆子常在眼。","因风寄平安，托此修竹枝。","岁晏当来归，永结林下期。"]},{"t":"题竹寄艮侄","f":"五言古诗","c":["嗣宗与兄子，俱是竹林人。","远道念阿咸，平生心所亲。","去乡越三纪，还乡甫四旬。","契阔未及展，缱绻未获伸。","南风吹大江，官船发江滨。","尔从五云来，追饯螺川津。","相违甫旬浃，相思渺烟云。","上堂侍慈亲，致养供晨昏。","下堂饬诸子，力学追前闻。","先茔布坰野，能不怀深恩。","春秋雨露零，洒扫无惮勤。","爱尔刚直资，殷勤赠霜筠。","常固清贞节，用以谢尘氛。"]},{"t":"送王原之诗 其一","f":"五言古诗","c":["暮春时雨霁，嘉卉蔚纷敷。","交交黄鸟鸣，送子城东隅。","念兹万里别，执辔仍踌躇。","丈夫四海志，谁能倦驰驱。","所重在兼济，奉国效良图。","鞠躬罄丹诚，千春垂令誉。"]},{"t":"送王原之诗 其二","f":"五言古诗","c":["雄藩庾岭外，邈在南海堧。","山川旷阻隔，气候何其偏。","九龄与安道，自昔有名贤。","如何岩谷幽，犷俗比难镌。","仁化可革顽，文教可柔坚。","君子奉皇命，敬哉赞旬宣。"]},{"t":"送王原之诗 其三","f":"五言古诗","c":["青松起中林，棘蔓缠其枝。","棘蔓一朝萎，陨堕沦污泥。","松枝禀贞性，干云色不移。","志士履清洁，而遭谗慝訾。","天道讵可欺，谗者旋自隳。","临别举离觞，犹嗟贝锦诗。"]},{"t":"赠吴淳","f":"五言古诗","c":["大器必晚成，早达多幸致。","园柳迎春发，不待秋霜悴。","青青南山柏，百岁升云际。","明堂选栋梁，匠石来拟议。","凡古贤哲人，孰不怀用世。","不惜发轫迟，惟患道未至。","流俗竞苟得，终焉速颠踬。","卓哉漆雕生，明达见大意。","吴生海虞秀，诗礼家有自。","夙承大父训，稽古研经义。","昨奉贤能书，霜蹄偶一蹶。","隆然敬执友，于我频见诣。","温温昆玉资，颙颙负志气。","久别留台君，对此喜忘寐。","于时夏六月，积雨旦初霁。","宛宛黄鸟鸣，葵榴艳荣丽。","辞我将南旋，何以效赠遗。","厚积而迟发，周行骋良骥。","不闻任公钓，岂为目前计。","往哉加进修，云霄匪难跂。"]},{"t":"醉后调时彦","f":"五言古诗","c":["久坐倦烦燠，澄景回素商。","青冥下湛露，丹桂扬天香。","济济金闺彦，高会白玉堂。","和洽谐琴瑟，况复惜时光。","西斋有旨酒，何由共华觞。"]},{"t":"送少师杨公归建安","f":"五言古诗","c":["富贵还故乡，古今所欣快。","安知明达人，志出富贵外。","立身天地间，所重孝与忠。","君亲与天等，敬事道实同。","杨公南闽英，天禀挺卓特。","胸中书五车，笔下云五色。","三十登金门，射策奋高鶱。","天兴圣明主，躬被汪濊恩。","清密侍丹扆，煇煌裁紫诏。","玉署兼青坊，高步儒林表。","龙舆戒巡省，峨冠扈属车。","平戎万里道，櫜鞬行秘书。","黾勉三纪馀，服事四朝圣。","孤卿百僚上，高年备鸿庆。","思以上益君，思以下益民。","小心效臣职，亹亹摅恭勤。","恭勤副深注，声誉闻遐裔。","苍松老益坚，皓首心愈厉。","国事靡遑暇，亲恩讵能遗。","卅年别丘垄，寝食劳怀思。","不见白鹤峰，飞云恒在望。","手植垄头柏，应过十围壮。","岂惟羹墙觌，夜夜梦旋归。","水木有源本，谁能不歔欷。","仰荷明主仁，洞鉴中迫切。","玺书赐展省，龙光昭日月。","阳和二月中，御柳初含金。","凝冰泮九河，好鸟繁春音。","骊驹发都门，官僚皆祖饯。","渡济遂踰淮，载驰驶于箭。","暄风芍药时，候者集龙津。","矫首睇桑梓，含情兼戚忻。","追远致禋祀，怀旧访亲爱。","岁久多凋亡，相知几人在。","言归席未暖，岂不耽家居。","恭承玉旨重，尚敢淹踌躇。","庙谟待公陈，衮阙待公补。","丈夫君臣义，无为倦衰暮。","炎光变素颢，凉露下青芜。","预买中山醪，迓公东城隅。"]},{"t":"赠澹庵杨公展墓诗 其一","f":"五言古诗","c":["东风吹大河，河水日夜流。","严装逝将归，祖送河上头。","故乡六千里，迢遥望荆州。","违别岁年远，耿耿桑梓忧。","恭承当宁命，去去无淹留。","焉知同袍者，临分意绸缪。"]},{"t":"赠澹庵杨公展墓诗 其二","f":"五言古诗","c":["绸缪倏已分，望望犹伫跂。","岂无相交人，外同中乃异。","夫子夙所慕，爰结金兰契。","眷言资谅直，矧重仁与义。","荏苒四十年，气合恒一致。","皎皎松柏心，永矢在终岁。"]},{"t":"赠澹庵杨公展墓诗 其三","f":"五言古诗","c":["终岁之所怀，岂缘耄疾躬。","上有明主仁，德比三圣隆。","人生非草木，宁昧造化功。","出身儋禄爵，道存敬与忠。","夙秉高洁心，况闻贤达风。","焉能甘淟涊，委躯侪凡庸。"]},{"t":"赠澹庵杨公展墓诗 其四","f":"五言古诗","c":["凡庸谅猥鄙，贪惏复蟊■。","良农治田穑，稂莠在芟除。","倬彼仁贤士，怀负经世具。","皋陶陈知人，周公躬吐哺。","如何后来者，当道昩所务。","所以君子心，恻恻存永虑。"]},{"t":"赠澹庵杨公展墓诗 其五","f":"五言古诗","c":["永虑积中抱，临食每与嘅。","丈夫所立志，岂在富与贵。","不闻诸葛云，鞠躬以尽瘁。","上将益明德，下将绥四海。","夷险不可渝，頫仰庶无愧。","勿为久契阔，引领遥相待。"]},{"t":"喜稷将至复虑炎暑","f":"五言古诗","c":["衰年久别离，岂不怀欢聚。","书缄初未收，传闻遽乃屡。","炎热三伏辰，江湖六千路。","注目暮及朝，关情喜兼惧。","椟蓍时自把，灯花亦频顾。","露坐思徘徊，今夕知何处。","而况老者心，犹忆诸孙慕。"]},{"t":"送尚书魏公致仕还乡诗","f":"五言古诗","c":["江右国南服，贤才之林薮。","匡庐彭蠡间，清淑萃加厚。","英英魏文渊，人物星之斗。","明经在致用，一第咄嗟取。","峨廌入乌台，白简岁年久。","击邪奋无前，直枉宁肯后。","超跻副浙宪，声华耸冈阜。","简陟少秋官，式贰大司寇。","致鞫悬鉴明，析疑迎刃剖。","大梁困岁饥，方伯拜廷授。","悉心事旬宣，勠力苏稿朽。","归来掌邦禁，雍容帝左右。","既诘奸慝平，亦著武绩茂。","廉清一志坚，闻望六官首。","方兹切倚毗，云何慕畎亩。","惟皇悯疾疢，且重违耆耇。","锡之五色书，龙光焕户牖。","久行遂归止，福祉自天祐。","川开万里风，南帆驶于走。","云净九叠屏，烟消彭泽柳。","迎门集童稚，携觞聚邻叟。","欢庆溢乡闾，劳问洽亲旧。","超超天地外，此乐宁多有。","蹇予朴钝质，颓龄七旬九。","谬叨词林馆，固陋寡所偶。","责重力不任，兢兢虑灾咎。","所藉同乡邦，同心二三友。","有言相启发，有病相砭灸。","何君既离郡，魏公复分手。","念此增悲嘅，中怀杂纷糅。","岁晚应乞身，归程能待否。","市酒望湖亭，玉壶为君扣。"]},{"t":"寄友","f":"五言律诗","c":["同馆阔相别，相思春复秋。","十年见桑梓，适意正绸缪。","欢聚故邻曲，閒寻旧钓游。","宁知鹓凤侣，延望在瀛洲。"]},{"t":"武昌游道院 其一 幽字","f":"五言古诗","c":["仙馆俯崇冈，振衣一来游。","逍遥越城肆，窈窕经林丘。","谷口岩溜鸣，檐端云气浮。","适违阛阓喧，弥觉山水幽。","啼鸟迁高枝，悲猿振长楸。","物类爰有托，矧伊学道俦。","抱生贵知足，全形尚无求。","疗饥采紫芝，濯缨临素流。","愚生昩所处，静趣乃相侔。","援琴弄清弦，遂令佳赏酬。","王师事遐征，苦辛殊未休。","岂不怀宁处，违世安可谋。","我非学仙侣，怅然难久留。"]},{"t":"武昌游道院 其二 客字","f":"五言古诗","c":["通衢拥车骑，四术罗第宅。","仙宫郁云兴，邈与红尘隔。","交疏被朱绣，飞薨绚金碧。","竹树纷掩映，烟霞互辉赫。","爰有一羽人，于焉托其迹。","皓皓白玉姿，翩翩异人格。","我来扣松关，相与论玄默。","阶前孤鹤舞，林下啼猿寂。","于兹究典坟，信足探幽阒。","无田寄閒身，翘思羡乡国。","天台与赤城，聊可资游息。","丹丘有遗构，琼台多旧识。","胡为旷归期，久作周南客。"]},{"t":"送萧雅容主事考绩之行","f":"五言古诗","c":["中台切云汉，特达罗俊贤。","有美吾乡彦，白璧何娟娟。","温恭君子容，素尚金石坚。","高科出奋跃，石渠踰岁年。","爰擢司马属，声华日蜚鶱。","殷殷职务崇，戋戋简牍繁。","志存行靡渝，道明施罔愆。","考绩及兹晨，严装起翩翩。","维时届初夏，芳荣被郊原。","登舻指清济，扬舲循广川。","缅怀趋谒馀，周游凤阙前。","倘遇玉堂侣，因寄停云篇。"]},{"t":"罗进文妻周娟抱子安同赴水死","f":"五言古诗","c":["东方有綵凤，雄雌鸣相和。","诞生五色雏，巢在高树柯。","雄飞触虞缴，哀雌忧欲死。","哀雌忧欲死，衔子忽堕水。","雄来脱虞缴，空巢委高枝。","不见旧匹侣，孤悲无已时。","艰难两诀绝，苦哉谁为陈。","君看罗氏妇，万古同酸辛。"]},{"t":"送熊御史归南京","f":"五言律诗","c":["秋雨洒梧桐，西风动杨柳。","之子忆南京，开帆潞河口。","平生所相好，不在饯杯酒。","持赠岁寒枝，清操期坚久。"]},{"t":"送乐象乾赴湖广按察经历","f":"五言律诗","c":["河冻不可舟，日久寒威厉。","之子奉明恩，翩翩发征骑。","殷勤远别言，缱绻同乡意。","誓将冰雪心，用称风霜吏。"]},{"t":"瑞应玄兔诗","f":"七言古诗","c":["昊天大德仁兆民，简畀明圣为民君。","陛下神圣兼武文，允膺景命体至仁。","统视海宇如一身，刬剔匪类皇威振。","整饬纲纪百度新，霈德覃化流沄沄。","靡有远迩视平均，至和融凝天贶频。","厥来煜煜凤与麟，嘉禾秀麦咸荐芬。","异瑞比出西郊濆，不牙不角趺而踆。","彷佛逸出中山群，閒雅夐异东郭㕙。","匪緅匪缁色尚玄，为云为雾黭莫分。","含章韬彩柔且驯，尝有异质素与纁。","懿此玄瑞世绝闻，吐养万物东方神。","正秋之位收穫辰，矧乾正色应至尊。","稽德揆义良有因，丰稔之祥兹豫陈。","西人得之愕且忻，居以雕笼承锦茵。","踰岐涉汴趋枫宸，食之琼芝饮醴泉。","上林御苑游甡甡，圣仁之应自天申。","咏歌洋溢欢缙绅，陛下大知察迩言。","祗天保民永弗谖，四表一统熙和春，陛下洪福齐乾坤。"]},{"t":"瑞鸨诗","f":"七言古诗","c":["西过流沙沙浩浩，远来良马标瑞鸨。","凤膺虬首耳竹披，目如夹镜扬光辉。","天生瑞鸨毛质异，一片玄云被全体。","高题中点雪光明，四蹄皆白如瑶琼。","有时长鸣欲奋迅，捲地萧萧朔风振。","轩昂卓荦真龙驹，电迈云驰见奇骏。","圣人御天海宇清，泰阶六符明且平。","房星储精产灵物，为祥为异来神京。","葱河昆崙夜飞度，左右王良皆造父。","羁金络玉立彤墀，恩荣屡得重瞳顾。","自昔名马称骕骦，亦有紫燕兼飞黄。","当时万马皆莫及，敢与瑞鸨争腾骧。","玉陛朝回仙仗下，五色云车未骖驾。","瀛洲草绿风日和，顾影长嘶意潇洒。","国手含毫儗曹霸，瑞鸨龙姿今见画。","圣皇图治急才贤，审象亦闻求在野。","大明当天万物睹，会有夔龙帝时举。","箫韶九奏神人和，瑞鸨凤麟同率舞。"]},{"t":"蔡舍人挽诗","f":"七言古诗","c":["公昔骑骥登周行，握瑜怀瑾锵鸣珰。","凝神月朗髯戟张，温如绿野熙春阳。","劲如桧柏凌秋霜，后来藩府前经商。","在卑不屈高不亢，德厚禄微胡可量。","朔风一旦悽高堂，脱缨垂衰趋故乡。","幡然升云游帝傍，迢遥东海徒相望，望公忆公何时忘。"]},{"t":"奉送李丈人之宣城就养","f":"七言古诗","c":["若溪丈人过七十，两脸渥丹头雪白。","平原不改昔衣冠，鄂渚殊怜旧乡陌。","鄂渚西边花树阴，更来辟馆对青衿。","四时有钱解沽酒，几度逢书尽卖金。","大儿清韵亦如此，去年高举青云里。","锦袍白晰耀芳春，画幕红莲开绿水。","奉檄由来志养亲，只今得禄待严君。","行沾鹦鹉洲前雨，去指敬亭山畔云。","戎阃清时疏案牍，从此承颜欢不足。","东风低拂绮罗筵，春光回映斑斓服。","丈人宴乐谁与同，宣城山水嘉莫穷。","閒历旧游怀李白，还赋新诗似谢公。"]},{"t":"题虎溪萧氏卷子","f":"七言古诗","c":["连山飞来如虎蹲，溪水百折缘山根。","萦回陕旷忽异状，武陵未数桃花源。","大宅谁家住深窈，粉壁纱窗动晴晓。","门前稻麦连纷纷，千畦万畛翻青云。","云深截断樵牧路，车马城中那得闻。","四时高堂会宗族，旨酒肥羔间山蔌。","座中诗礼罗俊贤，楚楚威仪光佩服。","此地移家今几传，但闻朝代忘岁年。","南阶乔木昔人植，如今已上干青天。","从知遗安及孙子，岂独地灵能致此。","后来继者更不忘，更百千年胡可量。"]},{"t":"送邓存诚之襄阳","f":"七言古诗","c":["庾公南楼燕新乳，行子辞家春欲暮。","西岸杨花白似银，荡日摇风满江路。","江边汉水转逶迤，南堂鹤发正垂丝。","愿寻甘旨何愁远，欲去临分又复悲。","子有清才出同辈，见者纷纷谁不爱。","擅题绣句锦筵端，能画青山白云外。","我来投分已三春，握手摅情共讨论。","即今相送缘鹦渚，明日相思间鹿门。","鹿门芳草芊绵碧，尚有庞公昔时宅。","池上山翁去不还，江皋神女无遗迹。","经过吊古易徘徊，且莫迟留定蚤来。","红芳照映莱衣舞，好及榴花五月开。"]},{"t":"马孝子诗","f":"七言古诗","c":["孤坟四尺荒郊里，野草苍烟带寒水。","子孙有在在他州，生者无知知者死。","昔时未死语丁宁，定将还葬附先茔。","来寻墓隧失南北，梦见言之真有灵。","上冢无人将百岁，启圹犹存旧题记。","出离客土返乡山，父已申情子终事。","由来至孝动皇天，解发系鞍皆昔传。","文章辉煌久不灭，知尔垂名俱万年。"]},{"t":"送杨翥孝廉归吴中","f":"七言古诗","c":["城中七月犹炎暑，城下归人趁行侣。","十年为客忆东吴，一日辞亲发南楚。","楚江吴江路几多，扬帆处处尽经过。","琵琶亭边有明月，长干门前闻踏歌。","千里苏台在行目，忽度枫桥到乡曲。","顾瞻桑梓杂悲欢，纷引亲朋问寒燠。","吴中归日嘉可游，知君未得久淹留。","晚岁还为越乡叹，他州重有倚门愁。"]},{"t":"别刘宗诚","f":"七言古诗","c":["湖南十月新雁飞，白苇渐高黄橘稀。","兰舟去远复回首，唯见星沙连杳微。","前年作官临海峤，海畔家家说司徼。","一日衔哀返故丘，三春忽尽不迟留。","遥趋北阙朝明主，暂下南楼谢旧游。","此地贤郎独为客，把卷看云几朝夕。","江边迎喜拜亲闱，馆下含情别师席。","临岐牵手重依依，可怜恩义两难违。","春来有使题芳札，想为殷勤报鹤矶。"]},{"t":"题萧德颢扇","f":"七言律诗","c":["石台盘盘浸溪曲，五月溪光帖寒玉。","千桃万竹夹成云，奕奕高门荫深绿。","主人凉袂纤絺裁，越罗小扇挥炎埃。","南薰院中听宝瑟，临清楼上引金罍。"]},{"t":"朱泽民云山障子为萧德颢题","f":"七言古诗","c":["昔闻朱侯写山水，一幅争投百金价。","至顺今来七十年，却在桃源看图画。","生绡八尺垂中堂，群山叠出开青苍。","前峰如屏锦霞烂，后岭岧峣插天半。","春风啼鸟浑欲闻，石磴盘盘屡回转。","双松如龙千尺强，几年偃蹇山之阳。","松根古道向何处，策马担簦去无数。","别看丹翠出层楼，云影浓遮入无路。","云遮雾滃深复深，信有隐者藏中林。","高怀远致不可即，空望微茫劳我心。","当时此景知何地，雁荡兰亭岂相似。","自是天机妙入神，位置从容见精意。","朱侯朱侯追郑老，笔势词华共妍好。","此图三绝交辉煌，千载人间视为宝。"]},{"t":"送李昌祺","f":"七言古诗","c":["盛年读书擢科第，共睹词华艳云绮。","翰林高步逐英贤，东阁潜心效文史。","身违定省五六年，梦绕庭闱二千里。","昨夜摅情达丹扆，特许归宁承玉旨。","谢恩初辞凤阙前，买船遽向龙江涘。","江天未明早潮上，况复连朝北风驶。","二月初旬应到家，冠带升堂亲为喜。","囊中尽倒官俸钱，郡市西头致滫瀡。","叙言契阔洽朋知，趋走牵携欢稚子。","爱亲敬君事所重，况乃皇恩厚无比。","还应回首顾王程，螺渚行舻须早理。"]},{"t":"送彭仲宜归荆州","f":"七言古诗","c":["四月都城风日好，远客违家思芳草。","秦淮河畔问南船，重译楼前出长道。","道傍送者皆缙绅，玉堂编修情独亲。","此来相看轻千里，此会相欢能几晨。","晨发无由执杯酒，折赠空持白门柳。","临分缱绻复申言，已去苍茫尚回首。","芦笋纷纷接浦桥，鲥鱼队队逐兰桡。","吹笛晚邀池口月，扬帆晴带海门潮。","归到绣林应夏五，鹧鸪啼歇榴花吐。","家庆趋承白发欢，云光回粲斑衣舞。","还携双鲤放江湄，江水朝宗日夜驰。","都将乡邑平安报，稍解京华契阔思。"]},{"t":"题小画赠曾贯还西昌兼致勉励之意","f":"七言律诗","c":["夫容绿水光鲜妍，芳春秀质何娟娟。","六年虎观驰彩笔，十月鸥江回画船。","醉写银瓶送将别，秋菊垂花纷可撷。","请看石上青琅玕，早晚凌云挺高节。"]},{"t":"题杨学士藏陈所翁四龙图","f":"七言古诗","c":["近代画龙谁第一，举世所重闽陈容。","秘府人家屡曾见，叶公虽古难独工。","此图四龙妙无敌，变化奇态才数尺。","乾坤黯黪閟云雾，风雷奔驱裂崖石。","腾身并出青冥上，盘拿夭矫皆相向。","神光睒矆如剑铓，倒捲江潮起银浪。","陈翁画意与谁同，爱龙所重泽物功。","炎飙六月撼原野，矫首滂沱如画中。"]},{"t":"题兰石寄王善学","f":"七言古诗","c":["清源先生乡达尊，昔以通家拜函丈。","别来四十有三年，至今仪形劳梦想。","当时令子朴且真，与我相欢亦长往。","有孙今传祖父业，授徒假馆双江上。","不随尘俗混驱驰，但以诗书待咨访。","潜心篆籀积岁年，往往挥毫作题榜。","我虽闻之未识面，已为名家动歆赏。","玉堂侍读重同宗，万里暌违心怏怏。","此图寄赠有微意，我为题诗叙畴曩。","清贞比德兰与石，珍重幽人在林莽。"]},{"t":"题开封黄璿太守感螺卷","f":"七言古诗","c":["叙州黄氏有孝孙，冬月大母病热烦。","渴心苦思螺疗疾，田枯溪涩那可得。","孝孙求螺急仓皇，手足冻皴肤肉僵。","是时孝孙年一纪，至诚感神神祐只。","探穴得螺四十多，煮液一进蠲沉痾。","姜诗王祥古孝子，孙之孝感见黄氏。","黄氏子孙贤且贵，作诗为告观风使。"]},{"t":"题画赠陈本深太守考绩复任","f":"七言古诗","c":["吉州太守明州彦，三十朝绅赞邦宪。","诗书法律重老成，冰雪操持万人见。","先帝孜孜念幽侧，廷中亲选二千石。","天语丁宁寄抚绥，五采龙章光烜赫。","螺冈鹭州开郡府，九邑茕嫠需召父。","陈侯下车兴隐恻，育稿濡枯作甘雨。","豺狼遁迹犬息吠，胥史无奸狱无滞。","桑麻蔼蔼连郊坰，弦诵洋洋起阛阓。","大江之西十三郡，陈侯特达腾声闻。","骅骝宁久双毂淹，雕鹗须当九霄奋。","我昔京华接邻屋，幸甚乡邦得贤牧。","入奏重闻功绩最，劳问还嗟别离速。","冰霜严凝岁华暮，五马双旌复南去。","苍筤树石贞澹意，特赠邦侯表清素。"]},{"t":"题汤都司东皋草堂","f":"七言律诗","c":["君侯襟度清于玉，草堂长忆东皋曲。","堂中高韵列诗书，堂下幽香绕兰菊。","雄藩此日任干城，玉帐牙旗常夙兴。","我家亦有东皋屋，春雨蒲田归未能。"]},{"t":"题宋知州瞻彼南山图诗","f":"七言古诗","c":["北方之山恒山尊，上出河汉凌星辰。","常时出云作霖雨，滋育万物乘阳春。","东风浩荡清川泻，川上人家住潇洒。","内黄旧是故殷城，临水观山足公暇。","此邦名与山齐高，古来为政多贤劳。","高山景仰攀逸驾，母负青年志气豪。"]},{"t":"萧启御史赴山东佥宪以何澄所画云山求题","f":"古风","c":["宜阳太守多公暇，肆笔云山出潇洒。","层峰叠翠凌苍空，英英玉气浮鸿濛。","缥缈瀰漫浑无迹，妙逼房山高克恭。","山乎云乎定何处，谁结茅屋倚深树。","岂无独抱千载心，玩水看山适朝暮。","柏台御史抚此图，忆得龙泉江上住。","岫幌岩扉意不忘，十载京华未归去。","秪今骢马复东行，马上看山向齐鲁。","君不见泰岱之云起肤寸，常向人间作霖雨。"]},{"t":"题卫以嘉藏盛子昭画","f":"七言古诗","c":["盛生家住吴山下，前代风流多见画。","此图三尺更清奇，野水疏林澹潇洒。","风平云净霁景鲜，玻瓈倒映水中天。","鉴湖洞庭不可辨，隔浦山光落钓船。","荡舟者谁定曾识，渺渺相望似相觅。","寻常一曲沧浪歌，醉倚汀沙白鸥侧。","鸱夷羊裘世久无，浮世虚名安足沽。","放怀纵意任所适，何处烟波无钓徒。"]},{"t":"题崔氏重庆堂","f":"七言古诗","c":["昌黎县中山水清，自昔挺特生贤英。","上究羲农至周孔，攘辟老佛大道明。","我敬其人想其处，身縻禄仕无由去。","崔生近日起昌黎，邂逅相逢谈所慕。","生昔泮水来游歌，明经三十登贤科。","铁冠霜简入乌府，岁久政誉传流多。","天官奏绩天颜悦，五采祥云腾凤敕。","堂上双亲共拜恩，更有重闱岁将百。","重庆堂中春昼长，寿酒日进青瑶觞。","四亲三百又馀岁，白发苍颜皆乐康。","家庆融融由世德，兰玉森森荫松柏。","剩取诗书遗后来，岂无继续昌黎伯。"]},{"t":"送栾瑄太守复任大同","f":"七言古诗","c":["东莱栾卿粹如玉，皦皦操持恭且肃。","秋官郎署居十年，盛有声名京国传。","九重圣人御明堂，简擢贤俊安边方。","栾卿出拜二千石，郡中如得龚与黄。","下车正属民凋疗，起仆濡焦不知怠。","帅阃崇严兵戍殷，徵需琐琐无昏晨。","鞠躬勤事靡缺失，上下不间称其人。","三年报政朝天阙，奏最重临促明发。","丈夫有志遇明时，宝剑精光肯沉没。","霜风十月红树凋，五花征马鸣萧萧。","自古公卿出贤守，黄鹄终当凌九霄。"]},{"t":"题康干竹石","f":"七言古诗","c":["康甥孟贞纯且质，家住珠林小江侧。","兄也霜台峨廌冠，贞也躬田食其力。","好山好水当衡门，违远城市无嚣喧。","身閒力学嗣尔祖，不见他家贤子孙。","有心如石不可转，苍筤有日干霄汉。","邂逅为尔题画图，七十老翁言匪迂。"]},{"t":"题竹与余存忠驿丞","f":"七言律诗","c":["家住芝山番水上，官作杨村驿亭长。","金门使者五色书，击鼓亭前开画舫。","朅来敬我同江乡，我亦报之双筼筜。","成阴结实须有日，会下昆丘青凤凰。"]},{"t":"新桥驿阻大风","f":"七言古诗","c":["南风吹河吼怒涛，河上飞沙千仞高。","临流十步不得济，北瞻阊阖心烦劳。","自春不雨田无麦，谷田焦枯亦龟坼。","密云四合扫复开，谁叩天阍讼风伯。","农家束手徒嗟吟，爱民自是天之心。","愿收巽二敕屏翳，普千万里均甘霖。"]},{"t":"黄氏寿谖堂诗","f":"七言古诗","c":["琴江黄氏好兄弟，五十年前屡过之。","今来都门遇令子，卓志能承书与诗。","二老风流已长往，独侍慈颜在堂上。","鹤发萧萧寿且康，甘旨晨昏足丰养。","堂下忘忧多树谖，晴日暄风花正繁。","斑衣婉愉献春酒，慈竹娟娟森子孙。","除官分教延平去，便道升堂荣拜母。","人生得禄贵及亲，板舆还奉官中住。","将行索我谖堂诗，为子喜色生两眉。","子家二老吾所重，诗罢能忘故旧思。"]},{"t":"送周敬常诗","f":"七言古诗","c":["去年奉敕还江南，东风千里迎归骖。","西昌城西访真境，正值碧桃三月三。","襜襜威仪森鹤氅，却忆仙翁隔蓬阆。","霜鬓酡颜戴鍊师，白玉觞行紫霞酿。","矞云垂彩拂檐端，芝草琅玕绕画栏。","欢言未竟登车去，天涯长忆三珠树。","戴师弟子来日边，清颜皎皎夫容鲜。","问师经年安健好，闭户日咏黄庭篇。","我有高怀在江海，为报而师扫氛霭。","黄茅冈畔会重寻，白鹤峰头定相待。"]},{"t":"送金少卿祭扫南归","f":"七言古诗","c":["去年奉敕我还乡，今年奉敕卿还乡。","我违乡国四十载，卿违乡国三十霜。","仕者还乡总□□，卿逢故旧当尽情，明年春风朝北京。"]},{"t":"题金亮伯梅花","f":"七言律诗","c":["雪崖先生好孙子，森森庭前玉树枝。","柏台御史冰霜笔，写赠梅花真似之。","朔风十月江南道，万里乡园到应早。","手持书卷傍花阴，更厉平生岁寒操。"]},{"t":"题范启东所藏俞汉远云山图","f":"七言古诗","c":["会稽俞生富天趣，笔法传得高房山。","白云滉瀁生空谷，危峰飞出青冥间。","灌木青葱俯溪曲，溪面沉沉湛寒玉。","超然肥遁者谁子，深结茅斋擅幽独。","人间嘉景何处无，何必远求衡与庐。","白头尘累苦羁绊，我念林栖增郁纡。","吁嗟俞生此遗迹，俞范昔年交莫逆。","知是看图重故人，不但溪光与山色。"]},{"t":"题严御史恭梅边读易图","f":"七言古诗","c":["钱塘湖畔山无数，湖上古梅千万树。","之人结屋傍湖山，坐起常在梅花间。","微风吹林动香雪，水色山光总清绝。","手持一卷太古编，周孔所示皆微言。","推辞通意必造玄。","二仪分判自太极，寻源更溯庖牺前。","潜心虚怀知几年，时来不得安考槃。","绣衣白简峨廌冠，风采六月冰霜寒。","辰阳西上开省署，又捧除书向西去。","天香满袖出金銮，带作边方九春雨。","边尘不动边人安，展图还忆钱塘看。","从知玩易有真趣，燕寝凝香清昼閒。"]},{"t":"赠伯时外弟","f":"七言古诗","c":["海榴作花梅雨息，令弟五月来京国。","玉堂晚归初见之，豁然令我舒胸臆。","传杯剪烛两迟迟，还因亲爱动欢悲。","清姿秀质今在眼，严父慈亲空永思。","又促明朝理归舫，家在西城柳溪上。","高楼深馆绝尘纷，努力诗书振馀响。"]},{"t":"赠纪指挥画卷","f":"七言古诗","c":["曲栏梧桐花正吐，万玉萧萧写青雨。","珊瑚红树拂天风，六月人间不知暑。","琵琶收弦寂无语，梦里随云度银渚。","侍者如花握金缕，倚绣娉婷对容与。","意远神清皆俣俣。","人间閒乐等神仙，更诧蓬山在何许。"]},{"t":"题费同知松树障子","f":"七言古诗","c":["当代画松谁最精，王绂卓迪俱驰声。","两生以来鲜继者，凤池周璿新得名。","此图笔有千钧力，全幅剡藤开泼墨。","双株奋起如双虬，直气森森势千尺。","樛枝屈铁蟠穹苍，劲节磥砢鳞甲张。","长风飒飒动满座，六月清昼高堂凉。","吉安别驾好奇古，对此宛然岩壑趣。","伏苓琥珀焉足期，坚操终怀共迟暮。","别驾别驾临安彦，浙东山东宦游遍。","四明徂徕千岁植，所历山林屡尝见。","大材之成由化工，自古匠输希得逢。","明堂清庙选梁柱，何限空老深山中。"]},{"t":"小山书屋","f":"七言古诗","c":["文江之东小山麓，旧有高人读书屋。","绕屋森森松作林，松阴行吟松下读。","平生读彻书五车，鹿鸣宴饯来京华。","御前奏对三千字，五彩椽笔登銮坡。","兰台石渠富纂述，献赋陈诗诵功德。","日给珍羞饱大官，宫锦无时出褒锡。","黑发去乡今二毛，近侍光华更四朝。","人生倦勤思暂逸，小山南望心摇摇。","鹏搏九万六月息，丹桂花香别京国。","旧屋还归小山下，邺侯多书仍满架。","门前冠盖来纷纷，少日同学何人存。","青松拂云尽成盖，慈竹青青蕃子孙。","邻叟时过话耕稼，亦有诜诜执经者。","红笺锦轴金绣段，更觉文章动高价。","老夫垂白念乡关，早晚天恩应赐閒。","长风万里溯玉峡，舣棹文江访小山。"]},{"t":"题蒋主善梅","f":"七言古诗","c":["蒋氏传家秉清白，住在金陵大江侧。","三径风流松菊存，别有梅花春意繁。","开轩正对花林下，襟抱冲和兴潇洒。","香浮丹鼎雪融初，影转琴床月明夜。","自承徵诏戴朝冠，朝朝拜谒趋金銮。","故乡迢遥隔烟水，十年梦绕梅花寒。","閒暇从容咏清句，节操从知凛贞素。","嗟余同是爱梅人，何时归赏江南春。"]},{"t":"题丘氏平原十景图","f":"古风","c":["昔年过东昌，游平原，望玉山。","万松夹径鸣珊珊，翠屏叠出青冥閒。","石豅瀑布飞秋雨，彷佛龙吟井江暮。","东陂流泉清我心，尽日徘徊不能去。","仙人夜半西极来，□云灿烂红莲开。","邀我□□万寿之宫里，酌以沆瀣青瑶杯。","隆山鸣钟促天曙，欢言未竟东西去。","扁舟来往不复寻，江中遥望空云岑。","湖塘月色今何似，岁晏黄原飞雪深。","之子幽居有清赏，展卷那堪动遐想。","到家还过仰山祠，刻我题诗青石上。"]},{"t":"题康氏临清楼","f":"古风","c":["文溪似秋浦，窈窕湛寒玉。","天净波平一鉴开，倒影金华千仞绿。","人家多住溪东西，飞栋辉煌接华屋。","疏槐杨柳荫当门，翠荇红蕖悦心目。","康氏楼居更萧爽，雕栏百尺凌云上。","仙姥峰高望欲齐，状元洲近平如掌。","词翁酒客屡招寻，吹竹弹丝共欢赏。","风物清华入吟啸，阛阓喧嚣断轮鞅。","忆昔总角初常游溪之涯，拆竿坐石堪垂钓，临水提筐逢浣纱。","朅来忽复四十载，漂泊不归双鬓华。","天涯往往闻逸兴，邂逅题诗徒自嗟。","岂不闻宋朝曾孝子，三子科名相继起。","连篇文采动公卿，文溪之名自兹始。","今人何必非古人，珍重贻谋在经史。","他年若绾银黄来，仰视高楼耀闾里。"]},{"t":"题杨学士藏子昂画刺虎图","f":"古风","c":["妇牵车，夫推毂。","车中儿，貌如玉。","全家远戍不辞苦，日暮途荒车下宿。","山凄凄，林谡谡。","飒然阴飙度，夫身罹虎毒。","妇奋遂虎曳虎足，呼儿抽刀斮虎腹。","倒虎肝肠夫来复，终然妇愤不可平，夫命无由百身赎。","有司匦函上行义，华表辉煌旌白屋，千年异事太史录。","人生富贵鸟过目，谁有姓名光汗竹。","吴兴妙绝诗与画，况复巴西详委曲。","昔贤汲汲翼名教，竞为表彰励民俗。","建安学士古人心，珍袭此图常韫椟。","偶然出示嘅古道，援笔题诗愧貂续。"]},{"t":"题画送欧阳广哲","f":"古风","c":["往昔送子时，春冰洞地明。","两京遂间阔，相望摇心旌。","今年子重来，几日复南征。","念子道路难，激我离别情。","是时碧梧亭亭汎露彩，翠竹瑟瑟含秋声。","踌蹰何以赠远行。","子负挺特姿，潇洒梧竹清。","岂不闻峄阳之产中琴瑟，嶰谷之材谐律吕。","人生有志当大用，况遇明时事尧禹。","常保坚贞德，不随流俗迁。","不见溪头磐石重如山，时解出云腾九天。"]},{"t":"陈氏贞寿堂","f":"古风","c":["北堂融融春昼长，锦树错落含春香。","堂中老母今八十，鹤发如丝身乐康。","母昔初嫁时，玉环自矜惜。","殷勤奉君子，顾盼怜贞白。","一从守空闺，皎皎冰雪色。","下有□男儿，力学慕古人。","季儿生来不识父，今年六十霜鬓新。","明经射策选上第，金马玉堂高致身。","大箱俸钱奉慈母，愿母十年百年寿。","清朝南极老人星，正照华筵酌春酒。","五福重好德，德厚福亦同。","伟哉贞寿堂，乡里高其风。","人之贞节乃大义，烱如白日光洞地。","方今圣朝务表励，作歌欲告观风使。"]},{"t":"题璚林积雪图送张宇初真人归龙虎山","f":"古风","c":["北风十日雪，大地气严凝。","江湖千里断行迹，温泉火井皆为冰。","盘盘龙虎山，岧峣出尘表。","势并匡庐近斗牛，叠巘重崖隔深窕。","向来积雪纷不消，千树万树凝琼瑶。","素鸾缟鹤下飞舞，空中缥缈天香飘。","上清真人夐清绝，吐气如虹貌如雪。","袖有三华宝篆文，腰佩千年苍水玦。","常招赤松为雨师，曾游东海邀安期。","手执玄枢斡元化，一扫氛翳回春熙。","玉皇端拱通明殿，紫凤云章频召见。","天京十二楼五城，亲接群仙奉华宴。","五彩春霞导金节，还向山中咽飞雪。","明年北上翔双凫，更采灵芝谒丹阙。"]},{"t":"赠族孙褒","f":"古风","c":["万里江南来，还归江南去。","丈夫得名何必早，大器之成在迟暮。","岂不见深山长谷松柏林，阅历风霜年岁深。","明堂清庙选梁柱，匠石奔走来相寻。","我家住西昌，于今四百载。","诗书门庭冰玉操，炯炯光华著先代。","人生出处自有时，立心但与前人期。","还家力学谢尘俗，六翮排云应未迟。"]},{"t":"题竹石送陈有戒重使关西","f":"古风","c":["骢马碧玉蹄，饰之黄金勒。","振鬣嘶青云，汗沟流赤色。","乌台使君廌作冠，绣衣虬髯冰雪颜。","大庭亲授五色诏，西出绥抚踰秦关。","长安城中旌节驻，富有欢谣动衢路。","豺狼遁迹犬生氂，不断和风送甘澍。","安内攘外职当为，秋高九月行边陲。","绥延宁夏濒绝漠，城高兵坚马尽肥。","归朝奏章累十纸，仰契天心天为喜。","为臣体国宁顾家，玺书重下歌皇华。","缙绅祖送都门道，雪后飞埃净于扫。","丈夫事业在盛年，莫遣麒麟画衰老。","不见渭川竹，可以栽汗青。","不见华峰石，可以镌姓名。","功名到手不可让，相期千载传芳声。"]},{"t":"题竹送欧阳哲佥宪之汴","f":"古风","c":["岂不见奉大祭，荐用璧与琮。","岂不见作广厦，选裁梁与柱。","国家致理仗才贤，教养成之在黉序。","圣皇宵衣急文治，大廷敕举观风使。","玉玺盘龙五色书，亲遣巡行严教事。","六一宗家有远孙，清才素行如玙璠。","手提文印之官去，马头南望河南路。","河洛天地中，崧高峻极天。","降生周家申与甫，近代亦有文富贤。","两程夫子明邹鲁，道统上承千载传。","山川佳气朝朝有灵秀，钟人物何曾间前后。","子行所历善教施，本末兼举真良师。","后来功业有奋起，看子誉名同远垂。","临岐何以赠别离，清风潇洒丹凤枝。","天寒岁晏凛冰操，持用慰我遥相思。"]},{"t":"题张氏秋月轩","f":"古风","c":["开轩对秋月，皎若白玉盘。","光辉上下澈无际，洞然八极天地宽。","山河微茫影可识，拂云桂树常团团。","太虚无尘万籁净，玉绳璀璨金波寒。","是时秋气澄，俯仰皆奇观。","灵台湛湛俗不染，坐与月色相盘桓。","念昔少小家西陲，爱此明月同襟期。","黔南蓟北行欲老，惟有明月长相随。","月轮万古行乾坤，年年常阅秋与春。","平生双眼炯如月，阅人富贵兼贱贫。","谁其胸中如月明，烦卿一阅世上人。"]},{"t":"惜别行送朱存礼致仕归鄱阳","f":"楚辞体","c":["御柳含春绿初遍，紫燕黄鹂满芳甸。","晓日承恩拜九重，银鞍白马骄嘶风。","我出送之城之东，惜别且驻无匆匆。","忆昔携书汉江涘，邂逅论心托交义。","折梅载酒春共游，烧烛联诗夜无寐。","卿才卓荦不可羁，雄词健笔皆如飞。","积金堆玉岂暇顾，登山临水常忘归。","南飞云鹄北飞雁，渺渺天涯两分散。","即今三十馀六年，前日红颜皆白颠。","五岭炎方桂林好，忠辅贤王已身老。","功成名遂天所全，七十归来世看宝。","嗟余樗散质，□□□□清。","未有涓尘效禆益，虚叨宠禄孤圣明。","望卿去兮惭感并。","倾离尊，饯远道。","重是平生故，何由尽怀抱。","官河三月波溶溶，片片飞落桃花红。","九华匡庐翠未了，芝山秀出鄱湖东。","武山南在芝山上，解绂他年定相访。"]},{"t":"赠眼医张生张侍郎求赠","f":"古风","c":["人身具两目，精气咸注之。","偶然神光困邪沴，虽有四体将焉为。","丹砂空青疗盲晦，异效往往闻良医。","今之皋陶少司寇，治刑求生劬以疲。","况复婴忧目为眚，邂逅拙工乖所施。","双目等河注，愁坐俛两眉。","圜扉纷纷叩苍昊，瘉我公者龙树谁。","河南张生亦超越，胸藏奇能口不伐。","小施寸七捷于神，尽扫浮云见明月。"]},{"t":"题竹送罗文衡湖广宪使","f":"古风","c":["骢马青玉蹄，银鞍碧丝缰。","振鬣忽长鸣，矫矫飞腾骧。","朝发都畿暮荆襄，千里歘忽流电光。","绣衣骑马天上郎，颜如玉洁髯云张。","十年北面侍明主，铁冠白简横秋霜。","九重惠南土，辍此殿陛良。","命之持斧振宪纲。","澄清洞庭及湘汉，尽洗阴翳开春阳。","青霄白日上雕鹗，及时功业须奋扬。","我有绝俗意，赠之翠筼筜。","贞姿不柔亦不刚，中虚外直操有常。","隆冬冰雪凛严厉，长与庭柏同苍苍。","交映黄鹄山下之高堂。","清风永昼含琅玕，坐使民物咸阜康。"]},{"t":"苍龙歌","f":"古风","c":["天马生西域，神骏挺卓特。","双目如镜悬方瞳，紫焰红光烱相射。","长身昂长八尺龙，腰袅飞黄奇骨同。","青丝潇梢尾窣地，滃滃雾鬣连风鬃。","四足高蹄削踣铁，满身犹被天山雪。","逸气超遥时一鸣，但觉飒爽长风生。","从知天驷宵降精，晶荧下澈寒泓澄。","灵物翕合嘉祥兴。","戎夷得之纷骇目，顾叹荒遐安得畜。","中华圣人今帝尧，锦鞯玉勒东来朝。","芒芒沙碛，渺渺西极。","籋云奔电，千里一息。","登瑶京，上赤墀。","下邦小臣陈奏词，年来泰和洽边陲。","乾坤灵瑞世罕见，端自皇仁所致之。","公卿拜舞效嵩祝，陛下万寿日月齐。","周文德盛?騜至，汉武役志劳贰师。","朝廷服远在有道，圣化真与周同规。","画史挥毫纪盛事，敬作歌颂垂耀无穷期。"]},{"t":"晏太守重庆堂诗","f":"古风","c":["家居重庆郡，堂奉重庆欢。","堂中二亲大母母，白发如银身健康。","大母行年九十三，母也今年七十五。","姑慈妇孝天锡寿，旨酒在樽殽在俎。","蹁跹五綵服，绕膝戏孙曾。","森森暖翠慈竹茂，烂烂云锦谖草荣。","象简绯袍日趋拜，门拥彤幡燕皂盖。","邦侯为政儗龚黄，能致高年总心快。","故家元住大江西，元献声华北斗齐。","公侯子孙必复始，封诰行看照闾里。"]},{"t":"送彭勖御史南还","f":"古风","c":["骢马铁连钱，锦鞍珊瑚鞭。","东风都门道，旦发何翩翩。","霜台御史贤且文，治平中丞之远孙。","贤孙白日上雕鹗，东广南闽持教铎。","九重召还赐廌冠，敕付条章振文学。","南畿一百二十二郡县，俊秀如林玉雕琢。","世重贤才比麟凤，杞梓楩楠作梁栋。","圣人垂拱坐明堂，昕夕需贤升显用。","臣子受命当驱驰，必有勋绩裨清时。","山川何地无奇产，要知成器须良师。","苏湖安定不易得，萧艾芳兰岂无择。","与君同乡郡，分手重离情。","丈夫得志贵行道，当令海内扬鸿名。"]},{"t":"龙马乐歌九首 其一","f":"古风","c":["龙马出，自西极。","应天驷，跃方泽。","具龙仪，皦玉色。","嶷山立，备纯德。"]},{"t":"龙马乐歌九首 其二","f":"古风","c":["龙马出，神骏发。","镜夹瞳，玉喷沬。","追迅风，凝皓雪。","灵瑞臻，耀天阙。"]},{"t":"龙马乐歌九首 其三","f":"古风","c":["龙马出，掩骥群。","捷流电，籋矞云。","入玉阙，登金门。","灵自天，瑞圣君。"]},{"t":"龙马乐歌九首 其四","f":"古风","c":["龙马出，象应乾。","旦历秦，晡憩燕。","秣珠票，饮琼泉。","偕祥麟，徵太平。"]},{"t":"龙马乐歌九首 其五","f":"古风","c":["圣人作，万物睹。","神之骏，出西夏。","日千里，汗流赭。","宜乘御，扬神武。"]},{"t":"龙马乐歌九首 其六","f":"古风","c":["身矫矫，首昂昂。","虬之跃，龙之骧。","迈兹白，越飞黄。","协乾符，表文明。"]},{"t":"龙马乐歌九首 其七","f":"古风","c":["乾之方，星之精。","萃厥灵，挺异生。","维圣仁，来嘉祯。","维圣仁，寿万龄。"]},{"t":"龙马乐歌九首 其八","f":"古风","c":["龙马出，应皇德。","皇圣仁，覆万国。","天祐圣，贞符锡。","圣子孙，千万亿。"]},{"t":"龙马乐歌九首 其九","f":"古风","c":["龙马出，昭圣世。","光八表，和四裔。","奉宗社，格天地。","隆家邦，永文治。"]},{"t":"七夕吟寄夏四秀才","f":"五言古诗","c":["迢迢天汉流，粲粲织女明。","牵牛出其东，何不长合并。","伊昔承嘉遇，欢言尽平生。","宴乐未及终，回驾趣修程。","斯须忽不见，安得伸中情。","别长会日促，暌违岁复盈。","终日秉机杼，七襄不能成。","思欲展嬿婉，谁乐各㷀㷀。","同心而离居，叹息涕泪零。"]},{"t":"题古木竹石","f":"七言绝句","c":["珊瑚出水天漠漠，翡翠横波月将落。","隔林罢歌湘浦词，片云还向君山归。"]},{"t":"商妇词","f":"七言绝句","c":["贩茶近在青山侧，贩珠远求沧海浔。","全家衣食需多少，渺渺鲸波愁妾心。"]},{"t":"征妇词","f":"七言绝句","c":["他家荡子滞吴门，妾家夫婿戍皋兰。","共是闺中别离泪，妾愁辛苦又愁寒。"]},{"t":"短歌行","f":"楚辞体","c":["青天高高行白日，忽西倾兮又东出。","人生百年能几时，身计未成早已衰。","子孙成行各长大，手种苍松尽成盖。","来日苦短去日长，何不饮酒居华堂。","流光催人急复急，八十龙钟悔无及。"]},{"t":"铜雀妓","f":"五言律诗","c":["高台凝望处，西陵落照边。","昼日自歌舞，秋风咽管弦。","恩随漳水远，恨与邺云连。","惟有昏鸦集，时时近墓田。"]},{"t":"隔谷歌","f":"古风","c":["严风凋角弓，钲鼓鸣不止。","弟兄但隔谷，咫尺异生死。","丈夫报国甘苦辛，此时顾恩宁顾身。","讵知兄弟左右手，临难方为行路人。","升高聊一望，力尽心未已。","仰天呼兄兄不来，壮发冲冠直如指。","生为同气亲，死作异乡尘。","自矜雄豪重仁义，谁保艰难不相弃。","岂不见南山桂树同根生，百年雨露同枯荣。","又不见桓山之鸟同巢哺，欲去回翔不能征。","人生有情乃若此，天地惨寂终难平。","呜呼宾客满堂歌伐木，且请停杯歌隔谷。"]},{"t":"伯阳新辟斗室有诗见示用韵奉和 其一","f":"五言律诗","c":["新来居斗室，还自惜分阴。","尽日唯探易，閒时不罢琴。","檐昏钟响度，窗皎月华侵。","及此宜无事，犹含白雪吟。"]},{"t":"伯阳新辟斗室有诗见示用韵奉和 其二","f":"五言律诗","c":["閒居植兰芷，绕屋似沅江。","香露浮侵席，光风动满窗。","调琴元少并，摛赋更无双。","来此皆心醉，何须倒玉缸。"]},{"t":"湘阴县","f":"五言律诗","c":["湖上湘阴县，清幽俗不殊。","江连三里郭，市有数廛车。","地产为陶器，生涯寄网鱼。","家家养黄犊，谁肯负王租。"]},{"t":"送刘季友游钱唐","f":"五言律诗","c":["风送浙江船，东游属妙年。","湖山围锦绣，楼阁艳神仙。","柳暗苏堤曲，湖平伍庙前。","此邦耆旧在，还去问先贤。"]},{"t":"题刘氏交友卷","f":"五言律诗","c":["谷鸟啭嘤嘤，兴馀伐木情。","当时论友道，何处托心盟。","杯酒身相许，千金意自轻。","还闻江海上，今世有刘生。"]},{"t":"钟长史木讷斋","f":"五言律诗","c":["贤王重师教，长史足官荣。","清绝斋居里，新题木讷名。","近仁由德性，好古见仪刑。","一世誇轻捷，君当表后生。"]},{"t":"示弼侄","f":"五言律诗","c":["有客传吾侄，攻书过昔时。","谦和自德性，俯仰备容仪。","观水求溟渤，登车慎路岐。","从兹万里去，努力在操持。"]},{"t":"寄仲亨兄","f":"五言律诗","c":["常记分携处，维舟鸥阁矶。","亲交情不浅，迟暮苦相违。","白发花前径，青编竹下扉。","东城同辈少，料得往还稀。"]},{"t":"永丰陈处士挽诗","f":"五言律诗","c":["世出颍川系，乡邻六一居。","声名崇孝友，术业富诗书。","禄养承昭代，神游渺太虚。","兵曹怀永痛，血涕满衣裾。"]},{"t":"乐平屈氏母挽诗","f":"五言律诗","c":["夙有闺闱德，兼闻母道贤。","教孙成令器，享禄及高年。","谖草凋堂砌，松枝蔼墓阡。","文章堪不朽，表石见新镌。"]},{"t":"送邓宗经","f":"五言律诗","c":["久别时相忆，重来又解携。","帝方求隐逸，子竟返幽栖。","海树连吴地，云山入剡溪。","草堂何处在，莫遣世人迷。"]},{"t":"送王孟坚脩撰南归 其一","f":"五言律诗","c":["东壁图书府，清华映上台。","朝廷重文治，近侍总英才。","独罢金门直，遥辞玉署回。","平生王逸少，临别恨难裁。"]},{"t":"送王孟坚脩撰南归 其二","f":"五言律诗","c":["从来欢聚意，不似别情深。","爱子清如玉，论交已断金。","云霄开逸翮，山水称閒心。","浩荡乾坤大，相思何处寻。"]},{"t":"送雷诚智延平知府 其一","f":"五言律诗","c":["五马引双旌，青春发帝京。","分符为郡远，衣锦过乡荣。","祠庙先贤近，弦歌旧俗清。","秪应劳抚字，莫遣愧阳城。"]},{"t":"送雷诚智延平知府 其二","f":"五言律诗","c":["平日丰城旧，新年感慨多。","于君来往熟，奈此别离何。","柳色迷官驿，莺声傍御河。","旗亭芳酒散，不忍对骊歌。"]},{"t":"过滁州马上口号寄陈廷器","f":"五言律诗","c":["一入滁阳郡，桑阴翳广原。","纷纷纳禾稼，渺渺散鸡豚。","清夜无鸣柝，长途不闭门。","皆云贤守化，深荷圣朝恩。"]},{"t":"江浦县遇曾于皋","f":"五言律诗","c":["忽遇髫年旧，惟看语笑真。","清诗仍满袖，华发已盈巾。","桑梓二千里，萍逢四十春。","金溪吟啸地，因话共伤神。"]},{"t":"送周存诚州判致仕归清江 其一","f":"五言律诗","c":["秘馆连西掖，编摩集众英。","有才皆荐达，垂老足恩荣。","旷野心情熟，浮云去就轻。","明朝对玉笥，山水有馀清。"]},{"t":"送周存诚州判致仕归清江 其二","f":"五言律诗","c":["往岁同趋召，兹晨独送归。","夕阳南浦棹，春雨北山薇。","鱼鸟欣相得，衣冠烂有辉。","无才缨绊繫，徒此惜相违。"]},{"t":"送万伴读","f":"五言律诗","c":["初日照明光，春风合殿香。","忽看辞圣上，远去从贤王。","画楫移江浦，青山向洛阳。","经游多雅咏，相寄莫相忘。"]},{"t":"愉老堂","f":"五言律诗","c":["此翁衡岳下，白发烱秋霜。","八帙过三岁，诸孙蔼一堂。","不辞愉老日，还注济生方。","玉屑能扶寿，朝朝进满觞。"]},{"t":"萧处士挽诗","f":"五言律诗","c":["识达前人重，诗书后学师。","艰危存大义，衰老见明时。","溪舫秋云冷，泉台月夜悲。","惟馀名姓在，光映史臣词。"]},{"t":"朝房待命","f":"五言律诗","c":["正是临危处，深知负罪频。","廷臣皆执法，天子尚垂仁。","紫殿红云近，金河瑞彩新。","恩波今浩荡，终忆借枯鳞。"]},{"t":"孔经历挽诗 其一","f":"五言律诗","c":["礼乐唐尧日，诗书孔氏门。","登朝荣象笏，列署切薇垣。","卓荦怀千载，凄凉遽九原。","英灵知不化，未报圣明恩。"]},{"t":"孔经历挽诗 其二","f":"五言律诗","c":["识尔趋庭际，芳年玉树高。","谦和自天性，文雅出时髦。","旧好过从断，深情梦寐劳。","他乡新冢在，松柏晚萧骚。"]},{"t":"潘太守挽诗 其一","f":"五言律诗","c":["昔在临川郡，行春皂盖荣。","桑麻千里绿，弦诵万家声。","意澹终辞禄，才高岂尚名。","至今城下水，人比使君清。"]},{"t":"潘太守挽诗 其二","f":"五言律诗","c":["郡城华盖下，岁月忽如驰。","五裤歌犹在，双旌去不归。","清名史氏传，遗爱后人思。","有子从仁政，传家愿不违。"]},{"t":"题竹赠廖子谟南归","f":"五言律诗","c":["芳春宰花县，久别不胜思。","比似湘川上，清风玉一枝。","五年重晤聚，几月又分岐。","临发无持赠，聊歌卫武诗。"]},{"t":"赠建平弟","f":"五言律诗","c":["七十年兄弟，于今二老存。","脩途余未息，古道尔能惇。","后辈纷纷出，颓风靡靡奔。","晨星与霜木，相对两忘言。"]},{"t":"金幼孝挽诗","f":"五言律诗","c":["英年兼令质，秋水映娟娟。","才行诸昆重，诗书累代传。","一朝随化物，万事逐浮烟。","听话临终意，何人不怆然。"]},{"t":"送沈生归省","f":"五言律诗","c":["旧与休文好，曾闻小阮贤。","行冲蓟门雨，归问浙江船。","璞玉须成器，韶光剧逝川。","承欢有馀暇，努力事遗编。"]},{"t":"贻程夏二中书","f":"五言律诗","c":["扈从巡畿甸，官曹喜接联。","屡颁丹凤诏，须属彩毫宣。","画障分云树，琴声泻涧泉。","春行有佳兴，相伴共悠然。"]},{"t":"陪驾观猎","f":"五言律诗","c":["武士拥周遭，前驱导彩旄。","径危兼水石，野阔盛蓬蒿。","鹰犬纷飞跃，狐狸莫遁逃。","老臣方寸切，上念圣躬劳。"]},{"t":"从度居庸高峰","f":"五言律诗","c":["玉辇巡边徼，师还此伐鼗。","紫云随警跸，红日动旌旄。","地险关城壮，天清眺望高。","非才叨侍从，无补只徒劳。"]},{"t":"陈豫中八十寿诗","f":"五言律诗","c":["翛然无俗累，恬澹乐丘园。","名誉三山重，春秋八帙尊。","安居非药里，荣养自词垣。","五月瞻南极，华星正对门。"]},{"t":"送李主事赴常州通判","f":"五言律诗","c":["初出郎官署，先传府倅贤。","天恩谢北阙，春水载南船。","郡已无三害，民皆有一廛。","年丰公事简，瀹茗试山泉。"]},{"t":"漳州曾氏望云卷","f":"五言律诗","c":["县城当桂岭，清昼白云垂。","重到曾游处，偏增罔极悲。","神游杳霭外，目断苍茫涯。","五色衣裳在，承欢讵可期。"]},{"t":"寄李德言","f":"五言律诗","c":["高州李别驾，未老倦缨簪。","金石论坚操，冰霜烱素心。","闭门吟对竹，延月坐鸣琴。","半幅幽贞趣，赠君文水浔。"]},{"t":"挽彭子信","f":"五言律诗","c":["昔者雩阳郡，黉宫重得师。","合宗推孝友，后进仰威仪。","丘垄松楸合，春秋雨露滋。","诸郎惇永慕，尤废蓼莪诗。"]},{"t":"送梁叔车","f":"五言律诗","c":["离怀不可尽，且复共芳筵。","卞玉终须献，韦经故有传。","河山行处好，云树望中妍。","归路诗千首，因风寄百篇。"]},{"t":"送王希积泰和训导","f":"五言律诗","c":["严亲进官日，并命出彤闱。","拜后多人羡，光前似子稀。","离情常北恋，行色又南归。","想侍慈颜处，簪缨胜舞衣。"]},{"t":"赠梁叔庄泰和训导","f":"五言律诗","c":["相违十载过，相聚半年深。","论旧何曾尽，伤离复在今。","黉宫双白璧，儒行万黄金。","莫道匆匆别，无穷迟好音。"]},{"t":"答黄宗载见寄","f":"五言律诗","c":["又是三年别，新来百感增。","薰莸安可问，枘凿苦难胜。","白发落垂尽，青山归未能。","故人赠佳句，拟报玉壶冰。"]},{"t":"赠仰善主事南归","f":"五言律诗","c":["重逢方适愿，几日又分岐。","瑚琏真堪宝，云霄自有期。","从知万人见，肯受一尘缁。","无限岁寒意，题诗赠别离。"]},{"t":"送苏伴读","f":"五言律诗","c":["德义儒林重，诗书学海翻。","校雠辞秘閤，辅导向王门。","晓铎行车远，春筵赐醴温。","须明藩屏意，天子万年尊。"]},{"t":"送刘凝节归永丰时有兴国训导之聘","f":"五言律诗","c":["都城一相见，文采动华年。","家与先贤近，经从太史传。","三春还旧邑，百里望平川。","应复匆匆去，诸生候讲筵。"]},{"t":"题敏求斋","f":"五言律诗","c":["閒居积文史，不厌五车多。","白玉须成器，流光惜逝波。","阶前春草遍，林下午风和。","还有同门者，时来共切磋。"]},{"t":"送王霖知县赴阆乡","f":"五言律诗","c":["千里河南北，忧勤切至尊。","兵年兼旱潦，民命急朝昏。","身倚诗书贵，功将抚字论。","无忘当宁意，一一在覃恩。"]},{"t":"刘指挥勤学斋","f":"五言律诗","c":["时平无警柝，公暇事遗编。","解剑闻春诵，烧灯减夜眠。","竹深幽院里，花暗素房前。","事业由多学，相期及盛年。"]},{"t":"送王性存亲迎后归省","f":"五言律诗","c":["朝辞金阙去，千里赴庭闱。","锦绣行春昼，何须五色衣。","岸花明画障，江月净琴徽。","一路弹新调，鸳鸯不独飞。"]},{"t":"张生水竹居","f":"五言律诗","c":["傍水连高竹，门前似渭川。","雨晴看净练，风爽听清弦。","为酒兼烧笋，持竿屡取鲜。","还资奉甘旨，非但乐林泉。"]},{"t":"戴诚问挽诗","f":"五言律诗","c":["□携如昨日，寤寐想平生。","操比寒松劲，心同秋水清。","诗书安素业，身世避浮荣。","冢树西风里，凄凉故旧情。"]},{"t":"王好信挽诗","f":"五言律诗","c":["来往经萧峡，舟人指富溪。","林藏君子宅，行慕古人齐。","锦诰恩封在，青山垄树迷。","郎曹未终养，愁绝夜乌啼。"]},{"t":"焦主簿挽诗 其一","f":"五言律诗","c":["郿县岐山侧，萍乡楚水浔。","扶持有神力，惠爱在人心。","往事岁年远，高坟松柏深。","自天鸾诰出，奕奕宠光临。"]},{"t":"焦主簿挽诗 其二","f":"五言律诗","c":["悯物由天性，能官不假威。","重为百里佐，遽作九原归。","瑟瑟悲风迥，荒荒零露稀。","惟馀凤毛在，五彩翙双飞。"]},{"t":"寄王宗豫 其一","f":"五言律诗","c":["相别岁频改，相思心未降。","故家沧海国，高卧白云窗。","适趣琴三叠，随游鹤一双。","东来抱锦轴，喜见笔如杠。"]},{"t":"寄王宗豫 其二","f":"五言律诗","c":["内阁承宣地，朝朝侍柘袍。","七人亡过半，二老去能高。","蹇劣仍踰分，驱驰岂任劳。","怀归归未得，鬓雪不胜搔。"]},{"t":"胡敏御史致事出梅求题余于胡有旧故赋二诗识别 其一","f":"五言律诗","c":["秘馆曾同事，流年四十馀。","花封有嘉政，柏府重清誉。","致事新恩命，怀乡旧隐居。","湖塘三百亩，已免贡菱租。"]},{"t":"胡敏御史致事出梅求题余于胡有旧故赋二诗识别 其二","f":"五言律诗","c":["五月出都畿，东风暑雨微。","济河新涨发，淮浦片帆归。","朋旧惊霜鬓，乡闾重绣衣。","岁寒怡老处，梅雪共清辉。"]},{"t":"寄杨仲举长史","f":"五言律诗","c":["谁不恋丘园，兼之鬓雪繁。","几人知道义，用世必玙璠。","遂有贤王奏，㳟闻圣主恩。","平生钦慕意，喜极欲飞鶱。"]},{"t":"题竹送陈中员外","f":"五言律诗","c":["文雅陈员外，三年一度来。","春风对玉树，浩荡好怀开。","北阙晴云下，南河彩鹢催。","一枝淇澳赠，临别意徘徊。"]},{"t":"曹侍郎乃母挽诗","f":"五言律诗","c":["曹家少司寇，至孝奉慈闱。","衣贮亲缝线，堂县旧断机。","喜崇二品养，遽动九原归。","天恩下鸾诰，千岁有光辉。"]},{"t":"题竹送乐象乾并寄声陈述","f":"五言律诗","c":["京国三年别，驱驰越汉皋。","冰霜纲纪地，旦暮简书劳。","入觐还相慰，能官见所操。","临分赠淇玉，更为谢同袍。"]},{"t":"题王郎中九峰归趣图","f":"五言律诗","c":["老别郎中署，人看昼绣荣。","家临三泖近，门对九峰清。","邻叟来分席，家僮从阅耕。","君恩重山岳，一饭未忘情。"]},{"t":"赠萧斯易御史巡按苏常诸郡","f":"五言律诗","c":["绣斧辞京国，三吴候画船。","丹枫秋水岸，白雁早霜天。","悯物须蠲蠹，观风在礼贤。","功名仗才俊，努力及英年。"]},{"t":"题陈宪山水","f":"五言律诗","c":["何卿妙写趣，陈宪问题诗。","野水瀰溪涧，春云压树枝。","群山如对客，独学更求师。","待我归来日，披图共酒卮。"]},{"t":"送凌副使归省先茔","f":"五言律诗","c":["先茔赐归省，腊尽出都门。","雁影行途远，梅花到日繁。","春风待旌旆，昼锦入乡园。","情事从容毕，不忘当宁恩。"]},{"t":"题梅月轩","f":"五言律诗","c":["清轩夕不扃，梅映月娉婷。","移影上琴荐，浮香著砚屏。","一尘元不染，万籁寂无听。","即此坐閒暇，澹然心志宁。"]},{"t":"次韵答胡若思宾客 其一","f":"五言律诗","c":["东璧蓬山顶，曾同侍玉皇。","碧霄龙早逝，沧海鹤高翔。","案有庄生论，门临孺子坊。","游心邈千载，尘虑已都忘。"]},{"t":"次韵答胡若思宾客 其二","f":"五言律诗","c":["自别颐庵叟，星行十二周。","天恩无寸补，世故有多忧。","老骥力垂尽，长途驰未休。","中怀何处写，聊用寄南州。"]},{"t":"重过鹞儿岭伤用道长史","f":"五言律诗","c":["荒山千万叠，茅舍頫河滨。","岂意清明世，翻为憔悴人。","命穷身不返，志屈道还伸。","为洒重来泪，平生心所亲。"]},{"t":"送王希德归西昌","f":"五言律诗","c":["三岁在京畿，春生五色衣。","殷勤承父教，归去候慈闱。","丹桂浮香露，黄花粲夕晖。","人生具庆少，养志在无违。"]},{"t":"送用仪之官莱芜","f":"五言律诗","c":["百里铜章贵，英年宠命新。","侵星辞阙下，带雨发河津。","岁歉须宽恤，民劳急拊循。","前贤有尘甑，垂誉已千春。"]},{"t":"送梁叔脩秀才归西昌","f":"五言律诗","c":["洒落王詹事，人今第一流。","相看佳子婿，冰柱照琳璆。","□□留经岁，家山到及秋。","文章千载事，珍重满归舟。"]},{"t":"御史陈谷乃父挽诗","f":"五言律诗","c":["行己严三畏，传家守一经。","选才成大典，膺召谒彤庭。","草露俄乘化，松茔已勒铭。","平生知不泯，有子嗣芳声。"]},{"t":"杨孟潜挽诗","f":"五言律诗","c":["芳春奋科目，令器比玙璠。","致孝亲闱乐，传经学者尊。","一朝随化物，群行载词垣。","光华知不泯，况有凤毛鶱。"]},{"t":"送叔纲表侄","f":"五言律诗","c":["失怙怜渠早，提携赖母慈。","门庭已秩秩，兄弟亦怡怡。","观国欣初见，怀乡又远离。","外家多子侄，期尔读书诗。"]},{"t":"送叶锡尹姑苏","f":"五言律诗","c":["买得吴中棹，遥辞潞渚滨。","重为花县宰，旧是玉堂人。","霜菊看将晚，寒梅到及春。","从知锦绣地，不肯厌清贫。"]},{"t":"题梅赠郭太守还镇江","f":"五言律诗","c":["每忆春坊旧，寥寥叹晓星。","明时用郭伋，五马驻江城。","庠序弦歌盛，桑麻雨露荣。","梅花一片月，长伴使君清。"]},{"t":"暇日承观上人惠访","f":"五言律诗","c":["参襌周十刹，随地演三车。","水月心常静，烟霞趣已赊。","胡杨皆故族，孔李更通家。","一访空斋里，玄谭过日斜。"]},{"t":"题画赠梁婿叔济","f":"五言律诗","c":["萧散藩翰幕，时平净俗埃。","河流带近郭，树色蔼高斋。","简牍常时阅，诗篇暇日裁。","閒情对图画，亦胜倒金罍。"]},{"t":"题任生山水","f":"五言律诗","c":["溪亭夏无暑，不假碧荷筒。","垂柳轩窗外，青山眺望中。","水漾玻瓈色，香生菡萏风。","借问坐谭者，还知无极翁。"]},{"t":"送王志浩","f":"五言律诗","c":["凤历纪王正，新春别帝京。","行观具区薮，先过阖闾城。","圣主方兴教，诸生喜受经。","他年看奏最，崇秩有光荣。"]},{"t":"挽冯知府","f":"五言律诗","c":["凄断南来讣，相违始十旬。","晤言犹昨日，死别惜芳春。","冰檗声仍在，龚黄志未伸。","平生乡郡意，回首一沾巾。"]},{"t":"题竹送刘子钦","f":"五言律诗","c":["故人刘子政，契阔十馀年。","此日重携手，相看各白颠。","交情方恋恋，别袂遽翩翩。","聊赠岁寒意，琅玕雪共妍。"]},{"t":"题福建吴布政竹石图","f":"五言律诗","c":["家住鄞江上，作藩闽海涯。","旬宣有馀暇，公退足委蛇。","竹秉岁寒操，石含大古姿。","高斋坐相对，无忘武公诗。"]},{"t":"送陈斌副使之陜西兼柬陈宪使于副使","f":"五言律诗","c":["骢马向咸阳，东风驿路长。","渭川清映月，秦树早迎霜。","风采人心快，贪渔吏弊亡。","陈于荣并命，冰玉共高堂。"]},{"t":"寄吏部尚书黄宗载","f":"五言律诗","c":["白首记同年，怀君静胜仙。","冰霜老北地，云树渺南天。","近俗伤多薄，无言忍独贤。","离情何所似，春柳遽飞绵。"]},{"t":"忠孝堂","f":"五言律诗","c":["桓桓忠孝行，藉甚说冯君。","有子传先德，能官续武勋。","高堂名教事，巨笔史臣文。","四海皆臣子，芳声独远闻。"]},{"t":"题刘纲知县梅花","f":"五言律诗","c":["作令更三邑，兹行向海邦。","民风尚文学，士俗亦惇庞。","须得穷櫩好，还令蠹吏降。","梅花玉雪意，常若对寒窗。"]},{"t":"题萧氏林泉居","f":"五言律诗","c":["壮游两京路，邂逅多写真。","一随化物尽，屡见流年新。","承家有令子，志墓托名人。","寂寞水南畔，依然旧松筠。"]},{"t":"送陈虬延安知府","f":"五言律诗","c":["天子急民瘼，廷臣领郡章。","平生怀玉雪，此去播春阳。","雕鹗云霄迥，骅骝道路长。","试看韩与范，遗迹在边方。"]},{"t":"次韵答颐庵 其一","f":"五言律诗","c":["十年去京国，高卧西山陲。","天趣常自得，他人安足知。","竹馆鸣琴处，河塘坐钓时。","劳心尘事者，何日赴幽期。"]},{"t":"次韵答颐庵 其二","f":"五言律诗","c":["与君离别后，两度历边陲。","年老衰容换，风寒病骨知。","有心存济物，何术可匡时。","矫首西江上，归帆会有期。"]},{"t":"送刘知县赴莆田","f":"五言律诗","c":["远邑需良宰，贤科起茂才。","九天辞玉阙，一骑发金台。","济北初舒柳，江南未过梅。","能官崇富教，莫遣吏民猜。"]},{"t":"题刘氏奉亲堂","f":"五言律诗","c":["双亲各垂白，至乐奉安居。","养有日官禄，教传星象书。","椿阴满庭户，谖草映阶除。","日月趣朝退，班衣侍婉愉。"]},{"t":"送贡士任善归丰城","f":"五言律诗","c":["妙龄兼令质，归省自京师。","为学功须倍，升荣计未迟。","岁时将暮矣，霜露亦凄其。","珍重关河道，高堂切尔思。"]},{"t":"题郑氏思亲卷","f":"五言律诗","c":["不忍杯棬饮，愁闻陟屺诗。","九原那复作，寸草恨难遗。","为养诚无及，行身庶可期。","灵椿百年寿，至乐罄吾私。"]},{"t":"章江刘先生挽诗","f":"五言律诗","c":["经术师承正，才名天分高。","閒情安野逸，雅操迈时髦。","百岁光阴远，诸生嘅慕劳。","章江庭馆外，逝水日滔滔。"]},{"t":"送东平傅知州复任","f":"五言律诗","c":["政成初北觐，考最复南征。","相逢遽相别，缱绻若为情。","露冷黄花老，天清锦树明。","吏民迎望切，慎莫滞双旌。"]},{"t":"题竹送贺宁知县之丰川","f":"五言律诗","c":["作宰丰川县，芳年际圣朝。","时清公事简，地僻瘴烟消。","抚字须勤职，驱驰莫惮遥。","匆匆斗酒别，聊复永今朝。"]},{"t":"送钱习传","f":"五言律诗","c":["迢递沧江路，天寒风雪深。","相知何在早，临别自难任。","人重昆冈玉，乡荣郤氏林。","为山终一篑，持赠比南金。"]},{"t":"汪氏慈训堂","f":"五言律诗","c":["早失过庭教，深依母氏恩。","持身在仁义，奉训切朝昏。","天地何由报，行藏矢弗谖。","慈颜千岁寿，春暖北堂萱。"]},{"t":"吴母挽诗","f":"五言律诗","c":["西风北堂上，白日黯春晖。","寂寂承欢处，尘封五色衣。","未终三釜养，遽动九原归。","女范传应在，闺门嗣不违。"]},{"t":"刘母挽诗","f":"五言律诗","c":["禄养人皆羡，兼荣母德贤。","空遗板舆在，竟负綵衣鲜。","吊鹤嗟何及，乘鸾望不旋。","恩封冀他日，光命贲重泉。"]},{"t":"萧母挽诗","f":"五言律诗","c":["日夕乌啼树，悲风起穗帷。","彩衣空五色，无复上堂时。","壸范嗟犹在，灵游不可知。","百年怀养者，长废蓼莪诗。"]},{"t":"春晖堂","f":"五言律诗","c":["早失趋庭训，深依徙舍恩。","踉蹡五色服，乐舞对春谖。","寿酒华觞进，安居绮席温。","持身务不辱，还究古人言。"]},{"t":"送乐舞生还闽中","f":"五言律诗","c":["清庙连丹阙，天坛接上台。","君王严祀礼，乐舞得仙才。","闽海三秋迥，云霄一鹤回。","飘然终散逸，还忆上蓬莱。"]},{"t":"题郭智宪使荣养堂","f":"五言律诗","c":["朝廷崇孝理，宪纪用儒臣。","分得乌台禄，归荣鹤发亲。","褒封承帝命，光彩焕龙文。","慈寿知方永，谖花百岁春。"]},{"t":"挽吴彦直","f":"五言律诗","c":["珠还合浦日，令尹擅廉明。","兴学皆从化，锄奸赫有声。","诗书传奕世，夷险任平生。","婉婉临终咏，闻之共怆情。"]},{"t":"赠尚书吕公挽诗 其一","f":"五言律诗","c":["清比蓝田玉，含辉故有馀。","乡人尊德义，世业重诗书。","渭水淹吟兴，莲峰对隐居。","百年皆过隙，不泯羡芳誉。"]},{"t":"赠尚书吕公挽诗 其二","f":"五言律诗","c":["瑞世生贤杰，登朝奉圣明。","身膺二品养，官赠六卿荣。","光宠真千载，遭逢自一经。","龙章照玉玺，褒拂极平生。"]},{"t":"示稻秫及昱","f":"五言律诗","c":["行年七十七，况复困沉疴。","世德流传远，天恩覆被多。","冉冉西颓景，骎骎东逝波。","诗书好承续，黾勉勿蹉跎。"]},{"t":"时勉学士升国子祭酒奉赠 其一","f":"五言律诗","c":["近侍踰三纪，文章柬掖垣。","冰霜存桧柏，廊庙荐玙璠。","帝重经筵旧，官升师道尊。","翩翩起车骑，相送向桥门。"]},{"t":"时勉学士升国子祭酒奉赠 其二","f":"五言律诗","c":["拜命彤廷日，龙墀瑞雪飞。","缙绅瞻有喜，寮采念相违。","时雨司成馆，天香学士衣。","斯文千载运，吾道有光辉。"]},{"t":"时勉学士升国子祭酒奉赠 其三","f":"五言律诗","c":["玉署东头阁，红扉昼不开。","衰龄馀我在，清论更谁来。","学者希传道，朝廷仗育才。","贤关有佳兴，时寄锦笺回。"]},{"t":"挽拙庵徐子信","f":"五言律诗","c":["行义时人重，才能邑里称。","系传高士远，家挹太湖清。","身世惊流电，朋游叹曙星。","从知郭有道，不愧蔡邕铭。"]},{"t":"赠佥事鲁希文","f":"古风","c":["自是天台秀，声名起绣衣。","八闽监海国，六月凛霜威。","考绩趋丹禁，承恩拜?闱。","从来冰檗操，吾道有光辉。"]},{"t":"示侄孙镛","f":"五言律诗","c":["念尔遽远别，送行无限情。","一心常体道，百行贵存诚。","海阔鹍鹏运，天寒冰雪清。","盛年当努力，莫让古人能。"]},{"t":"题竹赠陈文编脩","f":"五言律诗","c":["庐陵南望远，六十五长亭。","之子归宁日，重闱拜庆荣。","文章金榜贵，官秩玉堂清。","一幅湘皋赠，殷勤故郡情。"]},{"t":"题竹送李绍检讨","f":"五言律诗","c":["安成李克述，三岁在词林。","言色温如玉，操持坚断金。","君恩紫诰重，亲舍白云深。","万里归荣日，聊贻淇澳吟。"]},{"t":"寄顾都御史","f":"五言律诗","c":["翩然谢荣禄，林下乐天真。","台府留清望，朝廷忆老臣。","神情超物表，光彩动星辰。","俗辙何由到，长同园绮亲。"]},{"t":"雨后","f":"五言律诗","c":["炎天久不雨，数雨复还晴。","竹树繁阴合，阶墀幽草生。","闭门无俗事，散帙任閒情。","回首时西睡，芙蓉千叠清。"]},{"t":"庭树","f":"五言律诗","c":["手种庭前树，参差总出墙。","不须愁夏暑，已屡傲寒霜。","过雨纷交翠，因风亦度香。","如添清涧绕，即拟住山庄。"]},{"t":"暑中卧疴写怀 其一","f":"五言律诗","c":["坐卧连晨夕，中怀郁不开。","蝇攒眉上棘，蚊隐耳边雷。","无那惔焚困，生增褦襶来。","病咽兼患齿，两月废衔杯。"]},{"t":"暑中卧疴写怀 其二","f":"五言律诗","c":["白发垂垂老，丹心耿耿存。","毫丝无小补，天地有深恩。","病马长联皂，羸牛不驾辕。","蓬山望咫尺，惭负不胜论。"]},{"t":"示表侄陈纯","f":"五言律诗","c":["西江海桑老，冠冕重儒林。","我自外家学，尔求曾祖心。","诗书宜善继，尘俗莫容侵。","不见南山树，寸茎今百寻。"]},{"t":"送魏源尚书按视边务","f":"五言律诗","c":["宝剑动华星，关城候使旌。","春随司寇笔，霜重总兵营。","武备千年固，尘氛万里清。","归来奏天子，青史载鸿名。"]},{"t":"题梅寄傅知州","f":"五言律诗","c":["初入聊城县，遥闻郓守贤。","教先重芹泮，治不假蒲鞭。","吏牍清无滞，农田盛有年。","公馀多秀句，吟咏玉梅边。"]},{"t":"过济宁作","f":"五言律诗","c":["久发潞河棹，初经济水浔。","远山明晓黛，新柳动春禽。","恋阙云霄迥，怀乡岁月深。","君亲总恩重，来往并关心。"]},{"t":"舟中夜待弼侄不至","f":"五言律诗","c":["维舟喜相见，解䌫复相违。","江阔春潮满，云深夕月稀。","无眠成脉脉，延伫但依依。","寂寞蓬窗下，挑灯坐揽衣。"]},{"t":"入西江境","f":"五言律诗","c":["万里移归舠，东风谢绛桃。","烟迷彭泽柳，雪喷海门涛。","身世江湖老，君亲梦寐劳。","匡庐翠九叠，萧散白云高。"]},{"t":"归来","f":"五言律诗","c":["归来语向谁，白发故交稀。","满目亭台好，伤心俗化微。","慌迷携鹤径，惭过钓鱼矶。","童子何知我，犹嗤旧素衣。"]},{"t":"梦诸孙","f":"五言律诗","c":["绕膝戏诸孙，相看意独亲。","怜渠森似玉，对我浩生春。","已惜承欢浅，何堪入梦频。","亢宗吾望汝，莫遣愧荀陈。"]},{"t":"寄黄汝申宪使 其一","f":"五言律诗","c":["藩垣出岭表，宪节赴山东。","旧有先师化，行惟大道公。","百僚归表率，一志在瘝痌。","纲纪从容振，时来视頖宫。"]},{"t":"寄黄汝申宪使 其二","f":"五言律诗","c":["预想山东境，高才起颂声。","黔黎誇用恕，寮采荷推诚。","老柏霜逾劲，寒梅雪共明。","应同钟宪副，一力振澄清。"]},{"t":"五月六日早静海迤北大雨聊可苏旱","f":"五言律诗","c":["仰视月离毕，滂沱不待晨。","人心异昨日，物态总回春。","尚忆郊原遍，深思天地仁。","来牟已无及，回首一沾巾。"]},{"t":"直沽","f":"五言律诗","c":["城堞绕巍峨，城阴下九河。","水归东海近，人上北京多。","仓廪皆漕储，闾阎半负戈。","鱼盐十万户，何处有弦歌。"]},{"t":"过漷县望都门西山","f":"五言律诗","c":["东旭光芒起，西山紫翠分。","驰心向凤阙，仰首见龙文。","旆影高低出，钟声远近闻。","预将缨绂振，拟近玉炉薰。"]},{"t":"赠文玉主事","f":"五言律诗","c":["清高玉堂署，聚处岁年深。","心事澹于水，交情利断金。","衰龄各垂白，远道又分襟。","重会知何日，临岐惨不禁。"]},{"t":"送宋万中致事南归","f":"五言律诗","c":["白首遂辞荣，承恩出凤城。","故交推我老，远道念君行。","酒对黄花酌，帆随白雁征。","临岐记同学，惆怅不胜情。"]},{"t":"戴母挽诗","f":"五言律诗","c":["道路何屯塞，闺门著肃雍。","行宜君子配，恩拜孺人封。","妆閤间薰鸭，床帏惨暗蛩。","薇垣朝退食，举案属谁从。"]},{"t":"重寄澹庵","f":"五言律诗","c":["东观承恩地，俱看鬓雪侵。","别来春未暮，延伫夏将深。","忆我辞家日，知公恋阙心。","五伦书未奏，还待共披寻。"]},{"t":"慰时勉学士丧孙","f":"五言律诗","c":["承过西昌日，提携已识奇。","相随万里至，翻动九原悲。","岂是多时别，无深岁晏思。","与君俱此痛，排闷强裁诗。"]},{"t":"寒夕独坐乡思浩然有怀何文渊 其一","f":"五言律诗","c":["乡国云山外，衰年入梦勤。","经旬断杯酌，独夜对炉薰。","窃禄真惭我，论心每忆君。","许丞浑重听，时事不能闻。"]},{"t":"寒夕独坐乡思浩然有怀何文渊 其二","f":"五言律诗","c":["薄雪俄消瓦，惊风复撼窗。","蹉跎忽晏岁，寂寞伴寒缸。","病骨支难稳，愁心郁未降。","何由冰泮日，联棹溯西江。"]},{"t":"送袁本谦致仕归 其一","f":"五言律诗","c":["早岁从王事，迢迢促去骖。","十年留汉口，万里入滇南。","舟楫行应惯，弓刀力不堪。","昨朝新有旨，头白许抽簪。"]},{"t":"送袁本谦致仕归 其二","f":"五言律诗","c":["白下门前路，殷勤独送行。","楚山浮暮霭，淮树起寒声。","菰米香云饭，鲈鱼紫玉羹。","老年今有此，何异学长生。"]},{"t":"寄何文渊","f":"五言律诗","c":["忽复经年别，思乡趣不稀。","松筠还旧隐，山水溢清辉。","把钓银鲜滑，携镵紫蕨肥。","南归吾有日，访剡兴无违。"]},{"t":"送廖子谟贰守归河间","f":"五言律诗","c":["三载一相见，匆匆又别离。","荒年兼旱潦，圣主寄茕嫠。","刘毅才无敌，阳城道可师。","勋庸属贤俊，努力及明时。"]},{"t":"挽诗","f":"五言律诗","c":["乡里谈遗德，传流终未休。","甘依泉石老，不应栋梁求。","风树贻深感，云山徙故丘。","宪台忠孝在，宠赠被恩稠。"]},{"t":"送周仲规脩撰","f":"五言律诗","c":["恩拜龙头选，六年登禁闱。","暂辞金殿直，遥著锦衣归。","云净江天阔，潮平岛树微。","舟行足清景，诗思未应稀。"]},{"t":"送刘定之编脩","f":"五言律诗","c":["六载庭闱隔，常悬定省情。","自天膺宠命，即日戒归程。","人物金闺彦，才华玉署清。","承欢在有道，非但锦衣荣。"]},{"t":"任善得教谕于蜀辞行诗以勖之","f":"五言律诗","c":["典教除巴县，之官出帝畿。","也知轻道路，所乐近庭闱。","河岸杨花满，帆樯燕子飞。","相期传授暇，自省莫令稀。"]},{"t":"送别","f":"五言律诗","c":["相送复相别，花飞过却春。","朝廷屡考最，黎庶总归仁。","但倚丹心在，从教白发新。","崇文门外柳，折赠不辞频。"]},{"t":"题晋江何氏怡寿堂","f":"五言律诗","c":["圣代多耆寿，何家有凤毛。","谖明承日暖，椿老拂云高。","甘旨供天禄，欢娱艳赐袍。","庭闱介百岁，锦诰见华褒。"]},{"t":"送曹都御史","f":"五言律诗","c":["宠命膺边寄，天书焕紫泥。","九秋辞阙下，万里度关西。","著豸金横带，乘骢玉作蹄。","归朝奏成绩，光宠赐鞶犀。"]},{"t":"陈母挽诗","f":"五言律诗","c":["曾题南野墓，主孟复云亡。","八帙又三岁，诸孙泣满堂。","母仪乡里重，妇道族姻伤。","忍听门前树，乌啼惨夜霜。"]},{"t":"寄萧德迪","f":"五言律诗","c":["桃源萧德迪，苦志事题诗。","含咏常忘暮，抽思无倦时。","云边写素瀑，岩下发华芝。","万里劳相寄，聊酬青凤枝。"]},{"t":"题竹赠彭同知","f":"五言律诗","c":["分得筼筜谷，翛翛翠一竿。","曾闻裁作简，不假制为冠。","势接丹霄近，清宜白日看。","但保风霜操，相期历岁寒。"]},{"t":"题梅赠医士萧玄立","f":"五言律诗","c":["兰陵传谱系，两鬓雪霜侵。","医业过三世，仙方抵百金。","橘香苏氏井，杏艳董家林。","更着梅花好，光辉利济心。"]},{"t":"毛行人奉使江南便道省亲题梅花赠之","f":"五言律诗","c":["去乡六千里，念别思悠悠。","共是江南客，君乘使者舟。","折梅将远意，擢桂重名流。","捧檄升堂日，承欢慰白头。"]},{"t":"哭康甥孟嘉","f":"五言律诗","c":["提携二十载，羽翮已云飞。","眼见乘骢出，惊闻旅衬归。","素行元不忝，夙愿竟都违。","虽不多时别，能无涕泪挥。"]},{"t":"林佥宪斗山风木卷","f":"五言律诗","c":["青春艳绣衣，得禄更兴悲。","无复娱亲日，徒伤负米时。","迢迢桑梓恋，恻恻蓼莪思。","天地无穷极，难伸寸草私。"]},{"t":"重游东郭草亭","f":"五言律诗","c":["园亭风日好，邀客绮筵开。","重合金闺彦，兼联玉署才。","泉流经近席，花气拂深杯。","不断劝酬意，更堪弦管催。"]},{"t":"题梅赠萧雅容员外赴兖州知府","f":"五言律诗","c":["有美同乡彦，兹晨又别离。","光承宠命出，正及艳阳时。","抚字人皆望，操存我所知。","梅花故园意，持赠慰相思。"]},{"t":"题竹送雅容老友复任湖广布政聊寓折柳之意云","f":"五言律诗","c":["荣捧天恩出，都门雨散丝。","重临江汉上，深慰吏民思。","纯璞时稀识，贞松岁久知。","相逢即相别，聊赠凤凰枝。"]},{"t":"送刘习之","f":"五言律诗","c":["故人不可见，喜见子孙贤。","昨者义乌令，今来黄鹤仙。","芳春都市酒，新水北河船。","却忆萧方伯，分携又五年。"]},{"t":"挽翰林检讨廖敬先 其一","f":"五言律诗","c":["久重青云器，皆传白雪歌。","较文来棘院，承诏上銮坡。","家倚诗书富，人沾惠化多。","荒凉孤馆下，无处听鸣珂。"]},{"t":"挽翰林检讨廖敬先 其二","f":"五言律诗","c":["左掖门前路，朝回不共行。","竟违金殿直，虚梦玉楼成。","乡里思陈寔，君王失长卿。","同官悲永诀，掩泣送铭旌。"]},{"t":"送方御史往浙江诗","f":"五言律诗","c":["翩翩骢马出，遥赴浙河滨。","冰雪冲寒景，从知到及春。","清心持宪节，随事体皇仁。","履道由中正，相期继古人。"]},{"t":"挽韩本常 其一","f":"五言律诗","c":["勋德崇先代，山林乐隐居。","闭门逃宠禄，充栋有诗书。","流水心同净，浮云意共舒。","翛然随物化，千里见名驹。"]},{"t":"挽韩本常 其二","f":"五言律诗","c":["贤淑谐家室，升堂孝德齐。","一丘掩双璧，愁绝夜乌啼。","白日玄台暗，青山绿树迷。","显扬终有待，光映史臣题。"]},{"t":"挽禾溪乐仲韫","f":"五言律诗","c":["稀年德更稀，至孝奉慈闱。","子长皆知学，仓虚屡赈饥。","閒情松菊径，清代芰荷衣。","人往家规在，流传世有辉。"]},{"t":"送孙教授鼎还淞","f":"五言律诗","c":["吴淞孙郡博，如玉净无瑕。","学者皆心服，儒林誉孔嘉。","塞垣来白雁，河岸绽黄花。","又属匆匆别，题诗赠去槎。"]},{"t":"胡泉州朴斋","f":"五言古诗","c":["籍甚清源守，高斋近海滨。","依然如白屋，惟是表朱轮。","松竹论深契，诗书对古人。","吏民从尚质，风俗渐还淳。","治比刘宗正，歌传召信臣。","良哉二千石，时独见天真。"]},{"t":"洪处士挽诗","f":"五言古诗","c":["累叶诗书后，三山组绶门。","独看辞宠禄，清隐乐丘樊。","宾席高年重，州闾善行惇。","云中桂子出，天上凤毛鶱。","晚有南宫养，时倾北海尊。","将迎荣命下，先睹少微昏。","蕙帐惊秋鹤，萝扉惨暮猿。","生刍远莫致，哀些托空言。"]},{"t":"孝思堂为南安守作","f":"五言古诗","c":["故里高堂远，青山宰树蕃。","飞腾荣帝命，感激重亲恩。","宣化安诸邑，行春耀两幡。","抚时悲逸辙，临水叹深源。","定省晨昏急，声容梦寐存。","显扬须力致，表率在身敦。","郡赖为仁治，天将锡类繁。","圣朝崇孝理，终见表清门。"]},{"t":"送万资中赴南京大理寺副","f":"五言古诗","c":["万生吾郡秀，文学重乡评。","不媚难谐俗，无争亦让能。","盛时趋召命，累岁在承明。","书奏天颜悦，恩沾宠赐荣。","联班谢北阙，两骑赴南京。","齐鲁经游好，河山眺望清。","徘徊嘅往迹，倾写畅吟情。","议狱须推恕，持廉岂为名。","孜孜体帝德，勉勉骛王程。","公退如清暇，潜心向六经。"]},{"t":"题元端本堂所临宋徽宗芦雁图","f":"五言古诗","c":["惨淡穷阴日，萧条积雪时。","风含烟际菼，冰冱水中坻。","鸣应翻飞疾，栖兼饮啄宜。","临摹尽物理，点染妙天机。","无逸当年画，豳图七月诗。","望崇端本地，志异古人为。","绝艺功何补，为邦事可希。","不存前辙鉴，徒激后人悲。"]},{"t":"竹轩为徐以道赋","f":"五言古诗","c":["幽人乐种竹，竹生繁且妍。","垂云羃户外，映月摇阶前。","晴疑抗翠翿，风类鸣清弦。","夏来暑威薄，冬至寒节坚。","时携羊求侣，亦咏嵇阮篇。","即此适萧散，焉知尘俗牵。"]},{"t":"题竹为族孙挺","f":"五言古诗","c":["少年祗北觐，初命戒南驰。","虎踞石城壮，龙蟠钟阜奇。","国崇根本地，政肃纪纲司。","佐幕先修己，趋台自履卑。","小心勤职务，一意谨操持。","有过须知改，凡痾莫已医。","赴公恒起早，退食每归迟。","损友非吾类，前贤尽我师。","谦虚终受益，敖惰恐招危。","寡欲堪常乐，多营枉自疲。","勿贻君子贱，何畏小人嗤。","馀力披书卷，平时远酒卮。","夭桃朝暮色，贞桧雪霜姿。","永矢平生志，毋因薄俗移。","每虞端有道，万邑洁无私。","左右亲规诲，兴居视表仪。","顾余今潦倒，念尔远暌离。","行矣图树立，庶当光远期。"]},{"t":"送彝训致事","f":"五言古诗","c":["祖帐饯河桥，临分赠柳条。","凤池年岁久，薇省道途遥。","宦达垂三纪，恩深荷四朝。","丹心常耿耿，白发遽萧萧。","辞禄身无系，悬车兴自超。","人犹羡簪绂，我已向渔樵。","竹色涵书几，花香著酒瓢。","远归真足乐，高蹈竟难招。","羁旅怜同郡，分携重久要。","白驹如可系，聊复永今朝。"]},{"t":"宣府行营梦侍先师海桑先生","f":"五言古诗","c":["纯明程伯子，洒落邵尧夫。","世仰文章伯，人尊道德儒。","山川钟淑气，星斗焕高衢。","逸趣龙游海，光仪凤在梧。","卧云辞国聘，立雪盛门徒。","义合隆先祖，恩沾自早孤。","抠趋只影在，报施一尘无。","梦觉追畴昔，衾衣涕泪濡。"]},{"t":"寿吴氏母七十","f":"五言古诗","c":["盛德诗书后，慈闱节行全。","冰霜寒自洁，松柏晚逾坚。","孝有宗家说，贤因女教传。","春秋高八帙，鸾鷟晔双骞。","记日维华旦，瞻星丽碧天。","瑶池来阿母，珠翟俨群仙。","瓜枣千年熟，蟠桃五色鲜。","长生紫霞曲，歌舞乐琼筵。"]},{"t":"赠佘通府","f":"五言古诗","c":["圣代崇仁治，临民简俊英。","存心坚铁石，持行烱瑶琼。","吏蠹春冰净，公堂秋水清。","干求皆远迹，游惰亦趋耕。","光复山川色，兼涵草木荣。","还因扫螟螣，庶用育孤茕。","下邑今多幸，南州旧有声。","三年此相见，深慰别离情。"]},{"t":"同尤文度曹冀成院中夜饮联句","f":"五言古诗","c":["良朋枉惠顾，清霄集词馆。","久别念契阔，嘉晤谐燕衎。","维时属秋霁，展席面河汉。","辉辉月转阶，稍稍风侵幔。","菲薄陈豆登，绸缪缀篇翰。","才思茧丝抽，词彩珠玑粲。","语深香屡续，兴洽爵无算。","抚今诚可怡，感昔亦奚叹。","露白气逾肃，参高夜将半。","且共尽兹夕，坐待鸡鸣旦。"]},{"t":"静安亭诗沙溪刘伯川先生席上作时年十二","f":"七言律诗","c":["处士年将六十齐，作亭偏爱屋之西。","连床图史孙勤读，四壁棋琴客倦嬉。","鹅鼻峰高松鹤唳，鸡潭波静水禽啼。","向来翠竹江村路，弄月吟风醉不知。"]},{"t":"和伯阳池上梅花","f":"七言律诗","c":["扬州宅里旧看花，南楚频年不到家。","岁暮岂愁千里隔，雪残还对数枝斜。","閒临渌沼宜相映，略洗幽篁不谩遮。","綵笔清诗自堪赏，银瓶香酒讵须赊。"]},{"t":"奉和陆伴读元日雪中早朝韵","f":"七言律诗","c":["高阁馀钟已罢喧，绕廊明烛洞无昏。","墀中戒晓初排仗，殿上迎春正启门。","云气密含香缥缈，天花低舞雪翩翻。","当时授简推能赋，未数相如在兔园。"]},{"t":"和萧伴读秋夜有怀雷道夫时雷从朝京","f":"七言律诗","c":["北极迢遥直帝京，故人离阔渺脩程。","望随流月秋俱满，思触凉飔夜转生。","一派笳箫川上合，九重宫殿日边明。","从知谢眺怀西府，对景题诗并有情。"]},{"t":"次韵吴孟勤先生中秋有怀府中诸公并自和之作","f":"七言律诗","c":["桂花香满鹄山头，山下开轩称及秋。","月色纷当清斝落，凉风轻拂画檐流。","微微玉漏明河上，隐隐金门湛露浮。","为忆邹枚裁雅曲，连篇能倡复能酬。"]},{"t":"雷道夫随侍朝京还见示途中诸诗辄用奉柬","f":"七言律诗","c":["帝子趋朝归上国，儒臣随侍历脩程。","渌波不动听鼍鼓，白雁纷回避羽旌。","逦迤关河千嶂出，参差宫阙五云明。","非因此去游观乐，谁识当时赋颂声。"]},{"t":"舟泊匡庐次韵荅胡生","f":"七言律诗","c":["泊舟遥望匡庐寺，惟听微钟响曙撞。","日射紫烟霏滟滟，风飘高瀑洒淙淙。","常因来往怀香阁，未得登临蹑石矼。","时遇乡园文翰侣，又乘湖艇下双双。"]},{"t":"寄题贻厥堂 其一","f":"七言律诗","c":["南平郭里东西住，曾见名家六世来。","前辈风流皆寿俊，后人文采发英才。","春深栏槛云生竹，岁晚阶除雪映梅。","贻厥堂中最潇洒，四时清景隔浮埃。"]},{"t":"寄题贻厥堂 其二","f":"七言律诗","c":["堂前兰桂艳春荣，堂上衣冠老更清。","自倚诗书传世业，每持义利振乡评。","故家宦谱行当续，前代文章叠有声。","同学少年俱白首，几时相聚慰平生。"]},{"t":"送钟启晦南雄训导","f":"七言律诗","c":["试艺晨趋秘閤前，看君文采冠诸贤。","葩经早得尚书学，藻泮重登博士筵。","五月承恩辞北阙，一程冲暑向南天。","过家想见宁亲处，喜说梅关近赣壖。"]},{"t":"送康孔高","f":"七言律诗","c":["云南南望不须忧，千里零陵赴旧游。","复职亲承当宁命，过乡先慰倚门愁。","数家渔舍连江郭，尽日山光满郡楼。","博士到家多雅趣，弦歌声里度春秋。"]},{"t":"送李思益沐阳教谕","f":"七言律诗","c":["长乐疏钟应晓晴，千门杨柳动春莺。","重来拜命瞻龙阙，又促携书出凤城。","驿路看山经几处，县庠端笏见诸生。","十年一会还分手，未尽乡园间阔情。"]},{"t":"送永嘉秀才赴福宁教谕","f":"七言律诗","c":["博士承恩出九重，小车晨发凤台东。","遥知海道连乡郡，喜说山城有学宫。","雨过千家榕叶绿，秋清满县木犀红。","何幸明经逢圣代，须看扬铎振儒风。"]},{"t":"送王所存会昌训导","f":"七言律诗","c":["一棹之官路已赊，连天新涨更无涯。","遥看赣岭知何处，暂过文江喜是家。","县郭晴飞青嶂雨，讲堂秋对白鸥沙。","到家应际重阳节，清洒华筵粲菊花。"]},{"t":"送董海州","f":"七言律诗","c":["述职三回谒帝京，喜缘葭玉见深情。","退朝屡枉高轩过，儤直常孤倒屣迎。","淮浦落潮随去棹，海天凉露拂归旌。","伤心一掬鸰原泪，洒翰烦君寄楚城。"]},{"t":"挽李处士","f":"七言律诗","c":["不受遗金世共知，至今乡里系遐思。","贤郎已擢科名贵，太史新题孝友碑。","碧水园林违玩赏，青松丘垄閟容仪。","朝来晚翠堂前过，惟有家人哭素帷。"]},{"t":"和胡祭酒对雪韵","f":"七言律诗","c":["清旦同云閟彩霞，帝城又见雪飞花。","青林缀玉真看画，银沼分冰好试茶。","欲放剡舟乘逸兴，竞传郢曲到西家。","丰年有兆占三白，总觉新来喜气嘉。"]},{"t":"挽李孔目","f":"七言律诗","c":["词苑清华近禁闱，幕宾如子眼中稀。","庭无私谒惟看竹，官有閒时尽掩扉。","每喜枫宸同晓觐，忽惊薤露已朝晞。","凄凉南浦来时路，秋雨铭旌逐雁归。"]},{"t":"挽苏检讨伯厚","f":"七言律诗","c":["輀车晨发大江东，归葬闽山马鬣封。","千载交游悲坠露，百年心迹逐飘风。","空馀海内诗名在，无复朝端禁直同。","藉是词林知己旧，铭文光映九原中。"]},{"t":"送刘迪哲吉水训导","f":"七言律诗","c":["乡郡知名逾十载，初承荐剡谒彤闱。","李邕识面仍难遇，刘向传经喜得归。","腊雪浑飘征袂湿，江鸿遥逐去帆飞。","青春想见沾时雨，桃李花开映讲帷。"]},{"t":"送陈公馀赴高安训导兼柬本之","f":"七言律诗","c":["两家姻好托斯文，杨氏贤甥复有孙。","经学已能傅世业，儒官何幸拜君恩。","从知备养依微禄，且喜移家近故园。","还共郡庠梁博士，朝朝来往事清论。"]},{"t":"送许子谟博士归北京","f":"七言律诗","c":["邂逅京华岁欲阑，尊前论旧杂悲欢。","十年离别空相忆，万里驱驰只独难。","已喜骅骝归御厩，远随鸳鹭拜金銮。","明朝又过长淮去，玉雪纷纷扑马鞍。"]},{"t":"挽括苍樊处士 其一","f":"七言律诗","c":["早辞荐剡乐山居，荷芰纫衣草结庐。","欢奉慈颜登寿考，恩沾同气到遗孤。","秋云绕屋常看竹，夜月临轩或据梧。","惆怅佳城今郁郁，只应来往奠生刍。"]},{"t":"挽括苍樊处士 其二","f":"七言律诗","c":["黄金散尽为怜贫，芳誉流传满缙绅。","倒橐屡分行路客，买舟遥送望乡人。","少微云际冥冥色，棠棣原头寂寂春。","世泽不忘天道直，银台今睹凤毛新。"]},{"t":"送周茂才","f":"七言律诗","c":["盛世科名推小宋，故家孝弟重元方。","一春听雨同羁馆，千里看云忆旧乡。","淮水路边芳草合，桑园径里落花香。","到门五彩承欢处，遥想从容话玉堂。"]},{"t":"送晁司直景范致仕归济宁","f":"七言律诗","c":["春坊辅导集群英，清德多闻最老成。","天上归来投散逸，道傍祖送叹光荣。","圣朝雨露涵濡厚，晚节功名去住轻。","共羡行年今伏胜，遗经还待教诸生。"]},{"t":"题菊赠鹓侄","f":"七言律诗","c":["南望家山无尽情，衰年一病死兼生。","春风远道怜贤侄，夜雨他乡梦老兄。","千载诗书存世业，几家忠信重乡评。","从来明达安时命，珍重诸郎在矫轻。"]},{"t":"送尹自道","f":"七言律诗","c":["新安二守辞朝日，积雨初收暑顿轻。","秋尽平芜凉露满，月明长浦夕潮生。","片帆浩荡催行色，斗酒殷勤寄别情。","还有梅花可持赠，岁寒冰雪照同清。"]},{"t":"送胡孔时省亲丰县","f":"七言律诗","c":["遥瞻淮岫隔亲闱，初下钟陵过帝畿。","岂惮驱驰前路远，不禁消息近时稀。","渡江飞絮迎行棹，到县鲜桃艳舞衣。","慈父喜来慈母望，肯缘闻礼久忘归。"]},{"t":"袁中书升尚宝少卿其父同日受诰命桂脩撰索诗","f":"七言律诗","c":["早从潜邸识龙颜，白日青云翥翠鸾。","久典丝纶唐近职，又升符玺汉郎官。","全家父子光荣重，千载君臣际遇难。","帝德如天深化育，报恩须倚寸心丹。"]},{"t":"题梅寄刘仲兼老侄","f":"七言律诗","c":["故家遗泽根株盛，素蕊含香吐正齐。","雪后曾寻珠浦侧，春来先映白桥西。","十年去邑心相念，千里披图手自题。","珍重岁寒贞操在，水南清鹤待重携。"]},{"t":"次韵荅耐轩学士病中见寄","f":"七言律诗","c":["龙河初暖动春波，久病文园近若何。","知有官曹频问讯，自惭邻舍少经过。","茶香永夜分能数，诗句新年写渐多。","雪茧乌丝烦屡寄，閒烧红烛和清哦。"]},{"t":"得第二子","f":"七言律诗","c":["素蟾未满一分圆，正照垂弧竹下门。","因报添丁徵近梦，翻悲生我重慈恩。","箕裘倘解传弓冶，水木端期继本源。","百世奉尝今日始，敢伸虔告荐蘋蘩。"]},{"t":"樊通政守一斋","f":"七言律诗","c":["众万之源纯不杂，还因表字揭斋名。","已知要道无岐路，所贵专心事笃行。","大学工夫由主敬，古人勋业自存诚。","始终表里恒无失，此是斋中座右铭。"]},{"t":"送熊昱御史","f":"七言律诗","c":["故家文献驱前代，金榜科名起圣朝。","宪府飞霜持白简，绣衣炫日近丹霄。","归程万里秋随雁，挂席三山晓带潮。","春酒还家酌萸菊，高堂眉寿等松乔。"]},{"t":"次韵袁止安太常南归留别","f":"七言律诗","c":["文雅人推贺监贤，承宣数近九重天。","优閒有幸沾荣命，宠禄无心及暮年。","自斸紫芝充服食，閒骑白鹿傍云泉。","挂冠神武谁无意，迟我洪厓玉笥边。"]},{"t":"送兖州郡学教授","f":"七言律诗","c":["兖府诸生久待师，广文新去拥皋比。","閟宫旧有周公祀，泮水今传鲁国诗。","清泗流源千古在，尼丘佳气五云微。","讲馀时出城东郭，瞻仰从知重所思。"]},{"t":"送尹御史","f":"七言律诗","c":["久住南京共接邻，北京为别已经春。","每怀乡邑疏欢聚，又向都门送故人。","万里云霄雕翮健，九苞文采凤毛新。","一身上有君亲望，珍重芳名在缙绅。"]},{"t":"挽彭处士","f":"七言律诗","c":["溪园脩竹映桃花，负郭幽居逸趣赊。","自惜世家存礼乐，时过邻曲看桑麻。","堂馀素简人何在，墓绕青山世共嗟。","因读铭文思往事，感怀况是旧通家。"]},{"t":"送陈素行","f":"七言律诗","c":["去年相别萧藤县，此日重看博士行。","桂岭迢遥怀二俊，榕阴潇洒对诸生。","雨肥丹荔浆堪挹，霜下黄茆瘴已清。","知有少游文字在，倘摹遗刻寄都城。"]},{"t":"黄友文教授解官归建宁","f":"七言律诗","c":["京华十载托邻居，朝夕相从意不疏。","屡接宾筵同唱咏，静闻师馆授诗书。","青云倦翮能辞宠，白首閒情乐遂初。","一片烟霞人境外，幅巾萧散有谁如。"]},{"t":"追送江仲隆纪善兼寄罗思程博士 其一","f":"七言律诗","c":["来朝京国遂悬车，老去王门罢曳裾。","白发苍颜归旧里，青山红树托幽居。","閒穿竹径行携鹤，更傍荷塘坐看鱼。","道在未应全散逸，诸生须授伏生书。"]},{"t":"追送江仲隆纪善兼寄罗思程博士 其二","f":"七言律诗","c":["京华相忆几经春，颇恨重来不问人。","行馆空寻深巷曲，归舟先发大河滨。","到家闾里争迎劳，避俗林泉近隐沦。","想共湖西罗博士，小车来往似荀陈。"]},{"t":"送陈文璧赴石首知县","f":"七言律诗","c":["金榜青春有令名，玉堂高步接群英。","爱民自倚平生志，作县新承宠命荣。","蓟北霜清寒木落，岳阳烟净晚山横。","六年相聚还相别，不尽秋风送客情。"]},{"t":"送陈彝训赴湖广参议","f":"七言律诗","c":["三十年前过鄂城，藩垣吴郑最知名。","人怀遗爱至今日，子继贤声在此行。","梦渚茫茫连汉沔，岳阳渺渺望荆衡。","九重夙夜思民瘼，应展忠勤荅圣明。"]},{"t":"会稽章友让半村居","f":"七言律诗","c":["半山亭子江南畔，又说幽居擅半村。","十里松阴隔城郭，几家茅屋接田园。","朝闻鸿雁琴中落，秋对芙蓉镜里繁。","投老他年定相觅，欲寻禹穴访云门。"]},{"t":"送刘公潜郁林知州","f":"七言律诗","c":["万里边南望郁林，故人五马去骎骎。","传家自昔春秋学，用世平生冰檗心。","岐路寒风惊岁晏，衰年短鬓各霜侵。","朝来相送都门外，矫首云鸿思不禁。"]},{"t":"挽周孟简长史","f":"七言律诗","c":["翰苑飞腾二十春，同乡同署更情亲。","灯前对酒觥筹数，竹里联诗兴韵新。","梁苑延枚心不展，湘江吊屈叹何频。","俄闻瘗玉桑园上，老泪潸潸为故人。"]},{"t":"送袁尚宝","f":"七言律诗","c":["把酒临分惨不骄，嗟君此别渐难招。","交游托好踰三纪，近侍联班及四朝。","赐服晓沾天阙露，归帆秋带浙江潮。","白云沧海东鄞道，矫首冥鸿怅望遥。"]},{"t":"送刘丕武纪善致事","f":"七言律诗","c":["白首王门懒曳裾，青山归去爱吾庐。","天恩已赐双龙敕，家计犹存万卷书。","林下栖迟芝可茹，泉头来往鹿随车。","蹇予苦被浮名系，矫首看君愧未如。"]},{"t":"寄袁止安","f":"七言律诗","c":["十年不见袁高士，知在云山若个边。","已识道心尘外净，少将仙篆世间传。","秋清白鹤下珠树，春暖华芝长玉田。","早晚归来访真馆，晴窗共阅紫霞编。"]},{"t":"送本之赴鲁府纪善","f":"七言律诗","c":["泗水尼山天下名，衣冠何幸此中行。","云浮海岱苍茫合，树接青徐缥缈清。","圣主惇亲过文帝，贤王为善继东平。","碧堂赐醴多恩遇，全胜长沙著贾生。"]},{"t":"寄胡祭酒 其一","f":"七言律诗","c":["豫章先生厌轩冕，归来物外托閒身。","青山江上迢迢郭，碧树泉头淡淡春。","岁暮丹砂和玉屑，日长羽扇映纶巾。","城中冠盖多如雨，解识尧夫有几人。"]},{"t":"寄胡祭酒 其二","f":"七言律诗","c":["渺渺南州属望劳，玉堂金马旧同袍。","篇章富拟杜工部，才思清于何水曹。","京国几年嗟间阔，江村何日共游遨。","古来同舍多秦越，最忆先生独处高。"]},{"t":"存仁堂","f":"七言律诗","c":["肘后名方直百金，越人带下业精深。","功多为有江湖迹，世远皆存天地心。","橘叶香浮苏氏井，杏花春蔼董家林。","凤楼东畔新堂构，大扁光华众所钦。"]},{"t":"题竹送顾都御史还太康 其一","f":"七言律诗","c":["腰佩犀鞶首廌冠，肃将风采振台端。","心如明月涵秋水，操比清冰凛夏寒。","凤敕五文盘玉玺，龙光千载出金銮。","从来嵩洛多耆寿，坐绕琅玕共岁寒。"]},{"t":"题竹送顾都御史还太康 其二","f":"七言律诗","c":["潞渚初晴涨未消，衣冠祖饯出河桥。","登名科第踰三纪，奉职京华已四朝。","肯以暮龄孤宠禄，永怀幽兴在渔樵。","岂知衰疾淹留者，怅望冥鸿不可招。"]},{"t":"送陈正伦太守考绩复任","f":"七言律诗","c":["久别南阳陈太守，十年犹是旧青袍。","路人共说循良政，荒岁深知抚字劳。","白发交游吾最老，青云勋业子能高。","明时有志应须奋，九万扶摇看羽毛。"]},{"t":"题熊尚初经历茂恩堂","f":"七言律诗","c":["五花金诰出金门，白发庭闱拜帝恩。","当宁褒词明日月，全家庆泽戴乾坤。","椿阴谖彩晴逾好，桂馥兰馨暖更繁。","乌府幕中何以报，只应忠孝道弥敦。"]},{"t":"寄王格非","f":"七言律诗","c":["玉堂分手七年馀，萧散林泉乐遂初。","乡里共高王烈行，家庭常授伏生书。","穿云采药常携鹿，傍水持竿亦钓鱼。","南北相望六千里，一缄聊用慰离居。"]},{"t":"送清河尹","f":"七言律诗","c":["家住澄江北渚滨，清朝兄弟起彬彬。","同时作宰辉双璧，异县能官见几人。","采采黄花滋夕露，萧萧白雁度秋旻。","相逢未久还相别，珍重声华在缙绅。"]},{"t":"送吕大理致仕兼寄王孟坚","f":"七言律诗","c":["得谢青云向白云，绯袍象简拜天恩。","从来荣宦心如水，况是名家学有源。","日对沃州兼禹穴，时寻兰渚及云门。","往还知共王脩撰，几杖从容足细论。"]},{"t":"潘赐主事升鸿胪少卿赴南京","f":"七言律诗","c":["紫泥诏下九重天，曾向榑桑海外宣。","使者旌旗轻万里，郎官词赋欲千篇。","归朝已荷君王宠，进职今推近侍贤。","应到南京公事简，朝朝清趣在韦编。"]},{"t":"沈处士夫妇挽诗","f":"七言律诗","c":["临安处士休文后，萧散春秋七十馀。","荒岁恤人频发廪，平生爱子只收书。","眼看兰茁森如玉，身着荷衣乐饭蔬。","同德相辉更同穴，后来凭轼有高车。"]},{"t":"题竹酬正安友","f":"七言律诗","c":["别去京华今十载，仰高堂上趣如何。","曾孙近有含饴乐，使客频闻舣棹过。","坐对匡庐延爽气，门临彭蠡挹清波。","陶公祠里春秋社，醉看传芭舞且歌。"]},{"t":"送袁旭知府复任","f":"七言律诗","c":["三年奏最谒彤闱，五马翩翩又赋归。","风撼长河冰欲合，霜凋连树叶分飞。","从知辛苦苏民瘼，富有声名出帝畿。","坐对敬亭公事简，吟诗还似谢玄晖。"]},{"t":"题周孟德淳斋卷","f":"七言律诗","c":["性情澹澹葛天民，斋舍清幽迥绝尘。","玄酒大羹忘世味，閒云流水任天真。","农谈暇日同邻叟，经训当年对古人。","岂有机心到机事，青松翠竹四时春。"]},{"t":"送况伯律太守","f":"七言律诗","c":["还捧天书辞玉陛，东风五马去悠悠。","十年不愧赵清献，七县重迎张益州。","杨柳翠迷湖上寺，杏花红映水滨楼。","到官正及劝农日，郊郭歌谣拥道周。"]},{"t":"题竹寄陈有戒都宪","f":"七言律诗","c":["关塞秋风霜叶飞，又闻跨马出边陲。","多卿为国忘劳瘁，老我怀贤惜别离。","万里屡勤鸿雁信，一缄遥荅凤凰枝。","保民有志坚如石，想见西人载路碑。"]},{"t":"送广西佥事黄孟清","f":"七言律诗","c":["昭代光华起一经，手提文印广西行。","三年宦绩看书最，八桂人才属有成。","白简重辞金阙去，黄花纷映绣衣明。","相逢乍语还相别，勉尽忠诚答圣情。"]},{"t":"吴廷用侍郎挽诗","f":"七言律诗","c":["十载南京住接邻，北京相与更情亲。","朝端恩宠升官数，江上贤劳奉使频。","圣主亲垂君子誉，近臣谁复古人真。","分携未久遄闻讣，感悼题诗泪满巾。"]},{"t":"送吕从周平江教谕","f":"七言律诗","c":["荆岳东西路不赊，数程来往洞庭沙。","承恩典教重辞阙，得禄娱亲喜近家。","江上夜虹书棹远，津头春树酒旗斜。","从知子佩趋迎日，玄燕将雏柳正花。"]},{"t":"送张敏赴四川都司经历","f":"七言律诗","c":["同是青原郡里人，京华邂逅最情亲。","贤关出拜君前命，帅阃行充幕下宾。","万里桥边连远徼，九江城外溯通津。","临期无奈匆匆别，矫首飞蓬各怆神。"]},{"t":"寄金文鼎","f":"七言律诗","c":["锦袍新照鬓毛斑，归住吴淞三泖间。","天上已颁金诰重，林中不遣绿尊閒。","画图世儗王摩诘，词赋人高庾子山。","无限离情写相寄，明年春雁待书还。"]},{"t":"送干子楫中书谢恩还新淦","f":"七言律诗","c":["万里趋朝上九关，紫宸前殿谒龙颜。","天章已赐封官敕，雪鬓荣看衣锦还。","淮上春波连碧草，湖边晴黛拥青山。","他时归老须相觅，知在金川玉笥间。"]},{"t":"送进士赴南京刑部主事","f":"七言律诗","c":["一经登第拜金銮，六品升朝授好官。","自昔有家依帝阙，即今得禄奉亲欢。","英年郎署丹霄近，圣代秋官白昼寒。","立志长同冰雪厉，扶摇万里恣鹏抟。"]},{"t":"送郭鼎贞致仕还临江","f":"七言律诗","c":["郎官为政清如水，旧有清名远近闻。","天上拜辞丹凤阙，江南还觅白鸥群。","夫容杨柳零秋露，彭蠡匡庐渺暮云。","无数归帆背人去，不禁乡思日纷纷。"]},{"t":"送吕仲贤赴南京户部主事","f":"七言律诗","c":["柳色含金春正融，御沟冰泮玉波通。","读书有志逢千载，承命之官拜九重。","河上好山连济北，淮南佳气望江东。","朝廷邦赋存恒典，能秉廉勤亦是忠。"]},{"t":"题竹赠王澄渊归","f":"七言律诗","c":["握手临分思不禁，都门十日雨涔涔。","荒州远邑存遗爱，蜀岭黔江见越吟。","万里客途堪白首，三朝臣节只丹心。","清风潇洒安成郭，未许投閒坐竹林。"]},{"t":"送王邦彦大理归蜀","f":"七言律诗","c":["春坊二十馀年旧，此日同朝见几人。","老我论思愧臣职，多君谳议副皇仁。","西风岐路明红树，秋渚离情对白蘋。","万里天恩荣昼锦，到家应及岁华新。"]},{"t":"题何太守画","f":"七言律诗","c":["宜阳太守弹琴处，潇洒苍筠白石妍。","半夜波涛乱春雨，一拳苔藓出晴烟。","郡中旧有房韩政，林下那无白阮贤。","直节看渠清似玉，姓名琬琰后宜镌。"]},{"t":"送清河知县","f":"七言律诗","c":["当宁仁民秉至诚，濒淮今岁少丰登。","忧勤屡下明廷诏，抚字深资令尹能。","共爱温如玄圃玉，直须清比鉴池冰。","清河未必长淹骥，云路他年看尔升。"]},{"t":"胡祭酒宅秋菊盛开仆携酒就赏胡有诗因次其韵 其一","f":"七言律诗","c":["庭菊芬芳五色并，每因来看得怡情。","共怜羁旅增多病，太息交游减旧盟。","万事不如閒处乐，一樽聊就故人倾。","爱花欲种嗟无地，凭有清诗为借赓。"]},{"t":"胡祭酒宅秋菊盛开仆携酒就赏胡有诗因次其韵 其二","f":"七言律诗","c":["秋风客里百愁并，春雨江南万里情。","时序未忘黄菊兴，江湖犹梦白鸥盟。","况于衰病淹留际，岂有襟怀浩荡倾。","何怪相过旧同舍，一觞易醉句难赓。"]},{"t":"寿蹇少卿 其一","f":"七言律诗","c":["先皇亲制忠贞号，甲第新开宠更深。","周倚仲山能补衮，商需傅说解为霖。","春筵的皪梅舒玉，寿斝芬芳醴泛金。","圣代文臣公第一，承恩堂上盍华簪。"]},{"t":"寿蹇少卿 其二","f":"七言律诗","c":["天上星光照锦袍，满堂春色醉仙桃。","燮调四序勋庸盛，辅翼三朝德望高。","咸使华夷慕丰采，屡膺纶綍重华褒。","不才谬忝夔龙后，惟祝南山酌翠涛。"]},{"t":"寿建安少傅 其一","f":"七言律诗","c":["两扶红日上青天，盛有高名海外传。","黼黻鸿猷才胜锦，发挥龙诰笔如椽。","三朝并倚忠勤德，二气还需燮理贤。","九曲武夷尘境外，功成归作地行仙。"]},{"t":"寿建安少傅 其二","f":"七言律诗","c":["每挹天瓢润九区，蓬山高处领文儒。","梅花献寿作香雪，竹叶迎春开翠壶。","阙下引回鸳鹭侣，堂中看舞凤凰雏。","同官同姓同清健，应数耆英笑老迂。"]},{"t":"连景贤脩撰南归书此识别","f":"七言律诗","c":["万里闽关边岭海，送归晓发道傍车。","暂辞金马玉堂直，久忆丹山碧水居。","雁影将秋先驿骑，桂香含露袭衣裾。","到家想及寒梅节，觞酒花前会里闾。"]},{"t":"从游西苑 其一","f":"七言律诗","c":["宫城西畔接蓬莱，金饰飞楼玉饰台。","辇路前瞻双凤引，銮舆中驾六龙来。","时康道泰韶音奏，雪净天清瑞景开。","何幸群臣皆侍从，山呼捧献万年杯。"]},{"t":"从游西苑 其二","f":"七言律诗","c":["太液丹霞漾绿波，荣光五采贯银河。","牙樯锦缆移黄伞，凤羽龙旓拂翠荷。","武士威随严卤簿，儒臣歌颂续卷阿。","天王万岁天同寿，岁岁升平乐事多。"]},{"t":"从游西苑 其三","f":"七言律诗","c":["壶洲阆苑五云迷，紫殿彤楼众岫低。","日射飞甍金署榜，虹连閤道玉为梯。","流觞宛转清波送，赐扇煇煌御墨题。","欲报宠恩何以祝，皇图帝寿与天齐。"]},{"t":"寄宗豫","f":"七言律诗","c":["翰苑同袍三十载，忧欢何事不相联。","论思无补惭予甚，经济多能忆子贤。","竹簟茅檐宜晚岁，白云沧海别经年。","閒居未用浑忘世，尚想题诗到日边。"]},{"t":"送罗知州之广德","f":"七言律诗","c":["金殿传胪起一经，青春为郡引双旌。","晴瞻岱岳连齐甸，晚带淮潮过楚城。","千里桑麻相映绿，诸生弦诵有馀清。","州侯旧说孙莘老，想见怀贤系远情。"]},{"t":"和胡祭酒见寄韵 其一","f":"古风","c":["自昔襟怀淡荡春，老来幽趣更清新。","竹门松巷閒临水，书几琴床夐绝尘。","归隐已无青?梦，交游时念白头人。","黄庭一卷消长日，座有云山未当贫。"]},{"t":"和胡祭酒见寄韵 其二","f":"七言律诗","c":["分携又是十经春，喜见文章刻布新。","不待黄金论高价，共怜白璧净纤尘。","赓歌每忆同中禁，名姓频看慨故人。","国有贤王重耆彦，从知道在不忧贫。"]},{"t":"次韵行俭移居 其一","f":"七言律诗","c":["移住城西半亩宽，接邻俱是旧交欢。","中朝文采推王粲，别墅风流儗谢安。","应似诗人歌伐木，会筵嘉客醉焚兰。","新居更为长年祝，玉屑云英好试餐。"]},{"t":"次韵行俭移居 其二","f":"七言律诗","c":["移住城西半亩宽，喜于幽处托盘桓。","九苞威凤人争识，五色华芝世共看。","流水清弦閒屡奏，秋风长铗未须弹。","也应晏岁劳相慰，却愧阳春和独难。"]},{"t":"次韵行俭移居 其三","f":"七言律诗","c":["移住城西半亩宽，閒居萧散欲忘官。","邻园树色青连屋，露井苔痕碧映阑。","东观有书秋后校，西山如画雨馀看。","同乡同客兼同调，日日过从得共欢。"]},{"t":"次韵行俭移居 其四","f":"七言律诗","c":["移住城西半亩宽，相过邻曲尽衣冠。","南州文物终存古，北地风霜屡涉寒。","万里能无乡井意，数家相倚客居安。","匏壶载酒閒常会，竹笥藏书也易干。"]},{"t":"送王筹","f":"七言律诗","c":["不见青城十五年，春宫曾共侍经筵。","早乘鹤去归三岛，应从龙游近九天。","海内朋俦悲益减，客中岁月苦频迁。","秋风又与王郎别，为话高堂重惘然。"]},{"t":"寄题旴江郑氏隆寿堂","f":"七言律诗","c":["与君俱住西江上，往往清名听客传。","六十生年同甲子，寻常行乐似神仙。","厨供吏部曹中禄，酒酿麻源谷里泉。","盛世天恩锡隆寿，龙光长照绮筵前。"]},{"t":"奉敕㳟谒皇太子谢恩诗","f":"七言律诗","c":["华夷一统戴洪恩，庆衍皇家万万春。","总为太平隆景运，正生仁圣福斯民。","德如文武成康继，世沐乾坤雨露新。","龙凤之姿天日表，大明高祖圣玄孙。"]},{"t":"送王秉逊侍郎归益都","f":"七言律诗","c":["爱子儒林冰玉清，大廷文选佐持衡。","昔闻天语曾称孝，久侍经帷只用诚。","恩命已沾鸾诰重，乡人今看锦衣荣。","况逢青社烟氛净，共感皇仁说治平。"]},{"t":"午醒閒述","f":"七言律诗","c":["边方喜迓翠华来，风扫飞烟雨浥埃。","日暖营门喧鼓吹，秋清庐帐引尊罍。","诸公并有平戎策，贱子惭无奏赋才。","忽听六军传好语，龙舆今已办东回。"]},{"t":"怀柔旅次","f":"七言律诗","c":["古树萧条荫县门，县前民舍似山村。","何如荒歉频年后，犹有承平旧俗存。","爱客别延林外馆，多情还倒炕头尊。","不徒行役能相慰，兼复诗书可共论。"]},{"t":"归至清河","f":"七言律诗","c":["二月随銮三月归，近瞻城阙五云飞。","桃蹊深浅红相间，麦垄高低绿渐肥。","出郭故人期载酒，迎门稚子候牵衣。","登山临水多高兴，未抵抽毫侍禁闱。"]},{"t":"寄寿胡祭酒七十","f":"七言律诗","c":["八年不见颐庵面，楚树燕云思独悬。","宝气常腾山浦上，文光高烛斗牛边。","绿尊酒共幽人酌，锦字诗从过客传。","七十韶华还七十，重新甲子记流年。"]},{"t":"元宵侍宴万岁山 其一","f":"七言律诗","c":["綵映鳌山近紫霄，王正嘉节属元宵。","九衢星斗珠灯灿，一统乾坤玉烛调。","处处阳和融动植，家家欢乐合笙箫。","臣民仰戴君恩泽，万寿齐天祝帝尧。"]},{"t":"元宵侍宴万岁山 其二","f":"七言律诗","c":["宝炬华缸潋滟红，参差回合粲夫容。","九重殿上春先到，万岁山前月正中。","天意总看新岁好，圣情乐与兆民同。","频年边壤氛埃净，况是田畴稼穑丰。"]},{"t":"元宵侍宴万岁山 其三","f":"七言律诗","c":["帝德承天景运新，三阳开泰布和春。","典章礼乐隆昭代，玉帛梯航聚远人。","致乐天伦承圣母，均恩海宇霈皇仁。","太平元夕仙韶奏，率舞跄跄总凤麟。"]},{"t":"元宵侍宴万岁山 其四","f":"七言律诗","c":["大地山川明景象，连城灯火照笙歌。","月当华盖杠前好，春在蓬莱顶上多。","凤阙光辉含瑞霭，龙河浩荡溢恩波。","时平幸遇唐虞主，圣德无为保泰和。"]},{"t":"元宵侍宴万岁山 其五","f":"七言律诗","c":["诏书已下息黎元，远迩欢忻戴颂言。","节序适逢端正月，阳春偏感圣明恩。","三山瑞彩明黄道，五纬华星绕紫垣。","敬效嵩呼祝当宁，太平天子万年尊。"]},{"t":"送曹都御史赴丼州","f":"七言律诗","c":["绣衣骢马引双旌，手捧纶章出帝城。","满路桃花飞乳燕，夹堤杨柳带流莺。","关西旧识霜威肃，塞上今传氛祲清。","昭代有才当显用，会看竹简记勋名。"]},{"t":"寄杨寿夫","f":"七言律诗","c":["七十年华两鬓霜，九重恩旨赐还乡。","脩成国史登金匮，归去官衔带玉堂。","碧水丹山从散策，春兰秋菊对浮觞。","别来缱绻怀君子，故写琅玕远寄将。"]},{"t":"欧阳员外归省以山水画索题","f":"七言律诗","c":["去春我过蜀江曲，今春尔望蜀江归。","六一宗家有馀庆，椿庭萱砌交晴辉。","旨丼犹是秋官禄，绣锦新裁莱子衣。","一幅萧閒乡闾趣，白头相送念相违。"]},{"t":"送柴尚书归浙江","f":"七言律诗","c":["万里胡氛汎扫清，中台新拜夏官卿。","平生节比秋霜劲，此日光添昼锦荣。","乡国几人乘传入，江亭八月看潮生。","钱塘蟹熟鲈堪脍，谁共芳醪白玉觥。"]},{"t":"喜雨诗","f":"七言律诗","c":["好雨连朝苏久旱，无边喜意动宸衷。","皇天洞鉴圣仁德，臣子深惭燮理功。","每念升平均九土，已知舞蹈出三农。","骈繁宠锡身难报，何幸衰年际屡丰。"]},{"t":"送王日初","f":"七言律诗","c":["抚州太守温如玉，自昔论交在两都。","壮岁文章看擢桂，明时勋业遂分符。","临川野外春风满，华盖峰前皓月孤。","邂逅相欢又相别，天寒冰雪柰长途。"]},{"t":"送赵侍郎巡抚江西","f":"七言律诗","c":["圣主龙飞矜下土，天官鹄立侍彤庭。","九重北面承亲命，一道西江仰福星。","吏治还应察泾渭，农田须用去蝗螟。","使车所过从容驻，留取丼棠久远青。"]}]};